const { regClass } = Laya;
import GameLanguageMgr from "../../common/GameLanguageMgr";
import GameResourceManager from "../../common/GameResourceManager";
import { ModuleManager } from "../../common/ModuleManager";
import { ItemItem } from "../../data/sheetItem/item/ItemItem";
import { ModuleName } from "../../global/ModuleName";
import { NftItemBase } from "./NftItem.generated";
import { com } from "../../network/pb/socket";
import HallWebSocket from "../../network/HallWebSocket";
import { SceneType } from "../../common/baseScene/SceneType";
import SceneManager from "../../common/SceneManager";
import SheetDataManager from "../../global/SheetDataManager";
import Signal from "../../global/event/Signal";
import GlobalDataManager from "../../global/GlobalDataManager";
import { SocketDataUtil } from "../../utils/SocketDataUtil";
import NoticeMgr from "../notice/NoticeMgr";

@regClass('GyHLyzIaRva11NfPDbiBfw==')
export class NftItem extends NftItemBase {
    public nftItem: any;

    public constructor() {
        super();
    }
    onEnable(): void {
        this.btn_upgrade.on(Laya.Event.CLICK, this, this.toUpGradeDialog);
        this.btn_battle.on(Laya.Event.CLICK, this, this.onBattleClick);
    }

    onDisable(): void {
        this.btn_upgrade.off(Laya.Event.CLICK, this, this.toUpGradeDialog);
        this.btn_battle.off(Laya.Event.CLICK, this, this.onBattleClick);
        this.box_emply.off(Laya.Event.CLICK, this, this.toShopScene);
        this.btnBg.off(Laya.Event.CLICK, this, this.showDetail);
        Signal.off("msg_" + com.snake.socket.MessageType.MSG_SNAKE_FIGHT, this, this.onBattleCallback);
    }

    public set dataSource(value: any) {
        super.dataSource = value;
        if (!value) return;

        // 判断是否为特殊的商城入口数据
        if (value.isShopEntry) {
            // 显示商城入口组件，隐藏普通NFT组件
            this.box_emply.visible = true;
            this.box_nft.visible = false;

            // 为商城入口组件添加点击事件
            if (!this.box_emply.hasListener(Laya.Event.CLICK)) {
                this.box_emply.on(Laya.Event.CLICK, this, this.toShopScene);
            }
            return;
        }else{
            this.btnBg.on(Laya.Event.CLICK, this, this.showDetail);
        }

        // 正常NFT数据处理
        this.box_emply.visible = false;
        this.box_nft.visible = true;
        this.nftItem = value;
        let itemItem: ItemItem = SheetDataManager.m_dicItems.get(this.nftItem.id);
        this.tf_name.text = GameLanguageMgr.getLanguage(itemItem.name);
        this.img_icon.skin = GameResourceManager.getSnakeIcon(this.nftItem.skin || 101);
        
        // 检查蛇是否已经升级过 - 使用可选链安全访问attr属性(替换成升级属性)
        const hasUpgraded = !this.nftItem.upgrade;
        this.btn_upgrade.visible = false;

        let isBattle = GlobalDataManager.playerDto.snakeId == this.nftItem.unkey;
        this.Img_battleState.visible = isBattle;
        this.btn_battle.visible = !isBattle;

        // 更新按钮位置
        // if (hasUpgraded) {
        //     // 已升级过，不能再升级，只显示战斗按钮
        //     this.btn_battle.x = 58;
        // } else {
        //     // 未升级过，可以升级
        //     this.btn_battle.x = 6;
        //     this.btn_upgrade.x = isBattle ? 58 : 111;
        // }
    }

    private toUpGradeDialog() {
        ModuleManager.intance.openModule(ModuleName.SnakeUpgradeDialog, this.nftItem);
    }

    private onBattleClick() {
        if (!this.nftItem) return;

        const cmdId = com.snake.socket.MessageType.MSG_SNAKE_FIGHT;
        // 注册回调函数
        Signal.off("msg_" + com.snake.socket.MessageType.MSG_SNAKE_FIGHT, this, this.onBattleCallback);
        Signal.on("msg_" + com.snake.socket.MessageType.MSG_SNAKE_FIGHT, this, this.onBattleCallback);

        const requestData = com.snake.socket.CS_SNAKE_FIGHT.fromObject({
            unkey: this.nftItem.unkey
        });
        HallWebSocket.send(cmdId, requestData);
    }

    private onBattleCallback(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        // 移除监听，避免多次调用
        if (msgcode == com.snake.socket.MessageCode.SYS_NORMAL) {
            var msgBody: com.snake.socket.CS_SNAKE_FIGHT = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.CS_SNAKE_FIGHT);
            console.log(msgBody);
            NoticeMgr.notice(GameLanguageMgr.getLanguage(75));
            GlobalDataManager.playerDto.snakeId = msgBody.unkey;
    
            Signal.off("msg_" + com.snake.socket.MessageType.MSG_SNAKE_FIGHT, this, this.onBattleCallback);
            //更新所有数据
            const cmdId = com.snake.socket.MessageType.MSG_PACK_INFO;
            HallWebSocket.send(cmdId);
        }
    }

    /**
     * 跳转到商城页面
     */
    private toShopScene(): void {
        // 跳转到商城页面
        SceneManager.setCurrentScene(SceneType.M_SCENE_SHOP);
    }

    private showDetail(): void {
        ModuleManager.intance.openModule(ModuleName.SnakeUpgradeConfirmDialog, this.nftItem);
    }
}
