const { regClass } = Laya;
import { Quick } from "../../utils/Quick";
import { BodySkin } from "../../game/snake/BodySkin";
import { com } from "../../network/pb/socket";
import { StringTool } from "../../utils/StringTool";
import { DamageNumber } from "../match/DamageNumber";
import { MatchSnakeSprBase } from "./MatchSnakeSpr.generated";
import GameResourceManager from "../../common/GameResourceManager";
import FrameSyncManager from "../../game/match/FrameSyncManager";
import GameSetting from "../../global/GameSetting";
import GlobalDataManager from "../../global/GlobalDataManager";
import MatchModel from "../match/MatchModel";
import MapManager from "../../game/map/MapManager";

@regClass('tWPXV+AGQQ2kGHES5HnI0w==')
export class MatchSnakeSpr extends MatchSnakeSprBase {
    static POOL_NAME = "MatchSnakeSpr";
    owner: BodySkin;
    public roomPlayerDto: com.snake.socket.PlayerObject;
    public isMe: boolean = false;
    /**是否碰到墙 */
    public inGround: boolean = false;
    public enterItemId: number;
    _isDead: boolean;
    _isRealDead: boolean;
    public _isAttacking: boolean;
    _isTakingDamage: boolean;

    public speedRate: number = 1; //速度速率
    public moveSpeed: number = 10; //配表速度
    private _speed: number = 10;

    public get speed(): number {
        return this._speed;
    }

    public set speed(value: number) {
        this._speed = value;
        this.biasSpeed = Math.round(this.speed * Math.sin((45 * Math.PI) / 180));
        // console.log("Role speed2: ", this.speed, this.biasSpeed, this.roomPlayerDto.id);
    }

    /** 斜线速度 */
    biasSpeed: number = 0;
    private _roleDirection: number = -1;
    public get roleDirection(): number {
        return this._roleDirection;
    }

    /** 设置方向 (平滑旋转)
     * @param direct 目标方向 (角度)
     */
    public set roleDirection(direct: number) {
        if (direct === -4) return; // 过滤特殊值
        this._roleDirection = direct;
    }

    public constructor() {
        super();
    }

    public set dataSource(value: any) {
        // super.dataSource = value;
        this.roomPlayerDto = value as com.snake.socket.PlayerObject;
        if (!this.roomPlayerDto) {
            return;
        }
        this.img_follow.visible = false;
        this.heroSk.skin = GameResourceManager.getSnakeHeadIcon(this.roomPlayerDto.skin); //暂时使用随机的颜色
        if (this.roomPlayerDto.country) {
            this.img_country.skin = GameResourceManager.getCountryIconById(this.roomPlayerDto.country);
            this.img_country.visible = true;
        } else {
            this.img_country.visible = false;
        }

        this.tf_name.text = StringTool.abbreviateString(this.roomPlayerDto.userName);
        if (this.roomPlayerDto.roleId == GlobalDataManager.playerDto.pid) {
            this.tf_name.color = "#00FF00";
        }
        if (MatchModel.matchWatcher) {
            //只有观察者才能点击英雄
            this.heroSk.off(Laya.Event.CLICK, this, this.onHeroSkClick);
            this.heroSk.on(Laya.Event.CLICK, this, this.onHeroSkClick);
        }
    }

    onHeroSkClick() {
        MapManager.setOtherHero(this.owner.owner.owner);
    }
    smallHeroImg: Laya.Image;
    lastX: number = 0;

    set x(value: number) {
        super.x = value;
    }

    get x() {
        return super.x;
    }

    set visible(value: boolean) {
        super.visible = value;
        if (this.smallHeroImg) this.smallHeroImg.visible = value;
    }
    get visible() {
        return super.visible;
    }

    set alpha(value: number) {
        super.alpha = value;
        if (this.smallHeroImg) this.smallHeroImg.alpha = value;
    }

    onAwake(): void {}

    // 显示伤害数字并播放跳动动画
    showDamageLabelDetailDelay(damage: number, delay: number, attackPush: boolean): void {
        Laya.timer.once(delay, this, this.showDamageLabelDetail, [damage, attackPush], false);
    }

    // 显示伤害数字并播放跳动动画
    private showDamageLabelDetail(damage: number, isKill: boolean): void {
        var _damageLabel: DamageNumber = Laya.Pool.getItemByCreateFun(
            "damageNumber",
            GameResourceManager.damageNumPrefab.create,
            GameResourceManager.damageNumPrefab
        );

        _damageLabel.init(damage, isKill); // 设置位置在角色头顶

        this.addChild(_damageLabel);
    }

    public setRotation(rotation: number): void {
        this.heroSk.rotation = rotation;
    }

    setScale(radio: number) {
        // 当图片加载完成后才有 width/height 值
        const width = this.heroSk.width;
        const height = this.heroSk.height;
        const scaleX = (radio * 2) / width;
        const scaleY = (radio * 2) / height;
        this.heroSk.scaleX = scaleX;
        this.heroSk.scaleY = scaleY;
    }

    setAlpha(value: number) {
        this.heroSk.alpha = value;
    }

    setGray(isGray: boolean) {
        this.heroSk.gray = isGray;
    }

    public getRadio(): number {
        return (this.heroSk.width * this.heroSk.scaleX) / 2;
    }

    setFollowIcon(isShow: boolean) {
        this.img_follow.visible = isShow;
    }

    onDisable(): void {
        if (this.heroSk) this.heroSk.off(Laya.Event.CLICK, this, this.onHeroSkClick);
        Laya.timer.clearAll(this);
        Laya.Tween.clearAll(this);
        this.smallHeroImg = null;
        this.setGray(false);
        this.setAlpha(1);
        this.scale(1, 1);
        //移除时，回收到对象池，方便下次复用，减少对象创建开销
        Laya.Pool.recover(MatchSnakeSpr.POOL_NAME, this);
    }

    setClientScore(score: number) {
        this.tf_pos.text = `${score}`;
    }

    // checkClientAndServerFrame(x: number, y: number) {
    //     return;
    //     // this.tf_pos.text = `C：(${Math.round(x)}, ${Math.round(y)}, ${this.owner.owner.speedRate}, dir：${this.owner.owner.dir.getRotation()}, aimDir：${this.owner.owner.aimDir.getRotation()}, ${this.owner.owner.clientFrame})`;
    //     if (GameSetting.Debug >= 1) {
    //         if (GameSetting.Debug == 2)
    //             // console.log(
    //             //     Quick.GetLogTime +
    //             //         " " +
    //             //         `${this.roomPlayerDto.roleId} C：(${x}, ${y}, ${this.owner.owner.speedRate}, dir：${this.owner.owner.dir}, aimDir：${this.owner.owner.aimDir}, ${FrameSyncManager.currentFrame})`
    //             // );
    //             FrameSyncManager.checkClientAndServerFrame(
    //                 FrameSyncManager.clientRuningFrame,
    //                 this.roomPlayerDto.roleId,
    //                 x,
    //                 y
    //             );
    //     }
    // }

    setServerPosLog(serverFrame: number, head: com.snake.socket.SnakeObject, _mockSpeedRate: number, mockDirect: number, mockAimDirect: number) {
        // return;
        // this.tf_server_pos.text = `S：(${Math.round(head.loc.x)}, ${Math.round(head.loc.y)}, ${_mockSpeedRate}, dir：${mockDirect}, aimDir：${mockAimDirect}, ${serverFrame})`;
        if (GameSetting.Debug == 2)
            console.log(
                Quick.GetLogTime +
                    " " +
                    `${this.roomPlayerDto.roleId} S：(${head.loc.x}, ${head.loc.y}, ${_mockSpeedRate}, dir：${mockDirect}, aimDir：${mockAimDirect}, ${serverFrame})`
            );
    }

    showLogInHead(tip: string) {
        this.tf_server_pos.text = `${tip}`;
    }

    destroy(destroyChild?: boolean): void {
        Laya.timer.clearAll(this);
        Laya.Tween.clearAll(this);
        this.smallHeroImg = null;
        this.owner = null;
        this.roomPlayerDto = null;
        super.destroy(destroyChild);
    }
}
