const { regClass } = Laya;
import GameLanguageMgr from "../../common/GameLanguageMgr";
import GameResourceManager from "../../common/GameResourceManager";
import SheetDataManager from "../../global/SheetDataManager";
import { TimeUtil } from "../../utils/TimeUtil";
import { MatchEndRewardTokensListItemBase } from "./MatchEndRewardTokensListItem.generated";

@regClass('po6/Uf6sTlaC+xEazLOk5Q==')
export class MatchEndRewardTokensListItem extends MatchEndRewardTokensListItemBase {
    public constructor() {
        super();
    }

    private addEvent() {}

    public set dataSource(data: any) {
        super.dataSource = data;
        if (!data) {
            this.visible = false;
            return;
        }
        this.setData(data);
        this.addEvent();
    }
    private setData(data: string) {
        var value = data.split(","); //击杀时间，被击杀国家，名字，id，数量

        var country = value[1];
        var nickName = value[2];
        var coinType = value[3];
        var coinNum = value[4];

        this.tf_time.text = TimeUtil.formatTimeStamp(Number.parseFloat(value[0]), "HH:MM:SS"); //时间

        this.img_country.skin = GameResourceManager.getCountryIconById(country);
        this.tf_nickName.text = nickName;

        let itemItem = SheetDataManager.m_dicItems.get(coinType);
        let moneyName = GameLanguageMgr.getLanguage(itemItem.name);
        this.tf_token.text = coinNum + " " + moneyName;
    }

    // 自定义方法：接收index
    public setDataIndex(index: number): void {
        this.bg.skin = index % 2 === 0 ? "res/common/comm/img_wzbg_1.png" : "res/common/comm/img_wzbg_2.png";
    }
}
