import { ModuleManager } from "./ModuleManager";
import { SceneType } from "./baseScene/SceneType";
import { GameEvent } from "../global/event/GameEvent";
import { Quick } from "../utils/Quick";
import Signal from "../global/event/Signal";

class SceneManager {
    private static _instance: SceneManager;
    public dragging: boolean;
    public static getInstance(): SceneManager {
        if (SceneManager._instance) {
            return SceneManager._instance;
        }
        SceneManager._instance = new SceneManager();
        return SceneManager._instance;
    }

    public topView: any; // MainTopView;
    public bottomView: any; // MainBottomView;
    public m_sceneCurrent: Laya.Scene;
    public mainSceneX: number = 10086;
    public fromScene: string;
    public m_arrFromScenes: any[];

    public constructor() {
        Signal.on(GameEvent.EVENT_MODULE_ADDED, this, this.onAdded);
    }

    public init(): void {}

    public setup(): void {}

    public onAdded(data: any): void {}

    public isCloseAll: boolean = true;
    public getPreSceneData(): any[] {
        if (this.m_arrFromScenes.length < 1) {
            return [SceneType.M_SCENE_MAIN, true, 1, null];
        } else {
            let secenData: any[] = this.m_arrFromScenes.pop();
            console.log("pop-----------route：" + this.m_arrFromScenes.join(" | "));
            return secenData;
        }
    }

    public removePreSceneData(): void {
        this.m_arrFromScenes = [];
    }

    public setMainScene(type: number = 1, data: any = null): void {
        this.setCurrentScene(SceneType.M_SCENE_MAIN, data);
    }

    public async setCurrentScene(sceneType: string, data: any = null): Promise<void> {
        console.log("setCurrentScene: ", sceneType, data);
        this.preSceneName = sceneType;
        if (this.m_sceneCurrent && this.m_sceneCurrent.name == sceneType) {
            console.log("currentScene：" + this.m_sceneCurrent.name + "  openScene：：" + sceneType);
            return;
        }
        if (this.isCloseAll) {
            ModuleManager.intance.closeAll();
        } else {
            this.isCloseAll = true;
        }

        if (this.m_sceneCurrent) {
            if (!this.m_arrFromScenes) {
                this.m_arrFromScenes = [];
            }

            console.log("open-----------scene：" + this.m_arrFromScenes);
            this.fromScene = this.m_sceneCurrent.name;
            console.log("fromSceneName: " + this.fromScene);
        }

        switch (sceneType) {
            case SceneType.M_SCENE_MAIN:
                {
                    this.m_arrFromScenes = [];
                    this.m_sceneCurrent = await Laya.Scene.open("scenes/mainView/MainScene.ls");
                }
                break;
            case SceneType.M_SCENE_SHOP:
                {
                    this.m_sceneCurrent = await Laya.Scene.open("scenes/shop/ShopScene.ls", true, data);
                }
                break;
            case SceneType.M_SCENE_RANK:
                {
                    this.m_sceneCurrent = await Laya.Scene.open("scenes/rank/RankScene.ls");
                }
                break;
            case SceneType.M_SCENE_CLUB:
                {
                    this.m_sceneCurrent = await Laya.Scene.open("scenes/club/ClubScene.ls");
                }
                break;

            case SceneType.M_SCENE_FRIEND:
                {
                    this.m_sceneCurrent = await Laya.Scene.open("scenes/friend/FriendScene.ls");
                }
                break;
            case SceneType.M_SCENE_KNAPSACK:
                {
                    this.m_sceneCurrent = await Laya.Scene.open("scenes/knapsack/KnapsackScene.ls", true, data);
                }
                break;
            case SceneType.M_SCENE_MAIL:
                {
                    this.m_sceneCurrent = await Laya.Scene.open("scenes/mail/MailScene.ls", true, data);
                }
                break;
            case SceneType.M_SCENE_SNAKE_MATCH:
                {
                    this.m_sceneCurrent = await Laya.Scene.open("scenes/match/SnakeMatch.ls", true, data);
                }
                break;
            case SceneType.M_SCENE_AI_ARENA:
                {
                    this.m_sceneCurrent = await Laya.Scene.open("scenes/match/AiArenaScene.ls");
                }
                break;
            case SceneType.M_SCENE_MATCH_TOURNAMENT:
                {
                    this.m_sceneCurrent = await Laya.Scene.open("scenes/matchTournament/MatchTournamentScene.ls");
                }
                break;
            case SceneType.M_SCENE_ASSET:
                {
                    this.m_sceneCurrent = await Laya.Scene.open("scenes/asset/AssetNewScene.ls", true, data);
                }
                break;

            case SceneType.M_SCENE_ROLE:
                {
                    this.m_sceneCurrent = await Laya.Scene.open("scenes/createRole/RoleInfoScene.ls", false, data);
                }
                break;
            case SceneType.M_SCENE_SETTING:
                {
                    this.m_sceneCurrent = await Laya.Scene.open("scenes/gameSetting/SettingScene.ls", false, data);
                }
                break;
            case SceneType.M_SCENE_REFFERAL:
                {
                    this.m_sceneCurrent = await Laya.Scene.open("scenes/createRole/ReferralScene.ls", false, data);
                }
                break;
                
            default:
                break;
        }
        Quick.logs("======================  打开Scene: " + sceneType + "  ======================");
        this.m_sceneCurrent.name = sceneType;
    }

    public get currSceneName(): string {
        if (this.m_sceneCurrent) {
            return this.m_sceneCurrent.name;
        }
        return "";
    }

    public preSceneName: string;
}

export default SceneManager.getInstance();
