import ConfigBuilder from "../../assets/js/ConfigBuilder.js"; // 相对路径引入
import { Address } from "ton";
import EthereumManager from "../global/contract/EthereumManager";
import { Dictionary } from "./Dictionary";

export class ETHUtils {
    public static getInviteUrl() {
        return window.location.origin + "?invite=" + this.encode(EthereumManager.walletAddress);
    }
    //加密字符串
    public static encode(str: string) {
        //定义密钥，36个字母和数字
        console.log("encodeStr========>", str);
        var key = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";
        var len = key.length; //获取密钥的长度
        var a = key.split(""); //把密钥字符串转换为字符数组
        var s = "",
            b,
            b1,
            b2,
            b3; //定义临时变量
        for (var i = 0; i < str.length; i++) {
            //遍历字符串
            b = str.charCodeAt(i); //逐个提取每个字符，并获取Unicode编码值
            b1 = b % len; //求Unicode编码值得余数
            b = (b - b1) / len; //求最大倍数
            b2 = b % len; //求最大倍数的于是
            b = (b - b2) / len; //求最大倍数
            b3 = b % len; //求最大倍数的余数
            s += a[b3] + a[b2] + a[b1]; //根据余数值映射到密钥中对应下标位置的字符
        }
        return window.btoa(s); //返回这些映射的字符
    }
    //解密字符串：
    public static decode(str: string) {
        str = window.atob(str);
        //定义密钥，36个字母和数字
        var key = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";
        var len = key.length; //获取密钥的长度
        var b,
            b1,
            b2,
            b3,
            d = 0,
            s; //定义临时变量
        s = new Array(Math.floor(str.length / 3)); //计算加密字符串包含的字符数，并定义数组
        b = s.length; //获取数组的长度
        for (var i = 0; i < b; i++) {
            //以数组的长度循环次数，遍历加密字符串
            b1 = key.indexOf(str.charAt(d)); //截取周期内第一个字符串，计算在密钥中的下标值
            d++;
            b2 = key.indexOf(str.charAt(d)); //截取周期内第二个字符串，计算在密钥中的下标值
            d++;
            b3 = key.indexOf(str.charAt(d)); //截取周期内第三个字符串，计算在密钥中的下标值
            d++;
            s[i] = b1 * len * len + b2 * len + b3; //利用下标值，反推被加密字符的Unicode编码值
        }

        b = decodeCharCode(s.join(",") as any);
        // b = String.fromCharCode(s.join(',') as any);
        // b = eval("String.fromCharCode(" + s.join(',') + ")");
        return b; //返回被解密的字符串
    }

    //获取url里面的参数
    public static getQueryString(name: string): any {
        var reg = new RegExp("(^|&)" + name + "=([^&]*)(&|$)");
        var r = window.location.search.substr(1).match(reg);
        if (r != null) return r[2]; //注意这里不能用js里面的unescape方法
        return "";
    }

    public static getInviteWalletAddress() {
        let url = this.getQueryString("invite");
        if (url) {
            url = this.decode(url);
        }
        return url;
    }

    public static toWei(value: number, decimals: string) {
        let num = value * 10 ** parseInt(decimals);
        let tokens = (window as any)["web3"].utils.toBN("0x" + num.toString(16));
        return tokens.toString();
    }

    public static fromWei(value: string | any[], decimals: number, point = 0) {
        if (!value) {
            return 0;
        }
        let len = value.length - decimals + point;
        if (len <= 0) {
            return 0;
        }
        let temp = value.toString().slice(0, len);
        if (point) {
            let tt = temp.length - point;
            if (tt <= 0) {
                let ttt = "0.";
                for (let index = 0; index < Math.abs(tt); index++) {
                    ttt += "0";
                }
                temp = ttt + temp;
            } else {
                temp = temp.slice(0, temp.length - point) + "." + temp.slice(temp.length - point);
            }
        }
        return temp;
    }

    public static deepClone(obj: any): Dictionary {
        let temp: any = new Dictionary();
        for (let k in obj) {
            if (typeof obj[k] == "function") {
                //如果是方法直接赋值就可以了
                temp[k] = obj[k];
            } else {
                temp[k] = JSON.parse(JSON.stringify(obj[k]));
            }
        }
        return temp;
    }

    public static signTelegramArray(code: string) {
        let codes = code.split("&"); // 分割各个签名组件
        // 分解签名组件
        let timestamp = parseFloat(codes[0]); // 时间戳
        let randomHex = codes[1]; // 随机哈希
        let signatureHex = codes[2]; // 签名r值
        let domain = codes[3]; // 签名s值
        let publicKey = codes[4]; // 签名v值
        const loginData = {
            timestamp,
            randomHex,
            signatureHex,
            domain,
            publicKey
        };
        return loginData;
    }

    public static changeTonAddress(account: any) {
        ConfigBuilder;
        if (account) {
            const address = Address.parse(account);
            // Non-bounceable 地址（UQ 开头）
            const reallyAddress = address.toString({ bounceable: false, urlSafe: false });
            return reallyAddress;
        }
    }
}
