import { com } from "../../network/pb/socket";
import { Dictionary } from "../../utils/Dictionary";
import Constants from "../../global/config/Constants";
import { CollisionSystem } from "../collision/CollisionSystem";
import Snake from "./Snake";
import FrameSyncManager from "../match/FrameSyncManager";
import GlobalDataManager from "../../global/GlobalDataManager";
import MatchModel from "../../modules/match/MatchModel";

import RoomWebSocket from "../../network/RoomWebSocket";
import PvpSnake from "./PvpSnake";
import SnakeManagerBase from "./SnakeManagerBase";

class PvpSnakeManager extends SnakeManagerBase {
    protected static _instance: PvpSnakeManager | null = null;

    public static getInstance(): PvpSnakeManager {
        if (!PvpSnakeManager._instance) {
            PvpSnakeManager._instance = new PvpSnakeManager();
        }
        return PvpSnakeManager._instance;
    }

    /**
     * 创建一条蛇，并添加到管理器中
     * @param pos 蛇的初始位置（Laya.Point）
     * @param dir 蛇的初始方向（Vec2 类型）
     * @param len 蛇的骨骼数量
     * @param snakeType 蛇的类型，默认为其他蛇
     */
    public createSnake(roomPlayerDto: com.snake.socket.PlayerObject): Snake {
        let newSnake = new PvpSnake(this.container, roomPlayerDto);

        if (this.matchHeroSprDic.get(roomPlayerDto.roleId)) {
            throw new Error(roomPlayerDto.roleId + " 被重复添加！");
        }
        this.matchHeroSprDic.set(roomPlayerDto.roleId, newSnake);
        // this.snakes.push(newSnake);
        console.log("createSnake: " + roomPlayerDto.roleId, GlobalDataManager.playerDto.pid);
        if (GlobalDataManager.playerDto.pid == roomPlayerDto.roleId) {
            this.selfSnake = newSnake;
            // PvpSnakeManager.instance.selfSnake = newSnake;
        }
        // 添加蛇皮到碰撞四叉树中
        // this.collision.addSnake(newSnake.getSkins());
        return newSnake;
    }

    /**
     * 同步显示层
     */
    public adjustVisualState(): void {
        // console.log("adjustVisualState");

        var snakes = this.matchHeroSprDic.getMap();
        for (const [roleId, snake] of snakes) {
            if ((snake as Snake).tag) {
                (snake as PvpSnake).adjustVisualState();
            }
        }
    }

    /**
     * 设置蛇的目标旋转方向
     * @param snakeType 蛇类型
     * @param dir 目标方向（Vec2 类型）
     */
    public rorate(snakeType: number, direction: number): void {
        if (snakeType === Constants.snakeType.SELF) {
            if (this.selfSnake && this.selfSnake.tag) {
                this.selfSnake.rotateControl(direction, true);
            }
        } else {
            // 可扩展其他类型蛇的旋转逻辑
        }
    }

    /**
     * 转向操作
     */
    public rorateReadySend(): void {
        // ======提示====   1-1、客户端发送自己蛇的转向操作
        if (this.selfSnake && this.selfSnake.tag && this.selfSnake.isAlive(false)) {
            (this.selfSnake as PvpSnake).rorateReadySend();
        }
    }
    /**
     * 更新蛇的移动速率
     * @param snakeType 蛇类型
     * @param rate 速率值
     */
    public updateSpeedRate(snakeType: number, rate: number): void {
        if (snakeType === Constants.snakeType.SELF && this.selfSnake && this.selfSnake.tag && this.selfSnake.isAlive(false)) {
            var roleId = GlobalDataManager.playerDto.pid;
            // ======提示====   1-2、客户端发送自己蛇的加速操作

            var head = this.selfSnake.getToServerHead(false);
            //// opr : 1转向2加速
            var cmdId = com.snake.socket.MessageType.MSG_PLAYER_OPR;
            var o = com.snake.socket.CS_PLAYER_OPR.fromObject({
                roleId: roleId,
                opr: 2,
                value: rate,
                head: head,
                frame: FrameSyncManager.getClientCurrentFrame(),
                curDir: this.selfSnake.getCurDir(),
                aimDir: this.selfSnake.getAimDir()
                // snake: []
            });
            if (!MatchModel.matchWatcher) {
                RoomWebSocket.sendData(cmdId, o);
            }

            o.frame = FrameSyncManager.getPredictFrameHalf();
            // ======提示====   2-2、单独操作加入事件 加入到本地帧同步列表
            FrameSyncManager.frameNetQueue.addLocalOperation(o);
        } else {
            // 可扩展其他类型蛇的速率更新逻辑
        }
    }

    /**
     * 检查蛇是否碰撞死亡：
     * - 检查蛇头是否撞边界
     * - 检查蛇头与其他蛇之间的碰撞
     */
    public checkAllSnakeCollision(isLogicSnake: boolean, hasConfirmed: boolean): void {
        var snakes = this.matchHeroSprDic.getMap();
        for (const [roleId, snake] of snakes) {
            var playerSnake = snake as Snake;
            if (playerSnake && playerSnake.tag) {
                // console.log("checkAllSnakeCollision roleId: ", playerSnake.tag.roleId);

                if (isLogicSnake) {
                    CollisionSystem.checkCollisionsWithConfirm(playerSnake, null, this.collision, hasConfirmed);
                } else {
                    CollisionSystem.checkCollisions(playerSnake, null, this.collision, hasConfirmed);
                }
            }
        }
    }

    restoreSnakes() {
        this.removeAllSnakes();
        this.matchHeroSprDic = new Dictionary(true);

        let len = MatchModel.matchDto.members.length;

        for (var i = 0; i < len; i++) {
            var roomPlayerDto: com.snake.socket.PlayerObject = MatchModel.matchDto.members[i];

            try {
                var snake: Snake = this.createSnake(roomPlayerDto);
            } catch (error) {
                console.warn(error);
            }
        }
    }

    public getSnakesState(): any {
        const state: any = {
            snakes: {}
        };
        var snakes = this.matchHeroSprDic.getMap();
        for (const [roleId, snake] of snakes) {
            var pvpSnake: Snake = snake;
            const playerId = pvpSnake.tag.roleId;
            state.snakes[playerId] = pvpSnake.logicSnake.getState();
        }

        return state;
    }

    public restoreState(state: any): void {
        // 恢复蛇的状态
        for (const playerId in state.snakes) {
            var snake: Snake = this.matchHeroSprDic.get(playerId);
            if (snake) {
                snake.logicSnake.restoreState(state.snakes[playerId]);
            }
        }
    }
}
export default PvpSnakeManager;
