    // 新增：处理实际增长逻辑
    private _processGrowth(): void {
        var needBoneLen = this.boneLength;

        var boneLen = this.bones.length;
        // console.log(
        //     Quick.GetLogTime,
        //     this.tag.roleId + ", isLogicSnake: " + this.isLogicSnake + " _processGrowth: start needLen:" + needBoneLen,
        //     "boneLen: " + boneLen
        // );
        if (needBoneLen == boneLen && needBoneLen >= this.maxBoneLength) {
            //到达最大长度的时候，返回
            return;
        }
        if (needBoneLen > boneLen) {
            // 使用 Vec2.create 和 assign 方法来复制最后一个骨骼点
            const lastBone = this.bones[this.bones.length - 1];
            var lastTempBone;
            if (this.tempBones) {
                lastTempBone = this.tempBones[this.tempBones.length - 1];
            }
            var newBone;
            for (var i = boneLen + 1; i <= needBoneLen; i++) {
                newBone = Vec2.create(lastBone.x, lastBone.y);
                this.bones.push(newBone);
                if (lastTempBone) {
                    this.tempBones.push(Vec2.create(lastTempBone.x, lastTempBone.y));
                }
            }
        } else if (needBoneLen < boneLen) {
            this.bones.splice(needBoneLen);
        }

        var skinNeedLen = this.getSkinLength();
        var skinLen = this.skins.length;
        // console.log(
        //     Quick.GetLogTime,
        //     this.tag.roleId + ", isLogicSnake: " + this.isLogicSnake + " _processGrowth: start skinNeedLen:" + skinNeedLen,
        //     "skinLen: " + skinLen
        // );
        if (skinNeedLen > skinLen) {
            for (var skinNo = skinLen + 1; skinNo <= skinNeedLen; skinNo++) {
                const lastSkinBoneIndex = (skinNo - 1) * this.intervalBoneToDrawSkin;
                const newSkin = this.bodySkinPool.getBodySkin(Constants.snake.skinFlag.body, this.color, this.tag, this);

                newSkin.setPosition(this.bones[lastSkinBoneIndex]);
                SnakeManager.getInstance().addBodySkin(newSkin);
                // 设置皮肤层级和旋转
                newSkin.setLocalZOrder(-(skinNo + 1));
                let targetBone: Vec2 = this.bones[lastSkinBoneIndex];
                const boneRotation = this.bones[lastSkinBoneIndex].getRotationTo(targetBone);
                newSkin.setRotation(Constants.snake.defaultRotation - boneRotation);

                this.skins.push(newSkin);
            }
        } else if (skinNeedLen < skinLen) {
            for (var skinNo = skinNeedLen + 1; skinNo <= skinLen; skinNo++) {
                var bodySkin = this.skins[skinNo - 1];
                this.bodySkinPool.returnBodySkin(bodySkin);
            }
            // console.log("_processGrowth: before " + this.skins.length, "skinNeedLen: " + skinNeedLen, "skinLen: " + skinLen);
            this.skins.splice(skinNeedLen);
            // console.log("_processGrowth: after " + this.skins.length);
        }

        // 更新皮肤比例
        this._updateSkinRadio();
    }

    /**
     * 更新蛇身体（皮肤）的显示位置和旋转角度
     * 此方法在蛇移动后调用，以确保皮肤与骨骼数据保持一致
     */
    private _moveBody(): void {
        // if(GameSetting.Debug == 2)
        // console.log(Quick.GetLogTime, "_moveBody");
        // 计算皮肤数量
        const skinCount = this.getSkinLength();

        // 遍历每个皮肤
        for (let i = 0; i < skinCount; i++) {
            // 对应的骨骼点索引：每隔一定骨骼更新一次皮肤位置
            const index = i * this.intervalBoneToDrawSkin;
            if (this.skins[i]) {
                if (this.bones[index]) {
                    // 设置皮肤的位置与对应骨骼点相同
                    if (this.tempBones) {
                        this.skins[i].setPosition(this.tempBones[index]);
                    } else {
                        this.skins[i].setPosition(this.bones[index]);
                    }

                    // 同样根据相邻骨骼点来确定旋转角度
                    let targetBone: Vec2;
                    if (index + 1 < this.bones.length) {
                        targetBone = this.bones[index + 1];
                    } else if (index - 1 >= 0) {
                        targetBone = this.bones[index - 1];
                    } else {
                        targetBone = this.bones[index];
                    }

                    // if(i == 0){
                    //     console.log("_moveBody: ", this.bones[index], targetBone);
                    // }

                    // 计算当前骨骼点与目标骨骼点间的旋转角度
                    const boneRotation = this.bones[index].getRotationTo(targetBone);
                    // 使用默认旋转角度减去骨骼角度，得到皮肤需要设置的旋转角度
                    this.skins[i].setRotation(Constants.snake.defaultRotation - boneRotation);
                    this.skins[i].setVisible(true);
                    // console.log("_moveBody: info ", "skinLen: " + this.skins.length, "boneLen: " + this.bones.length, "i: " + i, "skinCount: " + skinCount, "isLogicSnake: " + this.isLogicSnake);
                } else {
                    this.skins[i].setVisible(false);
                    // console.error(
                    //     "_moveBody: error ",
                    //     "skinLen: " + this.skins.length,
                    //     "boneLen: " + this.bones.length,
                    //     "i: " + i,
                    //     "skinCount: " + skinCount,
                    //     "isLogicSnake: " + this.isLogicSnake
                    // );
                }
            }
        }
        //打印所有骨骼数据
        // if(GameSetting.Debug == 2)
        //     console.log(Quick.GetLogTime + " " + `${(this.tag.roleId)} ==C： ${this.bones}, ${this.speedRate}, dir：${this.dir}, aimDir：${this.aimDir}, ${FrameSyncManager.currentFrame})`);
    }
    /**
     * 更新皮肤的缩放比例（例如根据当前游戏状态动态调整缩放比例）
     */
    private _updateSkinRadio(): void {
        return;
        // 计算当前皮肤的数量
        const skinCount = this.getSkinLength();

        // 遍历每个皮肤，将其缩放比例设置为 this.radio
        for (let i = 0; i < skinCount; i++) {
            // this.skin[i].setScale(this.radio);
            if (this.skins[i]) this.skins[i].updateAlpha(this.radio, this.speedRate);
            // this.skin[i].updateScale(this.radio, this.speedRate);
        }
    }
