    /**
     * 发送转向命令给服务器
     */
    public rotateSend(): void {
        // if (this.lastDir != -1 && this.lastSendDir != this.lastDir) {

        if (FrameSyncManager.clientRuningFrame == FrameSyncManager.startFrame) return;
        var roleId = GlobalDataManager.playerDto.pid;
        //// opr : 1转向2加速
        var head = this.getToServerHead();
        var cmdId = com.snake.socket.MessageType.MSG_PLAYER_OPR;
        var o = com.snake.socket.CS_PLAYER_OPR.fromObject({
            roleId: roleId,
            opr: 1,
            value: this.lastDir,
            head: head,
            frame: FrameSyncManager.getClientCurrentFrame(), /// TODO 延迟帧+1
            curDir: this.getCurDir(),
            aimDir: this.getAimDir()
            // snake: []
        });
        // GameManager.instance.onRevOprPush(o, false);
        if (!MatchModel.matchWatcher) {
            RoomWebSocket.sendData(cmdId, o);
        }

        if (this.lastDir != -1 && this.lastSendDir != this.lastDir) {
            // ======提示====   2-2、单独操作加入事件 加入到本地帧同步列表
            o.frame = FrameSyncManager.getPredictFrameHalf();
            FrameSyncManager.frameNetQueue.addLocalOperation(o);
            this.lastSendDir = this.lastDir;
        }
    }

