export class CollisionSystem {
    public static checkCollisions(playerSnake: Snake, foodManager: any, collision: Collision, hasConfirmed: boolean): void {
        // console.log("碰撞检测");
        // if (!playerSnake.isAlive()) return;
        var isLogicSnake = false;
        if (playerSnake.getIsSend(isLogicSnake)) {
            return;
        }
        const mapSize = Constants.mapSize;

        // ======提示====   3-1、客户端检测所有蛇的碰撞（边界检测+食物+蛇）
        if (playerSnake && playerSnake.tag) {
            // 1. 地图边界碰撞检测
            const headBounds = playerSnake.getHeadCollisionBounds(isLogicSnake);
            if (headBounds) {
                const isOutOfBounds =
                    headBounds.x < mapSize.offsetX ||
                    headBounds.x + headBounds.width > mapSize.width - mapSize.offsetX ||
                    headBounds.y < mapSize.offsetY ||
                    headBounds.y + headBounds.height > mapSize.height - mapSize.offsetY;

                if (isOutOfBounds) {
                    if (playerSnake.isAlive(isLogicSnake)) {
                        playerSnake.readyDie();

                        // var head = playerSnake.getToServerHead(isLogicSnake);
                        // var cmdId = com.snake.socket.MessageType.MSG_PLAYER_COLLISION;
                        // var o1 = com.snake.socket.CS_PLAYER_COLLISION.fromObject({
                        //     roleId: playerSnake.tag.roleId,
                        //     head: head,
                        //     frame: FrameSyncManager.getClientRuningFrame(isLogicSnake),
                        //     body: false
                        // });
                        // RoomWebSocket.sendData(cmdId, o1);

                        playerSnake.setIsSend(true, isLogicSnake);
                    }

                    return;
                }
            }

            if (playerSnake.isAlive(isLogicSnake) && !playerSnake.getIsStop(isLogicSnake)) {
                // 1. 食物碰撞检测
                // 获取蛇头位置和碰撞半径

                // 获取蛇头中心位置和碰撞半径
                const headBounds = playerSnake.getHeadCollisionBounds(isLogicSnake);
                if (!headBounds) {
                    return;
                }

                if (true) {
                    // 确认帧之前的食物不吃
                    const foodCandidates = FoodManager.getAllFoods();

                    // const foodCandidates = collision.retrieve(playerSnake.getHead())
                    // .filter(obj => obj instanceof Food);

                    // console.log("foodCandidates 长度：" + foodCandidates.length);
                    var foodIds: string[] = [];
                    var totalAddScore: number = 0;
                    foodCandidates.forEach((food: Food) => {
                        if (!food.getHaveEaten(hasConfirmed)) {
                            if (playerSnake.checkFoodCollision(food, isLogicSnake)) {
                                // ======提示====   3-2、客户端检测到碰撞食物，就显示吃掉
                                if (GameSetting.Debug == 2)
                                    console.log(
                                        Quick.GetLogTime + " FOOD_TEST 显示蛇 吃 foodId：",
                                        food.foodObject.unkey,
                                        "currentFrame:" + FrameSyncManager.getClientRuningFrame(isLogicSnake),
                                        "isLogicSnake:" + isLogicSnake,
                                        "hasConfirmed:" + hasConfirmed
                                    );
                                food.beEattenByPlayerSnake(playerSnake, isLogicSnake, hasConfirmed);
                                // food.setHaveEaten(true, isLogicSnake);
                                // var isEaten = SnakeManager.getInstance().checkFoodEatByServer(roleId, food.foodObject.unkey);

                                // console.log(food.foodObject.unkey, food.getPosition());
                                foodIds.push(food.foodObject.unkey);
                                var addScore = food.getScore();
                                // if(Tool.getRandInRound(0, 99) < playerSnake.getDoublePointsProbability()){
                                //     addScore *= 2;
                                // }
                                totalAddScore += addScore;
                            }
                        }
                    });
                    if (foodIds && foodIds.length > 0) {
                        // ======提示====   3-3、客户端根据公式，计算分数和长度
                        var msgEatFoodBody: SC_EAT_FOOD = new SC_EAT_FOOD();
                        msgEatFoodBody.fid = foodIds; //食物id
                        msgEatFoodBody.score = totalAddScore; // 10;//当前积分 根据配置计算
                        var totalScore = playerSnake.getScore(isLogicSnake) + totalAddScore; // 10;//当前积分 根据配置计算

                        var skinLength = playerSnake.getSkinLength(isLogicSnake);

                        var snakeId = playerSnake.tag.snakeId;

                        //当前长度 TODO://根据配置计算
                        var newLen = SnakeManager.getInstance().countSnakeLen(
                            snakeId,
                            skinLength,
                            totalScore,
                            playerSnake.intervalBoneToDrawSkin(isLogicSnake)
                        );
                        // console.log(playerSnake.tag.roleId + " === 当前长度：" + newLen, snakeId, skinLength, totalScore);
                        // playerSnake.score = totalScore;
                        msgEatFoodBody.lenght = newLen;

                        msgEatFoodBody.roleId = playerSnake.tag.roleId; //玩家id
                        msgEatFoodBody.score = totalScore; //总分数
                        msgEatFoodBody.remain = []; //剩余未吃掉的食物
                        SnakeManager.getInstance().eatFoodAndAddScore(msgEatFoodBody, isLogicSnake);
                        if (GameSetting.Debug == 2)
                            console.log(
                                Quick.GetLogTime + " FOOD_TEST 显示蛇 吃到了食物",
                                "roleId:" + playerSnake.tag.roleId,
                                "foodIds:[" + foodIds + "], totalScore:" + totalScore,
                                "newLen:" + newLen,
                                "currentFrame:" + FrameSyncManager.getClientRuningFrame(isLogicSnake),
                                "isLogicSnake:" + isLogicSnake,
                                "hasConfirmed:" + hasConfirmed
                            );
                        // if (!isLogicSnake) {
                        //     //不是运行确认帧的时候发送
                        //     var roleId = playerSnake.tag.roleId; // GlobalDataManager.instance.playerDto.pid;
                        //     var head = playerSnake.getToServerHead(isLogicSnake);
                        //     var cmdId = com.snake.socket.MessageType.MSG_EAT_FOOD;
                        //     var o = com.snake.socket.CS_EAT_FOOD.fromObject({
                        //         roleId: roleId,
                        //         fid: foodIds,
                        //         head: head,
                        //         frame: FrameSyncManager.getClientRuningFrame(isLogicSnake)
                        //     });
                        //     // ======提示====   3-4、要吃的食物还发给服务器作弊验证用
                        //     RoomWebSocket.sendData(cmdId, o);
                        // }
                    }
                }
            }

            // if (isLogicSnake) {
            const snakeCandidates = SnakeManager.getInstance().getBodySkinsWithOutOne(playerSnake, isLogicSnake);
            // console.log("snakeCandidates: ", snakeCandidates, playerSnake.tag.roleId, isLogicSnake);

            // 2. 蛇间碰撞检测
            // const snakeCandidates = collision.retrieve(playerSnake.getHead())
            //     .filter(obj => obj instanceof BodySkin);
            for (const skin of snakeCandidates) {
                var otherSnake = skin.owner.owner;
                if (otherSnake !== playerSnake && playerSnake.checkBodyCollision(skin, isLogicSnake)) {
                    if (!playerSnake.isInvincible(isLogicSnake) && !otherSnake.isInvincible(isLogicSnake)) {
                        //如果都不处于无敌状态，才会死亡
                        if (
                            playerSnake.isAlive(isLogicSnake) &&
                            otherSnake.isAlive(isLogicSnake) &&
                            !playerSnake.isViewReadyDie &&
                            !otherSnake.isViewReadyDie
                        ) {
                            var needDie = false;
                            var isBody = !skin.isHead;
                            if (isBody) {
                                needDie = true;
                            } else {
                                // 如果是头部，长度小于等于的死亡
                                if (playerSnake.len(isLogicSnake) < otherSnake.len(isLogicSnake)) {
                                    needDie = true;
                                } else if (playerSnake.len(isLogicSnake) == otherSnake.len(isLogicSnake)) {
                                    //长度一样
                                    if (playerSnake.tag.enterTime >= otherSnake.tag.enterTime) {
                                        //进入时间慢的死亡
                                        needDie = true;
                                    }
                                }
                                if (needDie == false) {
                                    return; //如果碰到头，但是检测没有死，则跳过这条蛇的检测，留给别的蛇的蛇头来检测
                                }
                            }

                            if (needDie) {
                                // ======提示====   3-5、蛇头碰到别的蛇死亡，客户端先闪烁2秒，等收到服务端确认(主动确认或被动确认)后再死亡
                                playerSnake.readyDie();

                                // var isBody = !skin.isHead;

                                // var target = skin.owner.tag.roleId;
                                // var head = playerSnake.getToServerHead(isLogicSnake);
                                // var cmdId = com.snake.socket.MessageType.MSG_PLAYER_COLLISION;
                                // var o = com.snake.socket.CS_PLAYER_COLLISION.fromObject({
                                //     roleId: playerSnake.tag.roleId,
                                //     target: target,
                                //     head: head,
                                //     frame: FrameSyncManager.getClientRuningFrame(isLogicSnake),
                                //     body: isBody
                                // });
                                // RoomWebSocket.sendData(cmdId, o);
                                playerSnake.setIsSend(true, isLogicSnake);
                                return;
                            }
                        }

                        // skin.owner.addKill();
                    } else {
                        console.log(playerSnake.tag.roleId + " 或者 " + skin.owner.tag.roleId + " 处于无敌状态！");
                    }
                }
            }
            // }
        }
    }

    public static checkCollisionsWithConfirm(playerSnake: Snake, foodManager: any, collision: Collision, hasConfirmed: boolean): void {
        var isLogicSnake: boolean = true;
        // console.log("碰撞检测");
        // if (!playerSnake.isAlive()) return;
        if (playerSnake.getIsSend(isLogicSnake)) {
            return;
        }
        // if (!hasConfirmed && !playerSnake.isViewReadyDie) {//假如显示蛇已经死了，则包含使用预测蛇检测，防止到边界，服务器不发确认帧，导致不触发逻辑蛇碰撞检测
        if (!hasConfirmed) {
            return;
        }
        const mapSize = Constants.mapSize;

        // ======提示====   3-1、客户端检测所有蛇的碰撞（边界检测+食物+蛇）
        if (playerSnake && playerSnake.tag) {
            // 1. 地图边界碰撞检测
            const headBounds = playerSnake.getHeadCollisionBounds(isLogicSnake);
            if (headBounds) {
                const isOutOfBounds =
                    headBounds.x < mapSize.offsetX ||
                    headBounds.x + headBounds.width > mapSize.width - mapSize.offsetX ||
                    headBounds.y < mapSize.offsetY ||
                    headBounds.y + headBounds.height > mapSize.height - mapSize.offsetY;

                if (isOutOfBounds) {
                    if (playerSnake.isAlive(isLogicSnake)) {
                        playerSnake.sendDie();

                        // var head = playerSnake.getToServerHead(isLogicSnake);
                        var head = playerSnake.getToLoogicServerHead(isLogicSnake);
                        var cmdId = com.snake.socket.MessageType.MSG_PLAYER_COLLISION;
                        var o1 = com.snake.socket.CS_PLAYER_COLLISION.fromObject({
                            roleId: playerSnake.tag.roleId,
                            head: head,
                            frame: FrameSyncManager.getClientRuningFrame(isLogicSnake),
                            body: false
                        });
                        if (!MatchModel.matchWatcher) {
                            RoomWebSocket.sendData(cmdId, o1);
                        }

                        playerSnake.setIsSend(true, isLogicSnake);
                    }

                    return;
                }
            }

            if (playerSnake.isAlive(isLogicSnake) && !playerSnake.getIsStop(isLogicSnake)) {
                // 1. 食物碰撞检测
                // 获取蛇头位置和碰撞半径

                // 获取蛇头中心位置和碰撞半径
                const headBounds = playerSnake.getHeadCollisionBounds(isLogicSnake);
                if (!headBounds) {
                    return;
                }

                if (hasConfirmed) {
                    // 确认帧之前的食物不吃
                    const foodCandidates = FoodManager.getAllFoods();

                    // const foodCandidates = collision.retrieve(playerSnake.getHead())
                    // .filter(obj => obj instanceof Food);

                    // console.log("foodCandidates 长度：" + foodCandidates.length);
                    var foodIds: string[] = [];
                    var totalAddScore: number = 0;
                    foodCandidates.forEach((food: Food) => {
                        if (!food.getHaveEaten(hasConfirmed)) {
                            if (playerSnake.checkFoodCollision(food, isLogicSnake)) {
                                // ======提示====   3-2、客户端检测到碰撞食物，就显示吃掉
                                if (GameSetting.Debug == 2)
                                    console.log(
                                        Quick.GetLogTime + " FOOD_TEST 逻辑蛇 确认帧 吃 foodId：",
                                        food.foodObject.unkey,
                                        "currentFrame:" + FrameSyncManager.getClientRuningFrame(isLogicSnake),
                                        "isLogicSnake:" + isLogicSnake,
                                        "hasConfirmed:" + hasConfirmed
                                    );
                                food.beEattenByPlayerSnake(playerSnake, isLogicSnake, hasConfirmed);
                                // food.setHaveEaten(true, isLogicSnake);
                                // var isEaten = SnakeManager.getInstance().checkFoodEatByServer(roleId, food.foodObject.unkey);

                                // console.log(food.foodObject.unkey, food.getPosition());
                                foodIds.push(food.foodObject.unkey);
                                var addScore = food.getScore();
                                // if(Tool.getRandInRound(0, 99) < playerSnake.getDoublePointsProbability()){
                                //     addScore *= 2;
                                // }
                                totalAddScore += addScore;
                            }
                        }
                    });
                    if (foodIds && foodIds.length > 0) {
                        // ======提示====   3-3、客户端根据公式，计算分数和长度
                        var msgEatFoodBody: SC_EAT_FOOD = new SC_EAT_FOOD();
                        msgEatFoodBody.fid = foodIds; //食物id
                        msgEatFoodBody.score = totalAddScore; // 10;//当前积分 根据配置计算
                        var totalScore = playerSnake.getScore(isLogicSnake) + totalAddScore; // 10;//当前积分 根据配置计算

                        var skinLength = playerSnake.getSkinLength(isLogicSnake);

                        var snakeId = playerSnake.tag.snakeId;

                        //当前长度 TODO://根据配置计算
                        var newLen = SnakeManager.getInstance().countSnakeLen(
                            snakeId,
                            skinLength,
                            totalScore,
                            playerSnake.intervalBoneToDrawSkin(isLogicSnake)
                        );
                        // console.log(playerSnake.tag.roleId + " === 当前长度：" + newLen, snakeId, skinLength, totalScore);
                        // playerSnake.score = totalScore;
                        msgEatFoodBody.lenght = newLen;

                        msgEatFoodBody.roleId = playerSnake.tag.roleId; //玩家id
                        msgEatFoodBody.score = totalScore; //总分数
                        msgEatFoodBody.remain = []; //剩余未吃掉的食物
                        SnakeManager.getInstance().eatFoodAndAddScore(msgEatFoodBody, isLogicSnake);
                        if (GameSetting.Debug == 2) {
                            console.log(
                                Quick.GetLogTime + " FOOD_TEST SEND 112 逻辑蛇 确认帧 吃到了食物",
                                "roleId:" + playerSnake.tag.roleId,
                                "foodIds:[" + foodIds + "], totalScore:" + totalScore,
                                "newLen:" + newLen,
                                "currentFrame:" + FrameSyncManager.getClientRuningFrame(isLogicSnake),
                                "isLogicSnake:" + isLogicSnake,
                                "hasConfirmed:" + hasConfirmed
                            );
                        }

                        // if (isLogicSnake) {
                        //不是运行确认帧的时候发送
                        var roleId = playerSnake.tag.roleId; // GlobalDataManager.instance.playerDto.pid;
                        var head = playerSnake.getToServerHead(isLogicSnake);
                        var cmdId = com.snake.socket.MessageType.MSG_EAT_FOOD;
                        var o = com.snake.socket.CS_EAT_FOOD.fromObject({
                            roleId: roleId,
                            fid: foodIds,
                            head: head,
                            frame: FrameSyncManager.getClientRuningFrame(isLogicSnake)
                        });
                        // ======提示====   3-4、要吃的食物还发给服务器作弊验证用
                        if (!MatchModel.matchWatcher) {
                            RoomWebSocket.sendData(cmdId, o);
                        }

                        // }
                    }
                }
            }
            if (!hasConfirmed) {
                return;
            }
            // if (isLogicSnake) {
            const snakeCandidates = SnakeManager.getInstance().getBodySkinsWithOutOne(playerSnake, isLogicSnake);
            // console.log("snakeCandidates: ", snakeCandidates, playerSnake.tag.roleId, isLogicSnake);

            // 2. 蛇间碰撞检测
            // const snakeCandidates = collision.retrieve(playerSnake.getHead())
            //     .filter(obj => obj instanceof BodySkin);
            for (const skin of snakeCandidates) {
                var otherSnake = skin.owner.owner;
                if (otherSnake !== playerSnake && playerSnake.checkBodyCollision(skin, isLogicSnake)) {
                    if (!playerSnake.isInvincible(isLogicSnake) && !otherSnake.isInvincible(isLogicSnake)) {
                        //如果都不处于无敌状态，才会死亡
                        if (
                            playerSnake.isAlive(isLogicSnake) &&
                            otherSnake.isAlive(isLogicSnake) &&
                            !playerSnake.isLogicReadyDie &&
                            !otherSnake.isLogicReadyDie
                        ) {
                            var needDie = false;
                            var isBody = !skin.isHead;
                            if (isBody) {
                                needDie = true;
                            } else {
                                var playerSnakeLen = playerSnake.len(isLogicSnake);
                                var otherSnakeLen = otherSnake.len(isLogicSnake);
                                // 如果是头部，长度小于等于的死亡
                                if (playerSnakeLen < otherSnakeLen) {
                                    needDie = true;
                                } else if (playerSnakeLen == otherSnakeLen) {
                                    //长度一样
                                    if (playerSnake.tag.enterTime >= otherSnake.tag.enterTime) {
                                        //进入时间慢的死亡
                                        needDie = true;
                                    }
                                }
                                if (needDie == false) {
                                    return; //如果碰到头，但是检测没有死，则跳过这条蛇的检测，留给别的蛇的蛇头来检测
                                }
                            }

                            if (needDie) {
                                // ======提示====   3-5、蛇头碰到别的蛇死亡，客户端先闪烁2秒，等收到服务端确认(主动确认或被动确认)后再死亡
                                playerSnake.sendDie();

                                var isBody = !skin.isHead;

                                var target = skin.owner.tag.roleId;
                                console.warn(
                                    `Snake DIE ${playerSnake.tag.roleId} `,
                                    "sendDie playerSnakeLen: " + playerSnakeLen,
                                    "enterTime: " + playerSnake.tag.enterTime,
                                    "target: " + target,
                                    "otherSnakeLen: " + otherSnakeLen,
                                    "otherSnake enterTime: " + otherSnake.tag.enterTime,
                                    "isBody: " + isBody,
                                    "clientRuningFrame: " + FrameSyncManager.clientRuningFrame
                                );
                                var head = playerSnake.getToLoogicServerHead(isLogicSnake);
                                var cmdId = com.snake.socket.MessageType.MSG_PLAYER_COLLISION;
                                var o1 = com.snake.socket.CS_PLAYER_COLLISION.fromObject({
                                    roleId: playerSnake.tag.roleId,
                                    target: target,
                                    head: head,
                                    frame: FrameSyncManager.getClientRuningFrame(isLogicSnake),
                                    body: isBody,
                                    point: skin.getCollisionPoint(),
                                    thead: skin.getThead()
                                });
                                if (!MatchModel.matchWatcher) {
                                    RoomWebSocket.sendData(cmdId, o1);
                                }

                                console.warn(Quick.GetLogTime + "Snake DIE CMD:113 发送了 玩家 " + o1.roleId + " 碰撞 数据", o1);

                                playerSnake.setIsSend(true, isLogicSnake);
                                return;
                            }
                        }

                        // skin.owner.addKill();
                    } else {
                        console.log(playerSnake.tag.roleId + " 或者 " + skin.owner.tag.roleId + " 处于无敌状态！");
                    }
                }
            }
        }
    }

    public static checkCollisionsWithPve(playerSnake: AiSnake, foodManager: any, collision: Collision, hasConfirmed: boolean): void {
        // console.log("碰撞检测");
        // if (!playerSnake.isAlive()) return;
        var isLogicSnake = false;

        const mapSize = Constants.mapSize;

        // ======提示====   3-1、客户端检测所有蛇的碰撞（边界检测+食物+蛇）
        if (playerSnake && playerSnake.tag) {
            if (GameSetting.Debug == 2) console.log("碰撞检测", playerSnake.tag.roleId);
            // 1. 地图边界碰撞检测
            const headBounds = playerSnake.getHeadCollisionBounds(isLogicSnake);
            if (headBounds) {
                var offsetX = mapSize.offsetX;
                var offsetY = mapSize.offsetY;
                if (playerSnake.isAi) {
                    offsetX += 50;
                    offsetY += 50;
                }

                const isOutOfBounds =
                    headBounds.x < offsetX ||
                    headBounds.x + headBounds.width > mapSize.width - offsetX ||
                    headBounds.y < offsetY ||
                    headBounds.y + headBounds.height > mapSize.height - offsetY;

                if (isOutOfBounds) {
                    if (playerSnake.isAlive(isLogicSnake)) {
                        if (playerSnake.isAi) {
                            var targetPos = Vec2.create(mapSize.width / 2, mapSize.height / 2);
                            playerSnake.goTargetPos(targetPos);
                        } else {
                            playerSnake.pveDie();
                        }
                    }

                    return;
                }
            }

            if (playerSnake.isAlive(isLogicSnake) && !playerSnake.getIsStop(isLogicSnake)) {
                // 1. 食物碰撞检测
                // 获取蛇头位置和碰撞半径

                // 获取蛇头中心位置和碰撞半径
                const headBounds = playerSnake.getHeadCollisionBounds(isLogicSnake);
                if (!headBounds) {
                    return;
                }

                if (hasConfirmed) {
                    // 确认帧之前的食物不吃
                    // const foodCandidates = FoodManager.getAllFoods();

                    const foodCandidates = collision.retrieve(playerSnake.getHead(isLogicSnake)).filter((obj) => obj instanceof Food);

                    var foodIds: string[] = [];
                    var foodKeys: string[] = [];
                    var totalAddScore: number = 0;
                    foodCandidates.forEach((food: Food) => {
                        foodKeys.push(food.foodObject.unkey);
                        if (!food.getHaveEaten(hasConfirmed)) {
                            // console.log("客户端 吃：", food.foodObject.unkey, isLogicSnake);
                            if (playerSnake.checkFoodCollision(food, isLogicSnake)) {
                                // ======提示====   3-2、客户端检测到碰撞食物，就显示吃掉
                                // console.log("客户端先吃：", food.foodObject.unkey, isLogicSnake);
                                food.beEattenByPlayerSnake(playerSnake, isLogicSnake, hasConfirmed);
                                // food.setHaveEaten(true, isLogicSnake);
                                // var isEaten = SnakeManager.getInstance().checkFoodEatByServer(roleId, food.foodObject.unkey);

                                // console.log(food.foodObject.unkey, food.getPosition());
                                foodIds.push(food.foodObject.unkey);
                                var addScore = food.getScore();
                                // if(Tool.getRandInRound(0, 99) < playerSnake.getDoublePointsProbability()){
                                //     addScore *= 2;
                                // }
                                totalAddScore += addScore;
                            }
                        }
                    });
                    // if(GameSetting.Debug == 2)
                    // console.log("foodCandidates 长度：" + foodCandidates.length, foodKeys, foodIds);
                    if (foodIds && foodIds.length > 0) {
                        // ======提示====   3-3、客户端根据公式，计算分数和长度
                        var msgEatFoodBody: SC_EAT_FOOD = new SC_EAT_FOOD();
                        msgEatFoodBody.fid = foodIds; //食物id
                        msgEatFoodBody.score = totalAddScore; // 10;//当前积分 根据配置计算
                        var totalScore = playerSnake.getScore(isLogicSnake) + totalAddScore; // 10;//当前积分 根据配置计算

                        var skinLength = playerSnake.getSkinLength(isLogicSnake);

                        var snakeId = playerSnake.tag.snakeId;

                        //当前长度 TODO://根据配置计算
                        var newLen = SnakeManager.getInstance().countSnakeLen(
                            snakeId,
                            skinLength,
                            totalScore,
                            playerSnake.intervalBoneToDrawSkin(isLogicSnake)
                        );
                        // console.log(playerSnake.tag.roleId + " === 当前长度：" + newLen, snakeId, skinLength, totalScore);
                        // playerSnake.score = totalScore;
                        msgEatFoodBody.lenght = newLen;

                        msgEatFoodBody.roleId = playerSnake.tag.roleId; //玩家id
                        msgEatFoodBody.score = totalScore; //总分数
                        msgEatFoodBody.remain = []; //剩余未吃掉的食物
                        SnakeManager.getInstance().eatFoodAndAddScore(msgEatFoodBody, isLogicSnake);
                    }
                }
            }

            // if (isLogicSnake) {
            // const snakeCandidates = SnakeManager.getInstance().getBodySkinsWithOutOne(playerSnake, isLogicSnake);

            // 2. 蛇间碰撞检测
            const snakeCandidates = collision.retrieve(playerSnake.getHead(isLogicSnake)).filter((obj) => obj instanceof BodySkin);

            // console.log("snakeCandidates: ", snakeCandidates.length, playerSnake.tag.roleId, isLogicSnake);
            for (const skin of snakeCandidates) {
                var otherSnake = skin.owner.owner;
                if (otherSnake !== playerSnake && playerSnake.checkBodyCollision(skin, isLogicSnake)) {
                    if (!playerSnake.isInvincible(isLogicSnake) && !otherSnake.isInvincible(isLogicSnake)) {
                        // 如果都不处于无敌状态，才会死亡
                        if (
                            playerSnake.isAlive(isLogicSnake) &&
                            otherSnake.isAlive(isLogicSnake) &&
                            !playerSnake.isViewReadyDie &&
                            !otherSnake.isViewReadyDie
                        ) {
                            var needDie = false;
                            var isBody = !skin.isHead;
                            if (isBody) {
                                needDie = true;
                            } else {
                                // 如果是头部，长度小于等于的死亡
                                if (playerSnake.len(isLogicSnake) < otherSnake.len(isLogicSnake)) {
                                    needDie = true;
                                } else if (playerSnake.len(isLogicSnake) == otherSnake.len(isLogicSnake)) {
                                    // 长度一样
                                    if (playerSnake.tag.enterTime >= otherSnake.tag.enterTime) {
                                        // 进入时间慢的死亡
                                        needDie = true;
                                    }
                                }
                                if (needDie == false) {
                                    return; //如果碰到头，但是检测没有死，则跳过这条蛇的检测，留给别的蛇的蛇头来检测
                                }
                            }

                            if (needDie) {
                                playerSnake.pveDie();
                                otherSnake.addKill(1); //显示kill + 1
                                //击杀时也增加积分 = 查询当前节数所消耗积分(当前节数) / 3
                                // var otherSnake: Snake = skin.owner.owner;

                                var snakeLengthRuleItem: SnakeLengthRuleItem = SheetDataManager.getSheetDataByMultiKey(
                                    SheetDataManager.m_dicSnakeLengthRules,
                                    [otherSnake.tag.snakeId, otherSnake.getSkinLength(false)]
                                );
                                var totalAddScore = Math.ceil(snakeLengthRuleItem.consumePoints / 3);

                                var msgEatFoodBody: SC_EAT_FOOD = new SC_EAT_FOOD();
                                msgEatFoodBody.fid = []; //食物id
                                msgEatFoodBody.score = totalAddScore; // 10;//当前积分 根据配置计算
                                var totalScore = otherSnake.getScore(isLogicSnake) + totalAddScore; // 10;//当前积分 根据配置计算

                                var skinLength = otherSnake.getSkinLength(isLogicSnake);

                                var snakeId = otherSnake.tag.snakeId;

                                //当前长度 根据配置计算
                                var newLen = SnakeManager.getInstance().countSnakeLen(
                                    snakeId,
                                    skinLength,
                                    totalScore,
                                    otherSnake.intervalBoneToDrawSkin(isLogicSnake)
                                );
                                // console.log(otherSnake.tag.roleId + " === 当前长度：" + newLen, snakeId, skinLength, totalScore);
                                // otherSnake.score = totalScore;
                                msgEatFoodBody.lenght = newLen;

                                msgEatFoodBody.roleId = otherSnake.tag.roleId; //玩家id
                                msgEatFoodBody.score = totalScore; //总分数
                                msgEatFoodBody.remain = []; //剩余未吃掉的食物
                                SnakeManager.getInstance().eatFoodAndAddScore(msgEatFoodBody, isLogicSnake);

                                break; // 跳出循环
                            }
                        }
                    } else {
                        console.log(playerSnake.tag.roleId + " 或者 " + skin.owner.tag.roleId + " 处于无敌状态！");
                    }
                }
            }
            // }
        }
    }
}
