@regClass('0r0gyiRERf6yXTGaGqWBvg==')
export class SnakeMatchScene extends SnakeMatchSceneBase {
    public m_iLayerType: number;
    public m_iPositionType: number;
    private liveNum: number = 0;

    private isWatch: boolean = false;
    private watchEnterTime: number = 0;
    onAwake(): void {
        this.m_iLayerType = LayerManager.M_POP;
        this.m_iPositionType = LayerManager.UP;
    }

    onEnable(): void {
        Signal.on(GameEvent.EVENT_PVP_INIT_DATA, this, this.onInitData);
        Signal.on(GameEvent.EVENT_PVP_RESTORE_DATA, this, this.onRestoreData);

        Signal.on(GameEvent.EVENT_GameScene_Gray, this, this.onGameSceneGray);
        Signal.on(GameEvent.EVENT_CLICK_SPACE, this, this.onSpaceClick);

        // 注册窗口获得焦点事件
        Laya.stage.on(Laya.Event.FOCUS, this, this.onWindowFocus);

        // 在游戏初始化代码中添加
        Laya.stage.on(Laya.Event.KEY_DOWN, this, this.onKeyDown);
        this.matchRuleTipSpr.visible = false;
    }
    onOpened(_isWatch: any): void {
        this.isWatch = _isWatch;
        // ModuleManager.intance.openModule(ModuleName.MatchReadyView);

        this.list_rank.array = [];

        var matchMap1001: any = this.map_1001;
        MapManager.gameMap = matchMap1001;

        MapManager.img_smallMap = this.img_smallMap;

        this.init();

        this.playMusic();

        if (this.isWatch) {
            // this.img_mySnake.visible = false; //观看者不显示蛇成长信息
            this.btn_gift.visible = false; //观看者不显示蛇成长信息
            this.box_skills.visible = false; //观看者技能容器不显示
            this.box_items.visible = false; //观看者不显示蛇成长信息

            this.btn_exit.on(Laya.Event.CLICK, this, this.onExitClick);

            // this.img_kill.visible = false; //观看者不显示击杀数
            this.box_skills.visible = false; //观看者技能容器不显示

            this.img_smallMap.on(Laya.Event.CLICK, this, this.onSmallMapClick);

            // // 确保stage也能接受点击事件，用于调试
            // Laya.stage.on(Laya.Event.CLICK, this, this.onStageClick);
        }

        this.btn_exit.visible = this.isWatch; //观看者是否显示退出
        this.tf_live.visible = this.isWatch; //观看者是否显示LIVE

        if (this.isWatch) {
            this.watchEnterTime = Laya.Browser.now();
            // this.onInitData();
        }
    }

    // onStageClick(e: Laya.Event) {
    //     console.log("onStageClick: ", e.stageX, e.stageY, e);
    // }

    onSmallMapClick(e: Laya.Event) {
        var globalP = new Laya.Point(e.stageX, e.stageY);
        // console.log("onMouseMove e.stage: ", e.stageX, e.stageY);
        /**将舞台坐标转换为本地坐标 */
        const localP = this.img_smallMap.globalToLocal(globalP, false);
        MapManager.clickSmallMapToMove(localP);

        console.log("onSmallMapClick: ", e.stageX, e.stageY, "====", localP.x, localP.y);
    }
    playMusic() {
        SoundMgr.playMusicByURL("mp3/battle.mp3");
        GetItemDataModel.needPop = false;
    }

    async onExitClick() {
        if (this.isWatch) {
            SceneManager.setCurrentScene(SceneType.M_SCENE_MAIN);
        } else {
            console.log("不是观察者，不能退出");
        }
    }

    public init(): void {
        this.registerEvents();
        this.btn_addSpeed.on(Laya.Event.MOUSE_DOWN, this, this.onTouchSpeedDown);
        this.btn_addSpeed.on(Laya.Event.MOUSE_UP, this, this.onTouchSpeedUp);
        this.btn_addSpeed.on(Laya.Event.MOUSE_OUT, this, this.onTouchSpeedUp);
        // 传入游戏节点与摇杆节点初始化 SnakeManager
        GameControl.init(this.gameLayer);
    }

    lastSeedRate: number = 0;

    public onTouchSpeedDown(e: Laya.Event): void {
        if (e) {
            var eventType = e.type;
            e.stopPropagation();
            console.log("onTouchSpeedDown " + e.type);
        }
        if (this.lastSeedRate != Constants.snakeSpeedRate.speedUp) {
            this.lastSeedRate = Constants.snakeSpeedRate.speedUp;
            // const instance = GameControl.getInstance();
            SnakeManager.getInstance().updateSpeedRate(Constants.snakeType.SELF, Constants.snakeSpeedRate.speedUp); //speedUp = 2倍
        }
    }
    public onTouchSpeedUp(e: Laya.Event): void {
        if (e) {
            var eventType = e.type;
            e.stopPropagation();
            console.log("onTouchSpeedUp " + e.type);
            BtnColorFilter.clearClickFilter(e.target);
        }

        if (this.lastSeedRate != Constants.snakeSpeedRate.default) {
            this.lastSeedRate = Constants.snakeSpeedRate.default;
            // const instance = GameControl.getInstance();
            SnakeManager.getInstance().updateSpeedRate(Constants.snakeType.SELF, Constants.snakeSpeedRate.default); //speedUp = 1倍
        }
    }

    onSpaceClick(_isSpeedUp: boolean) {
        if (_isSpeedUp) {
            this.onTouchSpeedDown(null);
            BtnColorFilter.addClickFilter(this.btn_addSpeed);
        } else {
            this.onTouchSpeedUp(null);
            BtnColorFilter.clearClickFilter(this.btn_addSpeed);
        }
    }

    startGameLoop() {
        Laya.timer.frameLoop(10, this, this.gameLoop);
    }

    //============== snake begin =================

    private registerEvents(): void {
        // Signal.on(GameEvent.LENGTH_CHANGE, this, this.updateLength);
        // Signal.on(GameEvent.KILL_SNAKE, this, this.updateKills);
    }

    public removeEvents(): void {
        // Signal.off(GameEvent.LENGTH_CHANGE, this, this.updateLength);
        // Signal.off(GameEvent.KILL_SNAKE, this, this.updateKills);
    }

    SnakeAINum: number = 5; // AI 蛇的数量
    snakeAIArr: Array<MatchSnakeSpr> = []; // AI 蛇的数组

    /**
     * 游戏主循环
     */
    gameLoop(): void {
        if (MatchModel.matchWatcher) {
            if (MapManager.targetHeroSpr && MapManager.targetHeroSpr.tag) {
                this.updateLength(MapManager.targetHeroSpr.getSkinLength(true));

                this.updateKills(MapManager.targetHeroSpr.tag.kills);
                // this.updateSnakeLengthRule();
                this.text_score.text = MapManager.targetHeroSpr.tag.userName + "";
            } else {
                this.text_score.text = "";
                this.text_kill.text = "0";
                this.text_length.text = "0";
            }
        } else {
            if (SnakeManager.getInstance().selfSnake) {
                if (SnakeManager.getInstance().selfSnake.tag) {
                    this.updateLength(SnakeManager.getInstance().selfSnake.getSkinLength(true));

                    this.updateKills(SnakeManager.getInstance().selfSnake.tag.kills);
                    this.updateSnakeLengthRule();
                }
            }
        }

        if (SnakeManager.getInstance().matchHeroSprDic) {
            this.list_rank.array = this.getSortPlayer(SnakeManager.getInstance().matchHeroSprDic.values);
            this.tf_remainer.text = this.liveNum + "";
            if (this.isWatch) {
                if (this.liveNum <= 0) {
                    this.stopUpdate();
                    Quick.popToMain(2003, false);
                    return;
                }
            } else {
                if (this.liveNum == 1) {
                    this.openMatchRuleTipSpr();
                }
            }
        }
    }

    /**
     * 是否提示过
     */
    private isMatchRuleOpen = false;
    private openMatchRuleTipSpr(): void {
        if (!this.isMatchRuleOpen) {
            //一场比赛弹一次
            this.isMatchRuleOpen = true;

            Quick.showMatchRuleTip(
                EnumState.RULE_PVP,
                GameLanguageMgr.getLanguage(610103),
                GameLanguageMgr.getLanguage(610106),
                this.matchRuleTipSpr
            );
        }
    }

    /**
     * 点击规则
     */
    private onClickRule() {
        Quick.showRuleTip(EnumState.RULE_PVP, GameLanguageMgr.getLanguage(610103), GameLanguageMgr.getLanguage(610106));
    }

    private updateKills(kills: number): void {
        this.text_kill.text = `${kills}`; //击杀
    }

    public updateLength(length: number): void {
        this.text_length.text = `${length}`; //长度
    }

    updateSnakeLengthRule() {
        var snakeId = SnakeManager.getInstance().selfSnake.tag.snakeId;
        var skinLength = SnakeManager.getInstance().selfSnake.getSkinLength(true);

        var snakeLengthRuleItem: SnakeLengthRuleItem = SheetDataManager.getSheetDataByMultiKey(SheetDataManager.m_dicSnakeLengthRules, [
            snakeId,
            skinLength
        ]);
        var nextSnakeLengthRuleItem: SnakeLengthRuleItem = SheetDataManager.getSheetDataByMultiKey(SheetDataManager.m_dicSnakeLengthRules, [
            snakeId,
            skinLength + 1
        ]);
        var score = SnakeManager.getInstance().selfSnake.getScore(true);
        if (snakeLengthRuleItem && nextSnakeLengthRuleItem) {
            var currScore = score - snakeLengthRuleItem.accumulatePoints;
            var needScore = nextSnakeLengthRuleItem.accumulatePoints - snakeLengthRuleItem.accumulatePoints;
            this.text_score.text = `${currScore}/${needScore}`;

            var maskWidth = (currScore / needScore) * -180;
            if (maskWidth < -180) {
                maskWidth = -180;
            } else if (maskWidth > 0) {
                maskWidth = 0;
            }
            if (this.img_socre_mask.rotation > maskWidth) {
                Laya.Tween.to(this.img_socre_mask, { rotation: maskWidth }, 100);
            } else {
                Laya.Tween.clearAll(this.img_socre_mask);
                this.img_socre_mask.rotation = maskWidth;
                this.img_socre_mask.rotation = maskWidth;
            }

            // var maskWidth = (currScore / needScore) * 185;
            // // console.log("score", score, snakeLengthRuleItem.accumulatePoints, currScore, needScore, maskWidth);
            // if (maskWidth < 0) {
            //     maskWidth = 0;
            // }
            // if (this.img_socre_mask.width < maskWidth) {
            //     Laya.Tween.to(this.img_socre_mask, { width: maskWidth }, 100);
            // } else {
            //     Laya.Tween.clearAll(this.img_socre_mask);
            //     this.img_socre_mask.width = maskWidth;
            // }
        }
    }

    onInitData() {
        var roomId = MatchModel.matchDto.roomNo;
        if (roomId) {
            this.arenaNo.text = roomId + "";
        } else {
            this.arenaNo.text = "";
        }
        GameControl.createData();
        GameControl.startGame(true);

        this.startGameLoop();
        this.updateBattleCD();
        ModuleManager.intance.disposeView(ModuleName.MatchReadyView, "must"); //关闭过渡页
    }

    onRestoreData() {
        GameControl.clearTimer();
        GameControl.restoreData();

        GameControl.startGame(false);
    }

    getSortPlayer(heros: Snake[]) {
        // 深拷贝原数组避免污染原数据
        const newHeros = heros.slice();
        // 按分数降序排序（包括死亡玩家）
        const sortedHeros = newHeros.sort((a, b) => b.getScore(true) - a.getScore(true));
        const getHeros: Snake[] = [];
        this.liveNum = 0;
        let rankNum = 1; // 改用 let 避免作用域问题

        // 遍历排序后的玩家列表
        sortedHeros.forEach((currSnake: Snake) => {
            // 标记全局排名（无论是否存活）
            currSnake.rankNum = rankNum;

            // 统计存活玩家数量
            if (currSnake.tag != null) {
                this.liveNum++;
            }

            // 仅处理存活玩家
            if (currSnake.tag != null) {
                // 前10名存活玩家直接加入
                if (rankNum <= 10) {
                    getHeros.push(currSnake);
                }
                // 当前玩家在10名外且存活时，强制加入列表（替换最后一名）
                else if (currSnake.tag.roleId === GlobalDataManager.playerDto.pid) {
                    if (getHeros.length >= 10) {
                        getHeros.splice(-1, 1, currSnake); // 替换末尾
                    } else {
                        getHeros.push(currSnake); // 若列表未满，直接加入
                    }
                }
            }

            rankNum++;
        });

        return getHeros;
    }

    public updateBattleCD(): void {
        if (this.isWatch) {
            var nowTime = Laya.Browser.now();
            MatchModel.matchCoolDownTime = Math.round((nowTime - this.watchEnterTime) / 1000);
        } else {
            MatchModel.matchCoolDownTime = Math.round(
                (MatchModel.matchDto.myPlayerObject.oprTime - MatchModel.matchDto.myPlayerObject.enterTime) / 1000
            );
        }

        this.onSetCoolTime();
        Laya.timer.loop(1000, this, this.onSetCoolTime);
    }

    private onSetCoolTime(): void {
        this.tf_reduceTime.text = TimeUtil.format(MatchModel.matchCoolDownTime, ":", false);

        if (!MatchModel.stopAll) MatchModel.matchCoolDownTime++;
    }

    private onGameSceneGray(): void {
        this.matchBox.gray = true;
        Laya.timer.once(1000, this, this.stopUpdate);
    }

    stopUpdate() {
        Laya.timer.clear(this, this.gameLoop);
        RoomWebSocket.close();
        GameControl.endTimer(); //10秒后取消定时器
    }

    onKeyDown(e: Laya.Event) {
        if (e.keyCode === Laya.Keyboard.X) {
            DebugLayer.getInstance().toggleVisible();
        }
    }

    onWindowFocus() {
        FrameSyncManager.frameNetQueue.sendRestoreData();
    }

    onDisable(): void {
        this.stopUpdate();
        Signal.off(GameEvent.EVENT_PVP_INIT_DATA, this, this.onInitData);
        Signal.off(GameEvent.EVENT_PVP_RESTORE_DATA, this, this.onRestoreData);
        Signal.off(GameEvent.EVENT_GameScene_Gray, this, this.onGameSceneGray);
        Signal.off(GameEvent.EVENT_CLICK_SPACE, this, this.onSpaceClick);
        Laya.stage.off(Laya.Event.KEY_DOWN, this, this.onKeyDown);
        this.removeEvents();

        Laya.stage.off(Laya.Event.FOCUS, this, this.onWindowFocus);
        Laya.timer.clearAll(this);
        GameControl.clear();
        MatchModel.clearData();
    }
}
