import { FoodItem } from "../../data/sheetItem/snake/FoodItem";
import { MatchSnakeBeanSpr } from "../../modules/arena/MatchSnakeBeanSpr";
import { com } from "../../network/pb/socket";
import Constants from "../../global/config/Constants";
import { MathUtil } from "../../utils/MathUtil";
import { Vec2 } from "../../utils/Vec2";
import FoodManager from "./FoodManager";
import MatchModel from "../../modules/match/MatchModel";
import { EnumMatch } from "../../data/enumData/EnumMatch";
import GameSetting from "../../global/GameSetting";
import SheetDataManager from "../../global/SheetDataManager";
import GameResourceManager from "../../common/GameResourceManager";
import Snake from "../snake/Snake";
import FrameSyncManager from "../match/FrameSyncManager";
import { Quick } from "../../utils/Quick";

/**
 * 食物类
 */
export class Food {
    /**
     * 是否客户端标识被吃了
     */
    private haveEatenClient: boolean;

    haveEatenConfirm: boolean;
    private sprite: MatchSnakeBeanSpr;
    private position: Vec2;
    private oriPos: Vec2;

    foodObject: com.snake.socket.FoodObject;

    constructor(container: Laya.Sprite, foodObject: com.snake.socket.FoodObject, isDie: boolean) {
        this.position = Vec2.create(foodObject.loc.x, foodObject.loc.y);
        this.oriPos = Vec2.create(foodObject.loc.x, foodObject.loc.y);
        this.foodObject = foodObject;
        this.init(container, isDie);
    }

    private init(container: Laya.Sprite, isDie: boolean): void {
        this.sprite = GameResourceManager.matchSnakeBeanPrefab.create() as MatchSnakeBeanSpr;

        // this.sprite = new Laya.Image();
        // this.sprite.useSourceSize = true;
        var foodItem: FoodItem = SheetDataManager.m_dicFoods.get(this.foodObject.itemId);
        this.sprite.init(foodItem);
        this._collisionRadius = foodItem.collisionRadius; //食物碰撞半径读表；

        this.sprite.pos(this.position.x, this.position.y);
        var foodScale = isDie ? 1.5 : 1;
        this.sprite.scale(foodScale, foodScale);
        this.sprite.zOrder = 0;
        container.addChild(this.sprite);

        if (GameSetting.needFoodId) {
            // 创建位置文本  后面可能用于调试
            const posText = new Laya.Label();
            posText.text = `${this.foodObject.unkey}:(${Math.round(this.position.x)}, ${Math.round(this.position.y)})`;
            posText.color = "#FFFFFF";
            posText.fontSize = 18;
            posText.font = "Arial";
            posText.align = "center";
            posText.anchorX = 0.5;
            posText.anchorY = 1; // 锚点在底部中心
            posText.stroke = 2;
            posText.strokeColor = "#000000";

            // 将文本添加到图片并定位到顶部
            posText.y = -this.sprite.height / 2 - 2; // 图片上方2像素
            this.sprite.addChild(posText);
        }

        // this.startScalingAnimation();
    }

    public reset(container: Laya.Sprite, foodObject: com.snake.socket.FoodObject, isDie: boolean): void {
        this.position = Vec2.create(foodObject.loc.x, foodObject.loc.y);
        this.oriPos = Vec2.create(foodObject.loc.x, foodObject.loc.y);
        this.foodObject = foodObject;
        this.setHaveEaten(false, true);
        this.setHaveEaten(false, false);
        // 重置其他属性...
        var foodItem: FoodItem = SheetDataManager.m_dicFoods.get(this.foodObject.itemId);
        this.sprite.init(foodItem);
        this._collisionRadius = foodItem.collisionRadius; //食物碰撞半径读表；
        this.sprite.alpha = 1;
        this.sprite.pos(this.position.x, this.position.y);
        var foodScale = isDie ? 1.5 : 1;
        this.sprite.scale(foodScale, foodScale);
        container.addChild(this.sprite);
    }

    public resetForPool(): void {
        this.setHaveEaten(false, true);
        this.setHaveEaten(false, false);
        Laya.Tween.clearAll(this.sprite);
        this.sprite.removeSelf();
        // 重置其他属性...
    }

    private minScale: number = 1; // 最小缩放比例
    private maxScale: number = 1.2; // 最大缩放比例
    private minDuration: number = 800; // 最小动画时间（毫秒）
    private maxDuration: number = 1200; // 最大动画时间（毫秒）
    private startScalingAnimation() {
        // 生成随机的缩放比例和动画时间
        let randomScale = this.minScale + Math.random() * (this.maxScale - this.minScale);
        let randomDuration = this.minDuration + Math.random() * (this.maxDuration - this.minDuration);

        // 创建放大动画
        Laya.Tween.to(
            this.sprite,
            { scaleX: randomScale, scaleY: randomScale },
            randomDuration,
            null,
            Laya.Handler.create(this, () => {
                // 动画完成后的回调，创建缩小动画
                let nextRandomScale = this.minScale + Math.random() * (1 - this.minScale); // 缩小到1以下的一个随机比例
                let nextRandomDuration = this.minDuration + Math.random() * (this.maxDuration - this.minDuration);
                Laya.Tween.to(
                    this.sprite,
                    { scaleX: nextRandomScale, scaleY: nextRandomScale },
                    nextRandomDuration,
                    null,
                    Laya.Handler.create(this, this.startScalingAnimation)
                );
            }),
            -1,
            true
        ); // -1 表示不限制次数，true 表示使用缓动效果
    }

    public getPosition(): Vec2 {
        return this.position;
    }

    // public getType(): number {
    //     return this.foodObject;
    // }

    public getScore(): number {
        var foodItem: FoodItem = SheetDataManager.m_dicFoods.get(this.foodObject.itemId);
        return foodItem.points;
    }

    public getHaveEaten(hasConfirmed: boolean): boolean {
        if (hasConfirmed) {
            return this.haveEatenConfirm;
        } else {
            return this.haveEatenClient;
        }
    }

    beEattenByPlayerSnake(snake: Snake, isLogicSnake: boolean, hasConfirmed: boolean) {
        this.setHaveEaten(true, hasConfirmed);

        this.beEatten(snake.getHead(isLogicSnake).node.x, snake.getHead(isLogicSnake).node.y, hasConfirmed);
    }

    public setHaveEaten(value: boolean, hasConfirmed: boolean) {
        if (hasConfirmed) {
            this.haveEatenConfirm = value;
        } else {
            this.haveEatenClient = value;
        }
    }

    private beEatten(x: number, y: number, hasConfirmed: boolean) {
        var foodId = this.foodObject.unkey;
        if (hasConfirmed) {
            if (GameSetting.Debug == 2)
                console.log(Quick.GetLogTime + " FOOD_TEST beEatten removeEatOperation hasConfirmed: ", hasConfirmed, " foodId: " + foodId);
            FrameSyncManager.frameNetQueue.removeEatOperation(foodId);
            //如果确认帧被吃
            // if(this.getHaveEaten(false)){//如果客户端也已经吃过了
            //     this.onFinish(true);
            // }else{
            Laya.Tween.clearAll(this.sprite); // 清除所有动画
            Laya.Tween.to(this.sprite, { x: x, y: y, alpha: 0.5 }, 200, null, Laya.Handler.create(this, this.onFinish, [true]));
            // }
        } else {
            if (MatchModel.matchDto.matchType == EnumMatch.MATCH_TYPE_PVE) {
                // PVE 吃完就清掉
                Laya.Tween.clearAll(this.sprite); // 清除所有动画
                Laya.Tween.to(this.sprite, { x: x, y: y, alpha: 0.5 }, 200, null, Laya.Handler.create(this, this.onFinish, [true]));
            } else {
                if (GameSetting.Debug == 2)
                    console.log(
                        Quick.GetLogTime + " FOOD_TEST beEatten hasConfirmed: ",
                        hasConfirmed,
                        " foodId: " + foodId,
                        " haveEatenConfirm: " + this.getHaveEaten(true)
                    );
                if (this.getHaveEaten(true)) {
                } else {
                    var halfAlpha = GameSetting.vType == 0 ? 0.5 : 0; //预测食物被吃的时候，非开发环境，完全透明
                    var frame = FrameSyncManager.getPredictFrame();

                    FrameSyncManager.frameNetQueue.addEatOperation(foodId, frame);
                    Laya.Tween.clearAll(this.sprite); // 清除所有动画
                    Laya.Tween.to(this.sprite, { x: x, y: y, alpha: halfAlpha }, 200, null, Laya.Handler.create(this, this.onFinish, [false]));
                }
            }
        }

        this.setHaveEaten(true, hasConfirmed); // 标记食物已被吃掉
    }

    private onFinish(hasConfirmed: boolean): void {
        if (hasConfirmed) {
            if (GameSetting.Debug == 2)
                console.log(
                    Quick.GetLogTime + " FOOD_TEST onFinish hasConfirmed: ",
                    hasConfirmed + "haveEatenConfirm: ",
                    this.haveEatenConfirm,
                    " foodId: " + this.foodObject.unkey
                );

            this.resetForPool(); // 重置食物对象的状态
            FoodManager.removeFood(this); // 将食物对象返回到对象池
        } else {
            this.sprite.alpha = 0.5;
        }

        // this.destroy();
    }

    restoreView() {
        if (GameSetting.Debug == 2)
            console.log(Quick.GetLogTime + " FOOD_TEST restoreView haveEatenConfirm: ", this.haveEatenConfirm, " foodId: " + this.foodObject.unkey);

        if (!this.haveEatenConfirm) {
            this.haveEatenClient = false;
            Laya.Tween.clearAll(this.sprite); // 清除所有动画
            this.position = Vec2.create(this.oriPos.x, this.oriPos.y);
            this.sprite.alpha = 1;
            this.sprite.pos(this.position.x, this.position.y);
        }
    }

    public destroy(): void {
        Laya.Tween.clearAll(this.sprite);
        this.sprite.removeSelf();
        this.sprite.destroy();
        this.sprite = null;
        this.oriPos = this.position = null;
    }

    // 新增碰撞属性
    private _collisionRadius: number = Constants.collision.food.radius;

    public getBoundingBox(): Laya.Rectangle {
        // const size = Constants.food.radius;
        return new Laya.Rectangle(
            this.position.x - this._collisionRadius,
            this.position.y - this._collisionRadius,
            this._collisionRadius * 2,
            this._collisionRadius * 2
        );
    }

    public checkCollision(x: number, y: number, radius: number): boolean {
        const center = this.position;
        return MathUtil.distance(center.x, center.y, x, y) < radius + this._collisionRadius;
    }
}
