import { Food } from "./food/Food";
import { BodySkin } from "./snake/BodySkin";

/*
 * @Descripttion:
 * @version:
 * @Author: hjy
 * @Date: 2025-02-13 16:10:05
 * @LastEditors: hjy
 * @LastEditTime: 2025-05-18 20:26:17
 */
export default class DebugLayer extends Laya.Sprite {
    private static _instance: DebugLayer;
    private collidables: any[] = [];
    private isVisible = false;

    public static getInstance(): DebugLayer {
        if (!DebugLayer._instance) {
            DebugLayer._instance = new DebugLayer();
            DebugLayer._instance.zOrder = 9999; // 确保在最顶层
            DebugLayer._instance.mouseEnabled = false;
        }
        return DebugLayer._instance;
    }

    // 切换显示状态
    public toggleVisible(): void {
        this.isVisible = !this.isVisible;

        console.log("DebugLayer.toggleVisible", this.isVisible);
        this.graphics.clear();
    }

    // 更新要绘制的碰撞体
    public updateCollidables(list: any[]): void {
        this.collidables = list;
    }

    // 绘制方法
    public clearDraw(): void {
        this.graphics.clear();
        this.graphics.alpha(0.5);
    }

    // 绘制方法
    public draw(): void {
        if (!this.isVisible) return;

        this.graphics.clear();
        this.graphics.alpha(0.5);
        this.collidables.forEach((obj) => {
            if (obj instanceof BodySkin) {
                this.drawSnakeBody(obj);
            } else if (obj instanceof Food) {
                this.drawFood(obj);
            }
        });
    }

    // 绘制蛇身体（圆形）
    private drawSnakeBody(body: BodySkin): void {
        const pos = body.getPosition();
        const radius = body.getRadio();
        this.graphics.drawCircle(pos.x, pos.y, radius, "#FF0000", 2, 0.5);
    }

    // 绘制食物（矩形框）
    private drawFood(food: Food): void {
        const rect = food.getBoundingBox();

        this.graphics.drawRect(rect.x, rect.y, rect.width, rect.height, "#00FF00", 2, 0.5);
    }
}
