    /**
     * 充值代币
     * @param tokenAddress 代币合约地址
     * @param amount 充值金额
     * @returns {Promise<boolean>} 充值是否成功
     */
    async depositWallet(tokenAddress: string, amount: any) {
        // 显示加载提示
        LoadingManager.showLoading(true);
        // 检查是否已授权合约地址操作代币
        let allow = await EthereumManager.allowanceAddressByTokenAddress(EthereumConfig.WITHDRAW_AND_RECHARGE_ADDRESS, tokenAddress);
        if (!allow) {
            // 未授权则隐藏加载并提示
            LoadingManager.hideLoading();
            NoticeMgr.notice(GameLanguageMgr.getLanguage(23));
            return;
        }
        // 将充值金额转换为Wei单位
        amount = (window as any)["web3"].utils.toWei(amount + "");
        // 调用充值合约方法
        await this.assets_contract.methods
            .recharge(tokenAddress.toLowerCase(), amount)
            .send({ from: EthereumManager.walletAddress }, (err: any, result: any) => {
                if (err) {
                    // 充值失败则隐藏加载
                    LoadingManager.hideLoading();
                    return false;
                }
            });
        return true;
    }

    private startRecharge: boolean = false;
    /**
     * 充值
     * @param params 充值参数
     * @returns
     */
    async rechargeToken(params: RechargeParams) {
        try {
            const { amount, token, rechargeAddress, decimals = 18, abi } = params;
            //判断授权
            //主链币的代币地址配置为0x0000000000000000000000000000000000000000
            if (token !== EthereumConfig.ADDRESS0) {
                let allow = await EthereumManager.newAllowanceAddress(rechargeAddress, token);
                if (!allow) {
                    LoadingManager.hideLoading();
                    NoticeMgr.notice(GameLanguageMgr.getLanguage(23));
                    return false;
                }
            }
            //授权成功
            //数量格式转化
            const amountV = parseUnits(amount + "", decimals);
            //充值合约
            let functionName: string = "depositToken";
            let hash;
            if (!token || token == EthereumConfig.ADDRESS0) {
                //主链币充值
                hash = await EthereumManager.walletClient.writeContract({
                    account: EthereumManager.walletAddress,
                    address: rechargeAddress,
                    abi: abi,
                    functionName: "depositETH",
                    value: amountV,
                    args: [100001]
                });
            } else {
                //普通币充值
                hash = await EthereumManager.walletClient.writeContract({
                    account: EthereumManager.walletAddress,
                    address: rechargeAddress,
                    abi: abi,
                    functionName: functionName,
                    args: [token, amountV, 100001]
                });
            }

            this.startRecharge = true;
            //倒计时
            Laya.timer.once(60000, this, this.clearRecharge);

            let transaction;
            let isEth = false;
            transaction = await EthereumManager.publicClient.waitForTransactionReceipt({
                hash,
                pollingInterval: 1_000
            });

            if ((transaction && transaction.status == "success") || isEth) {
                //验证成功
                if (!this.startRecharge) {
                    return;
                }
                //取消掉之前的定时器，重新计时
                Laya.timer.clear(this, this.clearRecharge);
                console.log(`Tx successful with hash: ${hash}`);
                const currentChainId = await EthereumManager.walletClient.getChainId();
                const arg = [currentChainId, hash];
                LoadingManager.hideLoading();
                // this.getReward(currentChainId, hash);
                //充值链上走完之后，轮询获得币
                // Laya.timer.loop(2000, this, this.getReward, arg);
                // Laya.timer.once(60000, this, this.clearRecharge);
                return hash;
            } else {
                LoadingManager.hideLoading();
                Quick.TransactionErrorTip(); //提示交易失败
                return undefined;
            }
        } catch (err) {
            LoadingManager.hideLoading();
            console.log(err);
            if (err instanceof Error) {
                const errorMessage = err.message;
                if (errorMessage.includes("does not match the target chain for the transaction")) {
                    Signal.event(GameEvent.CHANGE_ASSET_CHAIN);
                } else {
                    console.log("Error message does not contain the specified character.");
                }
            } else {
                console.log("An error occurred, but it is not an instance of Error.");
            }
        }
    }

