    /**
     * TON钱包充值
     * @param params TON充值参数
     * @returns 交易哈希或undefined（失败时）
     */
    async rechargeTON(params: TonRechargeParams) {
        try {
            // 显示加载中提示
            LoadingManager.showLoadingByInfo();
            
            const { amount, token, rechargeAddress, decimals = 9, comment = "" } = params;
            
            // 获取tonConnectUI全局实例
            const tonConnectUI = EthereumManager.tonConnectUI;
            if (!tonConnectUI) {
                console.error("未找到tonConnectUI实例，尝试重新连接钱包");
                
                // // 尝试连接钱包
                // await EthereumManager.connectTonWallEthereumManager.tonConnectUI           // 重新获取实例，通过检查tonConnectUI和钱包地址判断是否连接成功
                // const reconnectedUI = (wEthereumManager.tonConnectUI;                if (!reconnectedUI || !EthereumManager.walletAddress) {
                //     LoadingManager.hideLoading();
                //     NoticeMgr.notice(GameLanguageMgr.getLanguage(62)); // 连接钱包失败
                //     return false;
                // }
            }
            
            // 检查钱包地址
            if (!EthereumManager.walletAddress) {
                LoadingManager.hideLoading();
                NoticeMgr.notice(GameLanguageMgr.getLanguage(62));
                return false;
            }
            
            // 构建特定格式的字符串：用户ID|时间戳
            const time = Math.floor(Date.now() / 1000) + 600; // 10分钟有效期
            
            // 获取用户ID，如果不存在则使用钱包地址
            const userId = ((window as any).PlayerModel?.inst?.tg_userInfo?.id) || 
                           EthereumManager.walletAddress.substring(0, 8);
            const str = `${userId}|${time}`;
            
            // 创建一个TON Cell（这段代码仅用于示例，不影响实际流程）
            // try {
            //     const cell = beginCell()
            //         .storeUint(0, 32)
            //         .storeStringTail(EthereumManager.walletAddress)
            //         .endCell();
            //     console.log("成功创建TON Cell:", cell.toString());
            // } catch (cellError) {
            //     console.error("创建TON Cell失败:", cellError);
            // }
            
            // 使用TextEncoder直接编码字符串
            let base64Payload;
            try {
                const textEncoder = new TextEncoder();
                const encoded = textEncoder.encode(str);
                base64Payload = btoa(String.fromCharCode.apply(null, [...encoded]));
            } catch (encodeError) {
                console.error("编码payload失败:", encodeError);
                base64Payload = btoa(str);
            }
            
            // 转换金额为最小单位
            const amountNano = amount * Math.pow(10, decimals);
            
            // 创建支付请求
            const paymentRequest = {
                address: rechargeAddress,
                amount: amountNano.toString(),
                // payload: base64Payload
            };
            
            // 构建交易请求
            const transactionRequest = {
                validUntil: time,
                messages: [paymentRequest]
            };
            
            this.startRecharge = true;
            Laya.timer.once(60000, this, this.clearRecharge);
            
            console.log("准备发送TON交易:", transactionRequest);
            
            // 获取最新的tonConnectUI实例
            const currentTonConnectUI = EthereumManager.tonConnectUI;            
            // 发送交易
            const response = await currentTonConnectUI.sendTransaction(transactionRequest);
            
            if (response && response.boc) {
                console.log("TON交易已发送，BOC:", response.boc);
                Laya.timer.clear(this, this.clearRecharge);
                GlobalDataManager.rechargeEnd = true;
                LoadingManager.hideLoading();
                return response.boc;
            } else {
                LoadingManager.hideLoading();
                Quick.TransactionErrorTip();
                return undefined;
            }
        } catch (err) {
            LoadingManager.hideLoading();
            console.error("TON充值错误:", err);
            
            if (err instanceof Error) {
                // 提供更友好的错误信息
                const errorMessage = err.message;
                console.error("错误详情:", errorMessage);
                
                if (errorMessage.includes("Transaction was not sent")) {
                    NoticeMgr.notice(GameLanguageMgr.getLanguage(54)); // 可能是余额不足
                } else {
                    NoticeMgr.notice(GameLanguageMgr.getLanguage(45)); // 通用错误
                }
            }
            
            return undefined;
        }
    }
    
    /**
     * TON钱包充值
     * @param params TON充值参数
     * @returns 交易哈希或undefined（失败时）
     */
    async rechargeTON2(params: TonRechargeParams) {
        const client = new TonClient({
			endpoint: "https://toncenter.com/api/v2/jsonRPC", // 主网 RPC
		});

		// USDT 合约地址
		const masterContract = Address.parse("EQCxE6mUtQJKFnGfaROTKOt1lZbDiiX1kCixRv7Nw2Id_sDs");
		// 自己钱包地址
		const myAddress = Address.parse("UQAoXndQbx6o8K_KSANgHzi8KGT041-imirppk6I01yB8H4W");

		// 查询子钱包地址
		const walletAddressRes = await client.runMethod(masterContract, 'get_wallet_address', [{ type: 'slice', cell: beginCell().storeAddress(myAddress).endCell() }]);

		// 5. 解析 Jetton 子钱包地址
		const jettonWalletAddress = walletAddressRes.stack.readAddress();

		console.log("你的 Jetton 子钱包地址是：", jettonWalletAddress.toString());


		// USDT 子钱包地址
		const usdtContractAddress = jettonWalletAddress.toString();

		// 接收方钱包地址
		const recipientAddress = "UQCtWbiu8_A8_3sz3UBGJ4gx7A7TOQhslQiUR87rsBm23BNg";

		// 转账金额 USDT（6位小数）
		const usdtAmount = 0.1 * 1e6;

		const payload = beginCell()
			.storeUint(0xf8a7ea5, 32) // Jetton transfer opcode
			.storeUint(0, 64) // query_id (optional)
			.storeCoins(usdtAmount) // amount in jetton units
			.storeAddress(Address.parse(recipientAddress)) // recipient
			.storeAddress(Address.parse(EthereumManager.walletAddress)) // response address (退款地址)
			.storeBit(0) // no custom payload
			.storeCoins(toNano("0.05")) // forward TON amount (gas)
			.storeBit(0) // no forward payload
			.endCell();
		console.log("payload===>", payload)

		const request = {
			validUntil: Math.floor(Date.now() / 1000) + 300, // 5分钟有效期
			messages: [
				{
					address: usdtContractAddress, // USDT 合约地址
					amount: toNano("0.15").toString(), // 0.1 TON（Gas 费）
					payload: payload.toBoc().toString("base64"), // 转账 payload
				},
			],
		};

		const result = await EthereumManager.tonConnectUI.sendTransaction(request);
        console.log("Transaction:", result.boc);
        return result.boc;
    }
