import SoundMgr from "../../common/SoundMgr";
import Constants from "../../global/config/Constants";
import GameSetting from "../../global/GameSetting";
import SheetDataManager from "../../global/SheetDataManager";
import MatchModel from "../../modules/match/MatchModel";
import { com } from "../../network/pb/socket";
import { Dictionary } from "../../utils/Dictionary";
import { MathUtil } from "../../utils/MathUtil";
import { Quick } from "../../utils/Quick";
import { Collision } from "../collision/Collision";
import Snake from "../snake/Snake";
import { Food } from "./Food";
import { FoodPool } from "./FoodPool";

class FoodManager {
    private static _instance: FoodManager | null = null;
    private foods: Food[] = [];
    private foodDic: Dictionary = new Dictionary();
    container: Laya.Sprite;

    private _collision: Collision;

    private foodPool: FoodPool;

    public static getInstance(): FoodManager {
        if (!FoodManager._instance) {
            FoodManager._instance = new FoodManager();
        }
        return FoodManager._instance;
    }

    constructor() {}

    init() {
        if (!this.container) this.container = new Laya.Sprite();
        this._collision = Collision.getInstance();
        this.foodPool = new FoodPool(this.container);
    }

    //=============== AI BEGIN ==================

    private spawnTimer: number = 0;
    private foodUnKey: number = 0;
    spawnFoods() {
        var items = [];
        var initCount = Constants.food.initCount;

        for (let j = 1; j <= initCount; j++) {
            var foodObject: com.snake.socket.FoodObject = this.spawnRandomFoodObject();

            items.push(foodObject);
        }
        return items;
    }
    spawnRandomFoodObject() {
        var offsetDistance = Constants.mapSize.offsetDistance;

        var bornX: number = MathUtil.randomRange(offsetDistance, Constants.mapSize.width - offsetDistance);
        var bornY: number = MathUtil.randomRange(offsetDistance, Constants.mapSize.height - offsetDistance);

        var foodObject: com.snake.socket.FoodObject = this.getFoodObjectByPos(bornX, bornY);
        return foodObject;
    }
    private spawnFood(): void {
        if (this.foods.length >= Constants.food.maxCount) return;

        var foodObject: com.snake.socket.FoodObject = this.spawnRandomFoodObject();
        this.addFood(foodObject);
    }

    public update(dt: number): void {
        // 定时生成食物
        this.spawnTimer += dt;
        if (this.spawnTimer >= Constants.food.spawnInterval) {
            this.spawnTimer = 0;
            this.spawnFood();
        }
    }

    addFoodByPosWithDie(bornX: number, bornY: number): void {
        if (this.foods.length >= Constants.food.maxCount) return;
        var foodObject: com.snake.socket.FoodObject = this.getFoodObjectByPos(bornX, bornY);

        this.addFood(foodObject);
    }
    getFoodObjectByPos(bornX: number, bornY: number) {
        this.foodUnKey += 1;
        var foodTypeLen = SheetDataManager.m_dicFoods.keys.length;
        var foodIndex: number = Math.floor(Math.random() * foodTypeLen);
        var foodId: number = SheetDataManager.m_dicFoods.keys[foodIndex];

        var foodObject: com.snake.socket.FoodObject = new com.snake.socket.FoodObject();
        foodObject.itemId = foodId;
        foodObject.unkey = this.foodUnKey + "";
        var pointObject = new com.snake.socket.PointObject();
        pointObject.x = bornX;
        pointObject.y = bornY;
        foodObject.loc = pointObject;
        return foodObject;
    }

    //=============== AI END ==================

    addFoods(foodObjects: com.snake.socket.FoodObject[], isDie = false): void {
        if (!foodObjects) return;
        foodObjects.forEach((foodObject) => this.addFood(foodObject, isDie));
    }

    addFood(foodObject: com.snake.socket.FoodObject, isDie = false): void {
        if (!foodObject) return;

        // const food = new Food(this.container, foodObject);
        const food = this.foodPool.getFood(foodObject, isDie);

        this._collision.addSnake([food]);
        this.foods.push(food);
        this.foodDic.set(foodObject.unkey, food);
    }

    getFood(foodId: string): Food {
        return this.foodDic.get(foodId);
    }

    eateFoodIds(snake: Snake, foodIds: string[], score: number, isLogicSnake: boolean) {
        if (GameSetting.Debug == 2) snake.setClientScore(score, isLogicSnake);
        var dScore = score - snake.getScore(isLogicSnake);
        if (dScore) {
            snake.showAddScore(dScore, isLogicSnake); // 增加吃豆计数
        }
        if (snake.isSelf && foodIds && foodIds.length) {
            var foodIndex = Math.floor(Math.random() * 3) + 1;
            const soundKey = `soundName_eat_food_${foodIndex}`; // 使用模板字符串生成键名
            if ((SoundMgr as any)[soundKey]) {
                SoundMgr.playSoundByName((SoundMgr as any)[soundKey]);
            } else {
                console.warn(`音效 ${soundKey} 不存在`);
            }
        }
    }

    public removeFood(food: Food): void {
        this._collision.removeSnake([food]);

        const index = this.foods.indexOf(food);
        if (index !== -1) {
            this.foods.splice(index, 1);
            // food.destroy();
        }
        if (GameSetting.Debug == 2) console.log(Quick.GetLogTime + " FOOD_TEST remove foodId: " + food.foodObject.unkey);
        this.foodDic.remove(food.foodObject.unkey);
        this.foodPool.returnFood(food);
    }

    removeAllFoods() {
        this._collision.removeSnake(this.foods);
        this.foods.forEach((food) => food.destroy());
        this.foods = [];
        this.foodDic = new Dictionary();
        this.foodPool.clear();
    }
    public getAllFoods(): Food[] {
        return this.foods;
    }

    public clear(): void {
        this.container.removeSelf();
        this.container = null;

        this.removeAllFoods(); // 完全销毁所有食物对象并清空对象池

        // 清空对象池
        this.foodPool.clear();
        // 可选：将 foodPool 设置为 null
        this.foodPool = null;

        FoodManager._instance = null;
    }

    restoreViewFood(foodId: string) {
        var food: Food = this.getFood(foodId);
        if (food) {
            food.restoreView();
        } else {
            if (GameSetting.Debug == 2) console.log(Quick.GetLogTime + " FOOD_TEST restoreViewFood foodId: " + foodId + " food is null ");
        }
    }

    restoreFoods() {
        this.removeAllFoods();

        this.createFoodsByData();
    }
    createFoodsByData() {
        let len = MatchModel.matchDto.item.length;

        for (var j = 0; j < len; j++) {
            var foodObject: com.snake.socket.FoodObject = MatchModel.matchDto.item[j];
            this.addFood(foodObject);
        }
    }
}

export default FoodManager.getInstance();
