export default class LoadingRT extends LoadingRTBase {
    public static m_iState: number = 1;
    private isLogout: boolean = false;
    private circleId: number;
    onAwake(): void {
        // ETHAssetsProxy.initData();

        // 侦听加载失败
        Laya.loader.on(Laya.Event.ERROR, this, this.onError);
        // 只加载最基础的UI资源
        Laya.loader.load(["res/loading/progress_load1.png", "res/loading/progress_load1$bar.png"]).then(() => {
            this.createUI();
            this.initBasic(); // 改为只初始化基础内容
        });
        // this.alertData()
    }

    /**
     * 当报错时打印错误
     * @param err 报错信息
     */
    onError(err: string): void {
        console.log("加载失败: " + err);
    }

    public createUI(): void {
        // ConfigBuilder;
        SoundMgr.init();
        SoundMgr.playMusicByName(SoundMgr.soundName_bg, ".mp3");
        Signal.on(GameEvent.EVENT_BACK_TO_LOGIN, this, this.backToLogin);
        Signal.on(GameEvent.EVENT_LOGIN_GAME_END, this, this.loginGameEnd);
        Signal.on(GameEvent.EVENT_ENTER_MAIN, this, this.loginCallBack);

        this.btn_ton.on(Laya.Event.CLICK, this, this.connectTonWallet); // 注意：根据引擎不同，获取方式可能不同，这里假设owner是Scene2D节点

        GameLanguageMgr.FGM_GetLanguage();
        var version = getGameVersion();
        this.txtLoad.text = version;
        console.log("VERSION: " + version);
        // 初始化 链配置信息 TODO::3加载资源信息
        let spotInfo: SpotInfo = new SpotInfo();
        spotInfo.ID = 1;
        spotInfo.Event = "加载版本信息 " + version;
        PlatFormManager.sendCustumEvent(1, null, spotInfo);
    }

    private initBasic(): void {
        // 只保留最基本的初始化
        RegistClass.init();
        LayerManager.instence.init();
        GameResourceManager.init(); // Moved from loadThirdBatch
        ComUtil.initParms();
        SceneManager.init();
        ModuleManager.intance.init();
        this.initLoad();
    }

    private initLoad(): void {
        this.onAssetLoaded();
    }

    private onAssetLoaded(): void {
        this.loadingProcess = 0.05;
        this.m_nProgress = 0.05;
        AnimationUtil.startRotationAnimation(this.img_circle, 2000, true);

        // 第一阶段：5% -> 15%
        Laya.timer.once(500, this, () => {
            this.loadFirstBatch();
        });
        let circleId = Laya.timer.loop(1000, this, this.onLoading, [this.m_nProgress]);
    }

    private loadFirstBatch(): void {
        // 第一批初始化

        this.m_nProgress = 0.15;
        this.loadingProcess = 0.15;

        // 第二阶段：15% -> 30%
        Laya.timer.once(800, this, () => {
            this.loadSecondBatch();
        });
    }

    private loadSecondBatch(): void {
        this.m_nProgress = 0.3;
        this.loadingProcess = 0.3;

        // 第三阶段：30% -> 50%
        Laya.timer.once(1000, this, () => {
            this.loadThirdBatch();
        });
    }

    private loadThirdBatch(): void {
        // 第三批初始化
        GlobalDataManager.init();

        this.m_nProgress = 0.5;
        this.loadingProcess = 0.5;

        // 最后阶段：50% -> 100%
        Laya.timer.once(1000, this, () => {
            this.loadFinalBatch();
        });
    }

    private loadFinalBatch(): void {
        // 最后的初始化

        let spotInfo: SpotInfo = new SpotInfo();
        spotInfo.ID = 3;
        spotInfo.Event = "加载资源信息";
        PlatFormManager.sendCustumEvent(3, null, spotInfo);

        // 设置到80%，预留20%给实际资源加载
        this.m_nProgress = 0.8;
        this.loadingProcess = 0.8;
    }

    private set loadingProcess(_value: number) {
        // 确保进度只增不减
        if (this.mcProcess && _value < this.mcProcess.value) {
            return;
        }

        if (_value > 1) {
            _value = 1;
        }
        if (_value < 0.05) {
            _value = 0.05;
        }

        this.mcProcess.value = _value;
        this.txtProcess.text = Math.floor(_value * 100) + "%";
        var img_guangX = _value * this.mcProcess.width - 70;
        if (img_guangX < 0) {
            img_guangX = 0;
        }
    }

    private backToLogin(): void {
        Laya.timer.clear(this, this.onLoading);
        this.m_nProgress = 0;
        Laya.loader.load(
            GameResourceManager.m_arrInitResource,
            Laya.Handler.create(this, this.getLoginData),
            Laya.Handler.create(this, this.onLoading2, null, false)
        );
    }

    private getLoginData(): void {
        //初始化 链配置信息 TODO::7进入加载页
        PlatFormManager.sendCustumEvent(7);
        // PlatFormManager.sendCustumEvent(51);
        // GlobalRoleDataManger.instance.initSkinData();
        // 初始化退出确认功能
        // GameExitManager.init();
        this.readyInitGame();
    }

    private readyInitGame(): void {
        if (this.isLogout) {
            Signal.event(GameEvent.EVENT_LOADING_SUC);
            return;
        }
        // 确保资源真正加载完成
        if (this.mcProcess) {
            // 先设置到90%
            this.loadingProcess = 0.9;

            // 延迟一小段时间，确保资源加载完成
            Laya.timer.once(500, this, () => {
                // 再设置到100%
                this.loadingProcess = 1;

                // 再延迟一小段时间，确保所有资源都加载完成
                Laya.timer.once(300, this, () => {
                    SheetDataManager.init();
                    if (GameSetting.isWhite) {
                        this.loginGame();
                    } else {
                        this.onGetNotice();
                    }
                });
            });
        }
    }

    private async onGetNotice(): Promise<void> {
        Laya.loader.maxLoader = 50;
        this.loginGame();
    }

    private async loginGame(): Promise<void> {
        Signal.event(GameEvent.EVENT_LOADED_COMPLETE);

        // console.log("8888");
        await EthereumManager.dappLogin();
        MatchModel.initMove();
    }

    private async loginGameEnd(loginDto: LoginDto): Promise<void> {
        LoadingManager.showLoading(true);
        //初始化 链配置信息 TODO::8加载配表信息
        PlatFormManager.sendCustumEvent(8);
        //初始化 链配置信息 TODO::22获取是否注册
        PlatFormManager.sendCustumEvent(22);
        if (!loginDto) {
            ModuleManager.intance.openModule(ModuleName.NoServerView);
            return;
        }
        if (loginDto.loginState == 1) {
            console.log("have no regist");
            //初始化 链配置信息 TODO::23未注册打卡创角
            PlatFormManager.sendCustumEvent(23);
            ModuleManager.intance.openModule(ModuleName.CreateLoginView);
        } else {
            //初始化 链配置信息 TODO::30已经注册，获取账户信息
            PlatFormManager.sendCustumEvent(30);
            if (loginDto.playerDto) {
                //初始化 链配置信息 TODO::31已经注册，获取账户信息成功
                PlatFormManager.sendCustumEvent(31);
                console.log("registed " + loginDto.playerDto.name);
                GlobalDataManager.playerDto = loginDto.playerDto;
                // localStorage.setItem('TOX-COOKIE' + EthereumManager.walletAddress, loginDto.playerDto.loginToken);
                this.loginCallBack();
            } else {
                //初始化 链配置信息 TODO::32已经注册，获取账户失败
                PlatFormManager.sendCustumEvent(32);
                console.log("getRegisted error");
                NoticeMgr.notice(GameLanguageMgr.getLanguage(29)); //error
            }
        }
    }
    // private onLanguageLoaded(): void {
    //     GameResourceManager.setGlobalLanguage();
    //     this.loginCallBack();
    // }
    private async loginCallBack(): Promise<void> {
        console.log("loginCallBack++++++++++++++++++++++++++++++++");
        if (GameSetting.vType == 2 && GameSetting.Debug == 0) {
            Laya.Browser.window.console.log = function () { };
        }
        GlobalDataManager.initData();
        LoadingManager.hideLoading();

        var playerDto = GlobalDataManager.playerDto;
        if (playerDto.roomId > 0) {
            let data: any = await HttpCmd.requestPost("wxgame/room/info", { roomId: playerDto.roomId });
            MatchModel.roomDto = data.roomDto;
            if (data.roomDto) {
                if (playerDto.roomState == 10) {
                    RoomWebSocket.initSocket();
                } else {
                    ModuleManager.intance.openModule(ModuleName.EnterRoomView);
                }
            } else {
                NoticeMgr.notice(GameLanguageMgr.getLanguage(29)); //error
            }
        } else {
            Quick.logs("进入主界面", 5);
            PlatFormManager.sendCustumEvent(33);
            AnimationUtil.stopCircleAnimation(this.img_circle);
            SceneManager.setCurrentScene(SceneType.M_SCENE_MAIN);
        }
    }

    private m_nProgress: number = 0;
    private onLoading(progress: number): void {
        // 确保进度值不会小于当前显示的进度
        let currentProgress = this.mcProcess ? this.mcProcess.value : 0;

        // 根据不同阶段使用不同的增长速度
        let increment = 0.01;
        if (this.m_nProgress < 0.15) {
            // 第一阶段
            increment = 0.02;
        } else if (this.m_nProgress < 0.3) {
            // 第二阶段
            increment = 0.015;
        } else if (this.m_nProgress < 0.5) {
            // 第三阶段
            increment = 0.01;
        } else if (this.m_nProgress < 0.8) {
            // 第四阶段
            increment = 0.005;
        } else {
            // 最后阶段
            increment = 0.001; // 最后阶段更慢
        }

        this.m_nProgress += increment;
        // 确保新的进度值不小于当前进度
        if (this.m_nProgress < currentProgress) {
            this.m_nProgress = currentProgress;
        }

        // 确保进度不会超过80%，最后的20%留给实际资源加载
        if (this.m_nProgress > 0.8) {
            this.m_nProgress = 0.8;
        }

        if (this.mcProcess) {
            if (progress > this.mcProcess.value) {
                this.loadingProcess = this.m_nProgress;
            }
        }
    }

    private onLoading2(progress: number): void {
        if (this.mcProcess) {
            this.loadingProcess = 0 + progress * 1.1;
        }
    }

    public removeEvent(): void {
        Signal.off(GameEvent.EVENT_BACK_TO_LOGIN, this, this.backToLogin);
        Signal.off(GameEvent.EVENT_LOGIN_GAME_END, this, this.loginGameEnd);
        Signal.off(GameEvent.EVENT_ENTER_MAIN, this, this.loginCallBack);
    }

    /**
     * TON钱包连接和签名功能
     * @description 连接TON钱包并进行消息签名
     */
    public async connectTonWallet(): Promise<void> {
        // 先连接TON钱包
        // await EthereumManager.connectTonWallet();

        // 测试TON充值功能
        try {
            // 引入ETHAssetsProxy
            // const ETHAssetsProxy = await import("../../global/contract/service/ETHAssetsProxy").then(m => m.default);

            // 创建充值参数
            const tonRechargeParams = {
                amount: 0.01, // 充值0.1个TON
                rechargeAddress: "UQCtWbiu8_A8_3sz3UBGJ4gx7A7TOQhslQiUR87rsBm23BNg", // 指定的充值地址
                decimals: 9, // TON默认精度
                comment: "测试TON充值" // 可选充值备注
                // token:"EQBCFwW8uFUh-amdRmNY9NyeDEaeDYXd9ggJGsicpqVcHhCP"
            };

            console.log("开始测试TON充值:", tonRechargeParams);

            // 调用充值方法
            const result = await ETHAssetsProxy.rechargeTON2(tonRechargeParams);

            if (result) {
                console.log("TON充值交易成功，交易哈希:", result);
            } else {
                console.error("TON充值失败");
            }
        } catch (error) {
            console.error("TON充值测试出错:", error);
        }
    }

    private alertData(): void {
        var signature = sessionStorage.getItem('signature');
        if (signature) {
            alert(signature);
        } else {
            alert("没有签名");
        }
    }
}
