const { regClass } = Laya;
import GameResourceManager from "../../common/GameResourceManager";
import MapManager from "../../game/map/MapManager";
import { BodySkin } from "../../game/snake/BodySkin";
import { com } from "../../network/pb/socket";
import MatchModel from "../match/MatchModel";
import { MatchSnakeBodySprBase } from "./MatchSnakeBodySpr.generated";

@regClass('Aeyt/emSSaCC6Np5nR/evQ==')
export class MatchSnakeBodySpr extends MatchSnakeBodySprBase {
    static POOL_NAME = "MatchSnakeBodySpr";
    public roomPlayerDto: com.snake.socket.PlayerObject;
    owner: BodySkin;
    public set dataSource(value: any) {
        // super.dataSource = value;
        this.roomPlayerDto = value as com.snake.socket.PlayerObject;
        if (!this.roomPlayerDto) {
            return;
        }

        this.skin = GameResourceManager.getSnakeBodyIcon(this.roomPlayerDto.skin); //暂时使用随机的颜色
        // this.skin = GameResourceManager.getSnakeBodyIcon(this.roomPlayerDto.snakeId);
        if (MatchModel.matchWatcher) {
            //只有观察者才能点击英雄
            this.off(Laya.Event.CLICK, this, this.onHeroSkClick);
            this.on(Laya.Event.CLICK, this, this.onHeroSkClick);
        }
    }

    onHeroSkClick() {
        MapManager.setOtherHero(this.owner.owner.owner);
    }
    public setRotation(rotation: number): void {
        this.rotation = rotation;
    }
    setScale(radio: number) {
        // 当图片加载完成后才有 width/height 值
        const width = this.width;
        const height = this.height;
        const scaleX = (radio * 2) / width;
        const scaleY = (radio * 2) / height;
        this.scaleX = scaleX;
        this.scaleY = scaleY;
    }
    setAlpha(value: number) {
        this.alpha = value;
    }
    setGray(isGray: boolean) {
        this.gray = isGray;
    }
    public getRadio(): number {
        return (this.width * this.scaleX) / 2;
    }

    onDisable(): void {
        this.owner = null;
        this.off(Laya.Event.CLICK, this, this.onHeroSkClick);
        this.setGray(false);
        this.setAlpha(1);
        this.scale(1, 1);
        // this.setScale(1);
        //移除时，回收到对象池，方便下次复用，减少对象创建开销
        Laya.Pool.recover(MatchSnakeBodySpr.POOL_NAME, this);
    }
}
