import { com } from "../../network/pb/socket";
import FoodManager from "../food/FoodManager";
import Constants from "../../global/config/Constants";
import { AIController } from "../ai/AIController";
import { Vec2 } from "../../utils/Vec2";
import FrameAiManager from "../ai/FrameAiManager";
import Snake from "./Snake";

export default class AiSnake extends Snake {
    aiController: AIController;

    isAi: boolean = false;
    /**
     * @param pnl 父容器
     * @param pos 初始位置
     * @param dir 初始方向（可选，默认向右）
     * @param len 蛇的骨骼数量（可选）
     * @param tag 节点标签（可选）
     */
    constructor(pnl: Laya.Sprite, roomPlayerDto: com.snake.socket.PlayerObject) {
        super(pnl, roomPlayerDto);
        if (this.tag.roleId && this.tag.roleId.startsWith(Constants.snake.aiPrefix)) {
            this.aiController = new AIController(this);
            this.isAi = true;
        }
    }

    pveDie() {
        if (!this.isSelf) {
            this.toFood();
            this.die();
        } else {
            this.viewSnake.setAlive(false);
            this.isConfirmDied = true;
            this.readyDie();
        }
    }

    toFood() {
        var skins = this.getSkins(false);
        for (let i = 4; i < skins.length; i += 5) {
            const matchSnakeBodySpr = skins[i];

            // 添加随机偏移
            const randomOffsetX = (Math.random() - 0.5) * 20; // 随机偏移范围 -10 到 10
            const randomOffsetY = (Math.random() - 0.5) * 20; // 随机偏移范围 -10 到 10

            const foodX = matchSnakeBodySpr.getPosition().x + randomOffsetX;
            const foodY = matchSnakeBodySpr.getPosition().y + randomOffsetY;

            // 添加食物
            FoodManager.addFoodByPosWithDie(foodX, foodY);
        }
    }

    override goMatchEnd() {
        FrameAiManager.onPveEnd();
    }

    // 添加AI更新方法
    protected override updateOther(): void {
        if (this.aiController) {
            this.aiController.update();
            // this.drawDebugInfo();
        }
    }
    public goTargetPos(targetPos: Vec2): void {
        if (this.aiController) {
            this.aiController.goTargetPos(targetPos);
            // this.drawDebugInfo();
        }
    }

    public destroy(): void {
        super.destroy();

        // 清除AI控制器
        if (this.aiController) {
            this.aiController.destroy();
            this.aiController = null;
        }
    }
}
