import { com } from "../network/pb/socket";

class RegistClass {
    private static _instance: RegistClass;

    private comIdMap: Map<number, string> = new Map();
    public constructor() {
    }

    public static getInstance(): RegistClass {
        if (RegistClass._instance) {
            return RegistClass._instance;
        }
        RegistClass._instance = new RegistClass();
        return RegistClass._instance;
    }

    public init(): void {
        this.comIdMap.set(com.snake.socket.MessageType.MSG_PLAYER_OPR, "CS_");
        this.comIdMap.set(com.snake.socket.MessageType.MSG_AI_ENTER, "CS_");
        // this.comIds.set(com.snake.socket.MessageType.MSG_PLAYER_OPR, "CS_");
        this.comIdMap.set(com.snake.socket.MessageType.MSG_NOTICE_ENTER, "SS_");
        // this.comIds.set(com.snake.socket.MessageType.MSG_GMTEST, "GM_"); // 支持GM_
        // this.comIds.set(com.snake.socket.MessageType.MSG_GMTEST, "OTHER_ANY"); // 支持任意自定义
        // 遍历枚举的非数字属性来自动注册处理类
        for (const key in com.snake.socket.MessageType) {
            // TypeScript 数字枚举生成正反映射，过滤掉数字键
            if (isNaN(Number(key))) {
                const msgCode = com.snake.socket.MessageType[key as keyof typeof com.snake.socket.MessageType];

                // 如果消息码是106则使用"CS_"前缀，110使用"SS_"，其他使用"SC_"
                let className = "";
                var msgCodeSign = this.comIdMap.get(msgCode);
                if (msgCodeSign) {
                    if (!msgCodeSign.endsWith("_")) {
                        className = msgCodeSign;
                    } else {
                        const prefix = this.comIdMap.get(msgCode);
                        // 构造类名：去掉 "MSG_" 前缀，并添加对应的前缀
                        const classSuffix = key.substring(4);
                        className = prefix + classSuffix;
                    }
                } else {
                    const prefix = "SC_";
                    // 构造类名：去掉 "MSG_" 前缀，并添加对应的前缀
                    const classSuffix = key.substring(4);
                    className = prefix + classSuffix;
                }

                // 从 com.snake.socket 命名空间下获取对应的处理类
                const handlerClass = (com.snake.socket as any)[className];
                if (handlerClass) {
                    Laya.ClassUtils.regClass(msgCode + "", handlerClass);
                } else {
                    // console.warn(`未找到 ${className} 对应的处理类，消息码：${msgCode}`);
                }
            }
        }
    }
}
export default RegistClass.getInstance();
