    /**
     * 用户钱包获取token并登录游戏
     * @returns
     */
    async checkTokenLogin() {
        var needGetToken: boolean = true; // 默认需要获取token

        // 初始化各种获取token相关变量
        let time = new Date().getTime(); // 当前时间戳
        let remeberToken = ""; // 上次记住的token
        let remeberUrl = ""; // 上次记住的url

        // 检查是否需要获取token：当不强制获取token且本地存储中有相关数据时，尝试使用缓存的获取token数据
        let _code = localStorage.getItem(this.getTokenStrByVersion());
        if (_code) {
            // 从本地存储获取登录令牌和获取token代码
            _code = ETHUtils.decode(_code); // 解码保存的获取token代码
            let codes = _code.split("&"); // 分割各个获取token组件

            // 分解获取token组件
            time = parseFloat(codes[0]); // 时间戳
            remeberToken = codes[1]; // // 上次记住的token
            remeberUrl = codes[2]; // // 上次记住的url

            // 检查时间戳是否在24小时内有效
            const isTimeValid = TimeUtil.checkTimeValid(time);
            //有缓存记录并且为超过24小时就可以不用获取token
            if (_code && time && isTimeValid && remeberToken) {
                needGetToken = false;
            }
        }
        console.log("needGetToken: " + needGetToken);
        if (needGetToken) {
            await this.signAndLogin(); //token失效 走签名流程；
        } else {
            HallWebSocket.wsUrl = remeberUrl;
            this.token = remeberToken;
            HallWebSocket.connect();
        }
    }

    /**
     * 用户钱包签名并登录游戏
     * @param mustSign 是否强制重新签名，默认为false
     * @returns
     */
    async signAndLogin() {
        //这里做一个判断，如果当前环境是telegram，则不使用电报的方式进行签名
        const isTelegram = this.isTelegramWebApp();
        var loginRequest;
        if (isTelegram) {
            this.source = "telegram";
            loginRequest = await this.connectTonWallet();
            return;
        } else {
            this.source = "normal";
            loginRequest = await this.connectNormalWallet();
        }

        if (loginRequest) {
            // if (GameSetting.vType != 0) {
            //SSO 登录认证
            var str = getServer() + `/auth/login`; //https://sso.queengame.io/auth/login
            // var str = `http://192.168.90.68:8080/auth/login`;

            let checkResult: any = await HttpCmd.requestPost(str, loginRequest, false, false).catch((err: any) => {
                // LoadingManager.hideLoading();
                console.log("checkResult 失败");
            });
            console.log("checkResult: ", checkResult);

            if (checkResult) {
                var data = checkResult.data;
                //"token":"f6c00c6dbc2e4300ada67400ad416540","nodeUrl":"wss://wss-hall-1.queengame.io"
                HallWebSocket.wsUrl = data.nodeUrl;
                this.token = data.token;
                var time = new Date().getTime();
                var _code = ETHUtils.encode(time + "&" + data.token + "&" + data.nodeUrl);
                localStorage.setItem(this.getTokenStrByVersion(), _code);
                HallWebSocket.connect();
            }
            // } else {
            //     HallWebSocket.connect();
            // }
        } else {
            Quick.errorTipAndReload(62); //籤名失敗,重新籤名
        }
    }

    private async connectNormalWallet(mustSign = false) {
        var needSign: boolean = true; // 默认需要签名

        // 初始化各种签名相关变量
        let time = new Date().getTime(); // 当前时间戳
        let randomHex = ""; // 随机哈希值
        let r = ""; // 签名组件r
        let s = ""; // 签名组件s
        let v = ""; // 签名组件v
        // 调试模式下不需要签名
        if (GameSetting.vType == 0 && GameSetting.Debug > 0) {
            needSign = false;
        } else {
            // // 检查是否需要签名：当不强制签名且本地存储中有相关数据时，尝试使用缓存的签名数据
            // let _code = localStorage.getItem("TOX-COOKIE-CODE" + EthereumManager._instance.walletAddress);
            // if (!mustSign && _code) {
            //     // 从本地存储获取登录令牌和签名代码
            //     _code = ETHUtils.decode(_code); // 解码保存的签名代码
            //     let codes = _code.split("&"); // 分割各个签名组件
            //     // 分解签名组件
            //     time = parseFloat(codes[0]); // 时间戳
            //     randomHex = codes[1]; // 随机哈希
            //     r = codes[2]; // 签名r值
            //     s = codes[3]; // 签名s值
            //     v = codes[4]; // 签名v值
            //     // 检查时间戳是否在24小时内有效
            //     const isTimeValid = TimeUtil.checkTimeValid(time);
            //     //有缓存记录并且为超过24小时就可以不用签名
            //     if (_code && time && isTimeValid && randomHex && r && s && v) {
            //         needSign = false;
            //     }
            //     console.log("needSign: " + needSign);
            // }
        }

        // 如果需要签名，执行签名流程
        if (needSign) {
            console.log("111");
            // 生成私钥和随机哈希作为签名的一部分
            const privateKey = generatePrivateKey(); // 生成随机私钥
            var addr = privateKey.substring(0, 32); // 获取私钥的前32位

            // 将地址转换为十六进制格式，作为随机数
            randomHex = toHex(addr, { size: 32 });

            // 获取当前时间戳并构造登录信息字符串
            time = new Date().getTime();
            let loginInfoStr = this.walletAddress + randomHex + time; // 拼接钱包地址、随机哈希和时间戳

            // 使用SHA-256对登录信息进行哈希处理
            const shaObj = new jsSHA("SHA-256", "TEXT", { encoding: "UTF8" });
            shaObj.update(loginInfoStr);
            const hash = shaObj.getHash("HEX"); // 获取十六进制格式的哈希值

            // 使用钱包客户端对哈希进行签名
            console.log("进入签名", 1);
            if (this.walletClient) {
                // 请求用户使用钱包签名消息
                try {
                    const signature = await this.walletClient.signMessage({
                        account: this.walletAddress!,
                        message: hash
                    });
                    console.log("签名结束", 1);
                    let signature1 = signature.substring(2); // 移除0x前缀
                    r = "0x" + signature1.substring(0, 64); // r值：签名的前64个字符
                    s = "0x" + signature1.substring(64, 128); // s值：签名的中间64个字符
                    v = "0x" + signature1.substring(128, 130); // v值：签名的最后2个字符
                } catch (err) {
                    NoticeMgr.notice(GameLanguageMgr.getLanguage(62)); //error
                    // Laya.timer.once(1000, this, this.signAndLogin, [mustSign]);
                    return;
                }
            }
        }
        var _code = ETHUtils.encode(time + "&" + randomHex + "&" + r + "&" + s + "&" + v);
        // localStorage.setItem("TOX-COOKIE-CODE" + EthereumManager._instance.walletAddress, _code);

        let loginRequest = {
            type: 1,
            loginEvmData: {
                address: this.walletAddress,
                time: time,

                randomHex: randomHex,
                r: r,
                s: s,
                v: v
            }
        };

        return loginRequest;
    }

