    /**
     * 查询TON钱包余额
     * @description 通过TON API查询指定地址的TON代币余额
     * @param address TON钱包地址
     * @returns 返回TON余额，单位为TON（如果查询失败则返回0）
     */
    public async fetchTonBalance(address: string): Promise<number> {
        if (!address) {
            console.error("查询余额失败: 地址为空");
            return 0;
        }

        try {
            const response = await fetch(`https://tonapi.io/v2/accounts/${address}`);
            const data = await response.json();
            console.log("TON余额查询响应 ===>", response);
            console.log("TON余额数据 ===>", data);

            // 将余额从nanoTON转换为TON（1 TON = 10^9 nanoTON）
            const balanceInTon = Number(data.balance) / 1e9;
            console.log("TON余额 ===>", balanceInTon);

            return balanceInTon;
        } catch (error) {
            console.error("查询TON余额失败:", error);
            return 0;
        }
    }

    /**
     * 查询TON链上的代币余额
     * @description 通过TON API查询指定地址的代币余额
     * @param address 钱包地址
     * @param tokenAddress 代币合约地址
     * @returns 返回代币余额，如果查询失败则返回0
     */
    public async fetchTonTokenBalance(address: string, tokenAddress: string): Promise<number> {
        if (!address || !tokenAddress) {
            console.error("查询代币余额失败: 地址或代币合约地址为空");
            return 0;
        }

        try {
            // 使用TON API查询代币余额
            const response = await fetch(`https://tonapi.io/v2/accounts/${address}/jettons`);
            const data = await response.json();
            console.log("TON代币数据 ===>", data);

            // 在返回的代币列表中查找指定代币
            if (data && data.jettons) {
                const token = data.jettons.find((jetton: any) => jetton.address.toLowerCase() === tokenAddress.toLowerCase());

                if (token) {
                    // 根据代币精度计算实际余额
                    const decimals = token.metadata?.decimals || 9;
                    const balanceInToken = Number(token.balance) / Math.pow(10, decimals);
                    console.log(`${token.metadata?.symbol || "代币"} 余额 ===>${balanceInToken}`);
                    return balanceInToken;
                } else {
                    console.log(`未找到合约地址为 ${tokenAddress} 的代币`);
                }
            }

            return 0;
        } catch (error) {
            console.error("查询TON代币余额失败:", error);
            return 0;
        }
    }

    /**
     * 检查是否在Telegram WebApp中
     * @returns
     */
    public isTelegramWebApp(): boolean {
        return true;
        try {
            // 判断是否在电报内置浏览器中（即 navigator.userAgent 包含 'Telegram' 字样）
            // console.log(`navigator.userAgent：${navigator.userAgent},Telegram:${(window as any).Telegram}`);
            const urlParams = new URLSearchParams(window.location.search);
            // const isTelegram = urlParams.has('tgWebAppPlatform') || urlParams.has('tgWebAppData');
            // alert(`isTelegram：${isTelegram}`);
            if (typeof navigator !== "undefined" && navigator.userAgent && navigator.userAgent.indexOf("Telegram") !== -1) {
                return true;
            }
            if (typeof (window as any)["ethereum"] === "undefined") {
                return true;
                // console.log(GameLanguageMgr.getLanguage(26));
                // if (GameSetting.Debug == 0) {
                //     Quick.downloadTip(26);
                //     // NoticeMgr.notice(GameLanguageMgr.getLanguage(26));
                //     // ModuleManager.intance.openModule(ModuleName.HelpDialog, [
                //     //     0,
                //     //     GameLanguageMgr.getUILang("System Tip"),
                //     //     GameLanguageMgr.getLanguage(26)
                //     // ]);
                //     return;
                //     // Quick.errorTipAndReload(26);
                // }
            }
            // 检查Telegram WebApp对象是否存在
            if (typeof window === "undefined" || !(window as any).Telegram || !(window as any).Telegram.WebApp) {
                return false;
            }

            // 检查Telegram WebApp特有的属性和方法
            const webApp = (window as any).Telegram.WebApp;

            // 验证initData属性
            if (!webApp.initData || typeof webApp.initData !== "string") {
                return false;
            }

            // 验证initDataUnsafe对象
            if (!webApp.initDataUnsafe || typeof webApp.initDataUnsafe !== "object") {
                return false;
            }

            // 验证常见的WebApp方法
            if (typeof webApp.close !== "function" || typeof webApp.expand !== "function" || typeof webApp.ready !== "function") {
                return false;
            }

            return true;
        } catch (e) {
            console.error("检测Telegram环境时出错:", e);
            return false;
        }
    }
