import { BaseItem } from "../BaseItem";
export class SnakeItem extends BaseItem {
    public id: number; //id	
    public name: string; //名字
    public category: number; //category|类型
    public icon: string; //icon| 图标
    public initLength: number; //initLength|初始长度
    public intervalBoneToDrawSkin: number; //intervalBoneToDrawSkin|每个皮肤之间的间隔骨骼数目
    public baseSpeed: number; //baseSpeed|基础速度
    public maxLength: number; //maxLength|最大长度
    public suctionRadius: number; //suctionRadius|吸食半径
    public collisionHeadRadius: number; //collisionHeadRadius|头部碰撞半径
    public collisionBodyRadius: number; //collisionBodyRadius|身体碰撞半径
    public headRadius: number; //headRadius|头部半径
    public bodyRadius: number; //bodyRadius|身体半径   			
    public doublePointsProbability: number; //doublePointsProbability|双倍积分概率(%)
    public price: number; //price|价格(U)
    public accelerationFactor: number; //accelerationFactor|加速系数
}
