const { regClass } = Laya;
import { SceneType } from "../../common/baseScene/SceneType";
import { LayerManager } from "../../common/LayerManager";
import SceneManager from "../../common/SceneManager";
import { SnakeItem } from "../../data/sheetItem/snake/SnakeItem";
import { GameEvent } from "../../global/event/GameEvent";
import Signal from "../../global/event/Signal";
import KnapsackManager from "../../global/KnapsackManager";
import SheetDataManager from "../../global/SheetDataManager";
import { com } from "../../network/pb/socket";
import HallWebSocket from "../../network/HallWebSocket";
import { AnimationUtil } from "../../utils/AnimationUtil";
import { KnapsackSceneBase } from "./KnapsackScene.generated";
import { SocketDataUtil } from "../../utils/SocketDataUtil";

@regClass('fGHujQp/QpOG4OhbMXNszQ==')
export class KnapsackScene extends KnapsackSceneBase {
    public m_iLayerType: number;
    public m_iPositionType: number;
    onAwake(): void {
        this.m_iLayerType = LayerManager.M_POP;
        this.m_iPositionType = LayerManager.UP;
    }
    private currTab: number = 0;
    private type: number = 1;
    private selectItemId: number = -1;
    private shopId: number = 1; //选中的蛇的id

    onOpened(datas: any): void {
        //根据参数切换优先显示的类目
        if (datas && datas.length > 0) {
            this.type = datas[0];
            if (datas[1] != undefined) {
                this.selectItemId = datas[1];
            }
            this.onClickTab(this.type);
        } else {
            //没有指定就显示默认第一个
            this.selectItemId = 1;
            this.onClickTab(this.selectItemId);
        }
        this.initBagInfo();
    }

    onEnable(): void {
        this.snakeList.visible = false;
        this.propList.visible = false;
        //注册事件左侧按钮点击（切换类型）
        for (let i = 1; i < 3; i++) {
            (this as any)["btn_" + i].on(Laya.Event.CLICK, this, this.onClickTab, [i]);
        }
        AnimationUtil.startJellyScaleAnimation(this.tf_tittle);
        Signal.on("msg_" + com.snake.socket.MessageType.MSG_SHOP_BUY, this, this.onBuySuccess);
        this.btn_back.on(Laya.Event.CLICK, this, this.setToMainScene);
        Signal.on(GameEvent.EVENT_ITEM_UPDATE, this, this.onPackInfo);
        Signal.on(GameEvent.EVENT_SNAKE_UPDATE, this, this.onSnakePackInfo);
        Signal.on(GameEvent.UPDATE_BAG_INFO, this, this.initBagInfo);
    }

    /**
     * 设置Tab的选中状态
     * @param value
     */
    public setTab(value: number) {
        for (let i = 1; i < 3; i++) {
            if (value == i) {
                (this as any)["btn_" + i].getChildByName("selectBox1").visible = true;
                (this as any)["btn_" + i].getChildByName("selectBox2").visible = false;
            } else {
                (this as any)["btn_" + i].getChildByName("selectBox1").visible = false;
                (this as any)["btn_" + i].getChildByName("selectBox2").visible = true;
            }
        }
    }

    /**
     * 左侧切换商品类型的点击事件
     * @param _index
     * @returns
     */
    async onClickTab(_index: number) {
        if (this.currTab == _index) return;
        this.type = _index;
        this.setTab(_index);
        if (_index == 1) {
            //nft
            this.box_nft.visible = true;
            this.box_prop.visible = false;
            this.tf_nft.stroke = 5;
            this.tf_nft.fontSize = 32;
            this.tf_props.stroke = 0;
            this.tf_props.fontSize = 25;
            // this.img_nft.skin = "res/shop/img_iconwz1.png";
            // this.img_props.skin = "res/shop/img_iconwz4.png";
        } else if (_index == 2) {
            //道具
            this.box_prop.visible = true;
            this.box_nft.visible = false;
            this.tf_nft.stroke = 0;
            this.tf_nft.fontSize = 25;
            this.tf_props.stroke = 5;
            this.tf_props.fontSize = 32;
            // this.img_nft.skin = "res/shop/img_iconwz2.png";
            // this.img_props.skin = "res/shop/img_iconwz3.png";
        }
    }

    private setToMainScene(): void {
        SceneManager.setCurrentScene(SceneType.M_SCENE_MAIN);
    }

    public removeEvent(): void {
        for (let i = 0; i < 4; i++) {
            (this as any)["tab" + i].off(Laya.Event.CLICK, this, this.onClickTab, [i]);
        }

        for (let i = 1; i < 3; i++) {
            (this as any)["btn_" + i].off(Laya.Event.CLICK, this, this.onClickTab, [i]);
        }

        this.btn_back.off(Laya.Event.CLICK, this, this.setToMainScene);
    }

    /**
     * Tab点击事件处理
     * @param index 被点击的Tab索引
     */
    private onTabClick(index: number) {
        // Tab相关常量定义
        const TAB_COUNT = 3;
        const SKIN_SELECTED_FIRST = "res/shop/img_Button_1.png";
        const SKIN_SELECTED_OTHER = "res/shop/img_btlv.png";
        const SKIN_UNSELECTED_FIRST = "res/shop/img_bt1_2.png";
        const SKIN_UNSELECTED_OTHER = "res/shop/img_Button_4.png";
        const STROKE_COLOR = "#009815";
        const STROKE_WIDTH = 5;

        // 遍历所有Tab按钮
        for (let i = 1; i < TAB_COUNT; i++) {
            // 获取当前Tab按钮和其标题文本组件
            const tab = (this as any)[`btn${i}`];
            const title = tab.getChildByName("tf_tit");

            // 判断当前Tab是否被选中，是否是第一个Tab
            const isSelected = index === i;
            const isFirstTab = i === 0;
            this.selectItemId = index;
            // 根据Tab位置和选中状态设置不同的皮肤
            tab.skin = isFirstTab
                ? isSelected
                    ? SKIN_SELECTED_FIRST
                    : SKIN_UNSELECTED_FIRST
                : isSelected
                ? SKIN_SELECTED_OTHER
                : SKIN_UNSELECTED_OTHER;

            // 设置文字描边效果：选中时显示描边，未选中时隐藏描边
            title.stroke = isSelected ? STROKE_WIDTH : 0;
            title.strokeColor = STROKE_COLOR;
        }
    }

    private onBuySuccess(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        var msgBody: com.snake.socket.SC_SHOP_BUY = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SC_SHOP_BUY);
        if (msgcode == com.snake.socket.MessageCode.SYS_NORMAL) {
            // 购买成功回调
            if (msgBody && msgBody.items) {
                // 更新商城数据
                // 显示购买成功提示
                Laya.Scene.open("dialog/TipsDialog", false, {
                    content: "购买成功!",
                    autoClose: true
                });
            }
        } else {
            // 购买失败提示
            Laya.Scene.open("dialog/TipsDialog", false, {
                content: "购买失败，请稍后重试",
                autoClose: true
            });
        }
    }

    /**
     * 请求资产信息
     */
    private onRecruit(token: number = 1): void {
        const cmdId = com.snake.socket.MessageType.MSG_SHOP_BUY;
        var snakeItem: SnakeItem = SheetDataManager.m_dicSnakes.get(this.shopId);
        console.log(snakeItem);
        if (this.shopId) {
            const requestData = com.snake.socket.CS_SHOP_BUY.fromObject({
                id: this.shopId
            });
            HallWebSocket.send(cmdId, requestData);
        }
    }

    private initBagInfo() {
        // 发送获取背包信息请求
        const cmdId = com.snake.socket.MessageType.MSG_PACK_INFO;
        HallWebSocket.send(cmdId);
    }

    /**
     * 背包信息返回处理
     */
    private onPackInfo(): void {
        // 过滤掉id为10001的道具和数量为0的道具
        var allItems = KnapsackManager.getAllKnapsackItems();
        const filteredItems = allItems.filter((item) => item.id !== 10001 && item.num > 0);

        this.propList.array = filteredItems;
        this.propList.visible = true;
        
    }
    /**
     * 背包信息返回处理
     */
    private onSnakePackInfo(): void {

        const snakeData = KnapsackManager.getAllSnakeItems();
        console.log("蛇信息返回处理", snakeData);
        // 添加一个特殊的数据项到蛇列表末尾，用于显示跳转商城的组件
        const specialItem = {
            id: -999, // 使用一个特殊ID标识这是跳转商城的项
            isShopEntry: true // 添加标识，表示这是商城入口
        };
        // 将特殊数据添加到蛇列表末尾
        this.snakeList.array = [...snakeData, specialItem];
        this.snakeList.visible = true;
    }
    // /**
    //  * 购买道具
    //  */
    // async onRecruit() {
    // }

    onDisable(): void {
        for (let i = 1; i < 3; i++) {
            (this as any)["btn_" + i].off(Laya.Event.CLICK, this, this.onClickTab);
        }
        Signal.off("msg_" + com.snake.socket.MessageType.MSG_SHOP_BUY, this, this.onBuySuccess);
        this.btn_back.off(Laya.Event.CLICK, this, this.setToMainScene);
        Signal.off(GameEvent.EVENT_ITEM_UPDATE, this, this.onPackInfo);
        Signal.off(GameEvent.EVENT_SNAKE_UPDATE, this, this.onSnakePackInfo);
        Signal.off(GameEvent.UPDATE_BAG_INFO, this, this.initBagInfo);
    }
}
