import ErrorPopManager from "../common/ErrorPopManager";
import GameLanguageMgr from "../common/GameLanguageMgr";
import LoadingManager from "../common/LoadingManager";
import { ModuleManager } from "../common/ModuleManager";
import PlatFormManager from "../common/PlatFormManager";
import EthereumManager from "../global/contract/EthereumManager";
import { GameEvent } from "../global/event/GameEvent";
import Signal from "../global/event/Signal";
import { SocketEvent } from "../global/event/SocketEvent";
import GameSetting from "../global/GameSetting";
import GlobalDataManager from "../global/GlobalDataManager";
import { ModuleName } from "../global/ModuleName";
import { Quick } from "../utils/Quick";
import { SocketDataUtil } from "../utils/SocketDataUtil";
import HallWebSocket from "./HallWebSocket";

import { com } from "./pb/socket";
import RoomWebSocket from "./RoomWebSocket";
import MarqueeManager from "../modules/notice/MarqueeManager";
import KnapsackManager from "../global/KnapsackManager";
import { ItemDto } from "../data/dto/ItemDto";
import { SnakeDto } from "../data/dto/SnakeDto";
import FrameSyncManager from "../game/match/FrameSyncManager";

export class HallMessageHandle {
    /** 尝试重发次数 */
    connectTime: number = 0;

    /** 断网可尝试发送消息最大为5次,超过3次直接返回到主界面 */
    connectTimeMax: number = 5;

    preTime: number = 1000;

    isOtherLogin: boolean = false;

    /** 心跳发送间隔 5000 */
    private _heartBeatInterval: number = 5000;
    constructor() {
        this.init();
    }

    private init(): void {
        Signal.on(SocketEvent.EVENT_GLOBAL_ERROR_CODE, this, this.onShowGlobalErrorCode);
        Signal.on(SocketEvent.EVENT_HALL_SOCKET_OPEN, this, this.onSocketOpen);
        Signal.on(SocketEvent.EVENT_HALL_SOCKET_ERROR, this, this.onScoketError);
        Signal.on(SocketEvent.EVENT_HALL_SOCKET_CLOSE, this, this.onSocketClose);
        Signal.on(SocketEvent.EVENT_HALL_STOP_HEART, this, this.stopHeartbearTimer);
        Signal.on(SocketEvent.EVENT_HALL_SHOW_TIP_DELAY, this, this.onShowTipDelay);

        Signal.on("msg_" + com.snake.socket.MessageType.MSG_USER_LOGIN, this, this.onUserLogin);
        Signal.on("msg_" + com.snake.socket.MessageType.MSG_REPEAT_LOGIN_NOTICE, this, this.onOtherUserLogin);
        Signal.on("msg_" + com.snake.socket.MessageType.MSG_LVUP_NOTICE, this, this.onLvUpNotice);
        Signal.on("msg_" + com.snake.socket.MessageType.MSG_UPDATE_ROLE, this, this.onUpdateRole);
        Signal.on("msg_" + com.snake.socket.MessageType.MSG_SYS_NOTICE, this, this.onSysNotice);
        Signal.on("msg_" + com.snake.socket.MessageType.MSG_PACK_INFO, this, this.onPackInfo);
        // Signal.on("msg_" + com.snake.socket.MessageType.MSG_NEW_MAIL, this, this.onMailNotice);
    }

    onSocketOpen() {
        console.log("socket connect success");
        // 启动心跳检测
        this.startHeartBeat();
        Laya.timer.clear(this, this.onReconnect);
        // this.connectTime = 0;

        // 如果已经获取到钱包地址，发送登录请求
        if (EthereumManager.walletAddress) {
            console.log(Quick.GetLogTime, "[HallMessageHandle] Sending login request after connecting to hall server");
            this.onLogin();
        }
    }

    onScoketError() {
        this.startReconnect();
    }
    onSocketClose() {
        this.startReconnect();
    }
    private startReconnect() {
        if (this.isOtherLogin) return;

        console.log("websocket----closed connectTime:" + this.connectTime + ", connectTimeMax: " + this.connectTimeMax);
        if (this.connectTime <= this.connectTimeMax) {
            var timeOutTime = this.connectTime * this.preTime;
            Laya.timer.once(timeOutTime, this, this.onReconnect);
        } else {
            LoadingManager.hideLoading();
            this.showTip();
        }
    }

    private onReconnect() {
        this.reconnect();
        this.connectTime++;
    }

    /* 重连 */
    reconnect() {
        console.log(Quick.GetLogTime, "[HallWebSocket]  reconnect 开始重连服务器");
        if (HallWebSocket.connected) {
            return;
        }

        let tipTxt = String(this.connectTime) + "/" + String(this.connectTimeMax) + " " + GameLanguageMgr.getLanguage("正在尝试重连"); // 正在尝试重连
        LoadingManager.showLoadingByInfo(tipTxt);

        HallWebSocket.connectWebSocket();

        console.log(Quick.GetLogTime, "[HallWebSocket]  reconnect -------->", tipTxt);
    }

    stopReconnect() {
        Laya.timer.clear(this, this.onReconnect);
        LoadingManager.hideLoading();
    }

    private onShowTipDelay() {
        Laya.timer.once(10000, this, this.showTip);
    }

    public clearShowTip() {
        Laya.timer.clear(this, this.showTip);
    }
    showTip() {
        Quick.netErrorAndReload();
    }

    private onLogin(): void {
        var cmdId = com.snake.socket.MessageType.MSG_USER_LOGIN;
        // let loginRequestInfo = EthereumManager.getloginRequestInfo; //获取签名信息
        var o = com.snake.socket.CS_USER_LOGIN.fromObject({
            walletAddr: EthereumManager.walletAddress,
            token: EthereumManager.token
        });
        console.log("登录请求信息", o);
        HallWebSocket.send(cmdId, o);
    }

    private isFirst: boolean = true;
    public onUserLogin(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        var msgBody: com.snake.socket.SC_USER_LOGIN = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SC_USER_LOGIN);
        console.log("登录返回信息", msgBody);
        if (msgcode == com.snake.socket.MessageCode.USER_NOT_EXIST) {
            LoadingManager.hideLoading();
            console.log("have no regist");
            //初始化 链配置信息 TODO::23未注册打卡创角
            PlatFormManager.sendCustumEvent(23);
            ModuleManager.intance.openModule(ModuleName.CreateLoginView);
        } else if (msgcode == com.snake.socket.MessageCode.WALLET_ADDRESS_ERROR) {
            console.log("token no exist");
            EthereumManager.clearToken();//清空token
            this.stopReconnect();
            Quick.errorTipAndReload(10005);
        } else if (msgcode == com.snake.socket.MessageCode.SYS_NORMAL) {
            LoadingManager.hideLoading();
            console.log("have regist");

            // 更新玩家信息
            GlobalDataManager.updatePlayerInfo(msgBody.roleInfo);

            //防止是重连登录； 只有首次登录成功后，才打开主界面
            if (this.isFirst) {
                Signal.event(GameEvent.EVENT_ENTER_MAIN);
                this.isFirst = false;
            }
        }
        this.connectTime = 0;
        this.clearShowTip();
        this.heartbeatTimer();
    }
    public onOtherUserLogin(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        this.isOtherLogin = true;
        HallWebSocket.clearAll();
        HallWebSocket.close();
        RoomWebSocket.isOtherLogin = true;
        RoomWebSocket.clearAll();
        RoomWebSocket.close();
        Quick.otherLogin(); //提示别的地方登录
        console.log("WS----------------------------otherLogin");
    }

    private onShowGlobalErrorCode(msgcode: number) {
        if (msgcode != com.snake.socket.MessageCode.SYS_NORMAL) {
            console.log(Quick.GetLogTime, "[HallMessageHandle]  msgcode--------------->", msgcode);

            // let errorMsg = GameLanguageMgr.getError(msgcode);

            // if (GameSetting.vType != 2) {
            if (
                msgcode !== com.snake.socket.MessageCode.NOT_ENOUGH_TOKEN &&
                msgcode !== com.snake.socket.MessageCode.CREATE_ROOM_MAX &&
                msgcode !== com.snake.socket.MessageCode.USER_NOT_EXIST
            ) {
                let tip = GameLanguageMgr.getError(msgcode);
                Quick.commTipWithYes(tip);
                // Quick.commTipWithYes(errorMsg + " code:" + msgcode);
            }
            // } else {
            //     Quick.commTipWithYes(errorMsg);
            // }
        }
    }
    // handle(messageBase: com.snake.socket.CMsgBase) {
    //     var msgtype = messageBase.msghead.msgtype;
    //     var msgcode = messageBase.msghead.msgcode;
    //     if (msgtype == com.snake.socket.MessageType.MSG_HEART_BEAT) {
    //         return;
    //     }

    //     var msgBody = SocketDataUtil.getMsgBody(messageBase);
    //     this.onShowGlobalErrorCode(msgcode);
    // }

    /** 停止发送心跳消息 */
    stopHeartbearTimer() {
        Laya.timer.clear(this, this.sendHeartBeat);
    }

    heartbeatTimer() {
        this.stopHeartbearTimer();
        Laya.timer.loop(this._heartBeatInterval, this, this.sendHeartBeat);
    }

    // 启动心跳检测
    private startHeartBeat() {
        // 发送第一次心跳
        this.sendHeartBeat();
        // 定时发送心跳
        Laya.timer.loop(30000, this, this.sendHeartBeat);
    }

    // 发送心跳包
    private sendHeartBeat() {
        HallWebSocket.send(com.snake.socket.MessageType.MSG_HEART_BEAT, null, false);
    }

    private onLvUpNotice(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        var msgBody: com.snake.socket.SC_LVUP_NOTICE = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SC_LVUP_NOTICE);
        let msgLvUpBody = msgBody as com.snake.socket.SC_LVUP_NOTICE;
        // 玩家不在房间内，正常弹出升级页面
        if (!FrameSyncManager.frameNetQueue.isStart) {
            ModuleManager.intance.openModule(ModuleName.PlayerUpgradeSuccessDialog, msgLvUpBody);
        }
        console.log("收到升级通知:", msgLvUpBody);
    }

    private onUpdateRole(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        var msgBody: com.snake.socket.SS_UPDATE_ROLE = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SS_UPDATE_ROLE);
        let msgUpdateRoleBody = msgBody as com.snake.socket.SS_UPDATE_ROLE;
        console.log("收到更新角色信息:", msgUpdateRoleBody);

        if (!msgBody.roleInfo || msgBody.roleInfo.length === 0) {
            console.log("收到的角色信息为空");
            return;
        }

        // 使用GlobalDataManager中的updatePlayerInfo方法更新玩家信息
        GlobalDataManager.updatePlayerInfo(msgBody.roleInfo[0]);
    }

    private onMailNotice(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        var msgBody: com.snake.socket.SC_MAIL_LIST = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SC_MAIL_LIST);
        // console.log("收到新邮件通知:", msgBody,msgcode);
    }

    /**
     * 处理系统公告消息
     * @param msgBase 消息基类
     * @param msgcode 消息码
     */
    private onSysNotice(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        // 从消息中提取公告内容
        var msgBody: com.snake.socket.SC_SYS_NOTICE = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SC_SYS_NOTICE);

        if (msgcode === com.snake.socket.MessageCode.SYS_NORMAL && msgBody && msgBody.msg) {
            console.log("收到系统公告:", msgBody.msg);
            msgBody.msg = `${msgBody.msg}`;

            // 将公告直接添加到MarqueeManager
            // MarqueeManager会根据是否在主界面决定是否立即显示
            // 并且会记录播放次数，每条公告播放两次后自动移除
            if (msgBody.msg && msgBody.msg.trim() !== "") {
                MarqueeManager.addNotice(msgBody.msg);
            }

            // 同时触发新公告事件，以便其他需要处理公告的组件可以接收
            Signal.event(GameEvent.EVENT_NEW_NOTICE, msgBody.msg);
        }
    }

    /**
     * 背包信息返回处理
     */
    private onPackInfo(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        var msgBody: com.snake.socket.SC_PACK_INFO = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SC_PACK_INFO);
        if (msgcode === com.snake.socket.MessageCode.SYS_NORMAL) {
            // 更新背包数据
            KnapsackManager.initKnapsackData(msgBody.items as ItemDto[]);

            // 更新背包数据
            KnapsackManager.initSnakeData(msgBody.snake as SnakeDto[]);
        }
    }
}
