export class Vec2 {
    public x: number;
    public y: number;

    constructor(x: number = 0, y: number = 0) {
        this.x = x;
        this.y = y;
    }

    static create(x: number = 0, y: number = 0): Vec2 {
        return new Vec2(x, y);
    }

    /**
     * 将当前向量的值赋值为另一个向量的值
     */
    assign(vec2: Vec2): this {
        this.x = vec2.x;
        this.y = vec2.y;
        return this;
    }

    /**
     * 返回一个新向量，表示当前向量与 vec2 的和
     */
    add(vec2: Vec2): Vec2 {
        return new Vec2(this.x + vec2.x, this.y + vec2.y);
    }

    /**
     * 返回一个新向量，表示当前向量与 vec2 的差
     */
    sub(vec2: Vec2): Vec2 {
        return new Vec2(this.x - vec2.x, this.y - vec2.y);
    }

    /**
     * 返回一个新向量，表示当前向量乘以一个数值
     */
    mul(num: number): Vec2 {
        return new Vec2(this.x * num, this.y * num);
    }

    /**
     * 返回当前向量相对于正 x 轴的绝对角度（单位：度），归一化到 [0, 360)
     */
    getRotation(): number {
        // 以当前向量本身为方向（视为从原点(0,0)出发）
        let angle = (Math.atan2(this.y, this.x) * 180) / Math.PI;
        if (angle < 0) {
            angle += 360;
        }
        return angle;
    }

    /**
     * 计算从当前向量指向目标向量的角度（单位：度），归一化到 [0, 360)
     * 这里计算的是目标向量减去当前向量的差值
     */
    getRotationTo(target: Vec2): number {
        const dx = target.x - this.x;
        const dy = target.y - this.y;
        let angle = (Math.atan2(dy, -dx) * 180) / Math.PI;
        if (angle < 0) {
            angle += 360;
        }
        return angle;
    }

    /**
     * 将当前向量归一化（单位向量）
     */
    normalize(): Vec2 {
        const n = Math.sqrt(this.x * this.x + this.y * this.y);
        if (n !== 0) {
            this.x /= n;
            this.y /= n;
        }
        return this;
    }

    /**
     * 逆时针旋转向量指定角度（单位：度）
     */
    rotateCCW(rotation: number): Vec2 {
        const rad = (rotation * Math.PI) / 180;
        const sin = Math.sin(rad);
        const cos = Math.cos(rad);
        const x = this.x;
        const y = this.y;
        this.x = x * cos - y * sin;
        this.y = x * sin + y * cos;
        return this;
    }

    /**
     * 计算当前向量与 vec 的点积
     */
    dot(vec: Vec2): number {
        return this.x * vec.x + this.y * vec.y;
    }

    multiplyScalar(scale: number) {
        this.x *= scale;
        this.y *= scale;
    }

    /**
     * 判断当前向量与 vec 是否相等
     */
    equal(vec: Vec2): boolean {
        return this.x === vec.x && this.y === vec.y;
    }

    length(): number {
        return Math.sqrt(this.x * this.x + this.y * this.y);
    }

    /**
     * 初始化方法（供对象池调用）
     */
    init(x: number = 0, y: number = 0): this {
        this.x = x;
        this.y = y;
        return this;
    }

    /**
     * 克隆当前向量
     */
    clone(): Vec2 {
        return new Vec2(this.x, this.y);
    }

    /**
     * 限制向量长度范围
     */
    clamp(min: number, max: number): this {
        const len = this.length();
        if (len > max) this.normalize().mul(max);
        if (len < min) this.normalize().mul(min);
        return this;
    }

    /**
     * 重置为(0,0)
     */
    reset(): this {
        this.x = 0;
        this.y = 0;
        return this;
    }
    /**
     * 保留1位小数
     */
    toOneDecimal(): this {
        this.x = this.NumtoOneDecimal(this.x);
        this.y = this.NumtoOneDecimal(this.y);
        return this;
    }

    private NumtoOneDecimal(num: number): number {
        // return Math.floor(num * 10) / 10;
        return Math.round(num * 10) / 10;
    }

    toString(): string {
        return `(${this.x},${this.y})`;
    }
}
