const { regClass } = Laya;
import { LayerManager } from "../../common/LayerManager";
import SceneManager from "../../common/SceneManager";
import { SceneType } from "../../common/baseScene/SceneType";
import { AnimationUtil } from "../../utils/AnimationUtil";
import { RankSceneBase } from "./RankScene.generated";
import { com } from "../../network/pb/socket";
import HallWebSocket from "../../network/HallWebSocket";
import Signal from "../../global/event/Signal";
import { SocketDataUtil } from "../../utils/SocketDataUtil";

@regClass('kxqXjP8sR7OnW67fK0960g==')
export class RankScene extends RankSceneBase {
    public m_iLayerType: number;
    public m_iPositionType: number;
    private currentTabIndex: number = 0;
    private allRankData: Map<number, any[]> = new Map();

    onAwake(): void {
        this.m_iLayerType = LayerManager.M_POP;
        this.m_iPositionType = LayerManager.UP;
    }

    onEnable(): void {
        this.RankList.visible = false;
        //注册事件顶部按钮点击
        for (let i = 0; i < 3; i++) {
            (this as any)["tab" + i].on(Laya.Event.CLICK, this, this.onTabClick, [i]);
        }
        this.btn_back.on(Laya.Event.CLICK, this, this.setToMainScene);
        AnimationUtil.startJellyScaleAnimation(this.tf_tittle);

        // // 注册协议回调
        Signal.on("msg_" + com.snake.socket.MessageType.MSG_REQUEST_RANK, this, this.onRankListReceived);

        // // 默认加载第一个Tab的数据
        this.onTabClick(0);
    }

    /**
     * 设置Tab的选中状态
     * @param value
     */
    public setTab(value: number) {
        for (let i = 1; i < 3; i++) {
            if (value == i) {
                (this as any)["btn_" + i].getChildByName("selectBox1").visible = true;
                (this as any)["btn_" + i].getChildByName("selectBox2").visible = false;
            } else {
                (this as any)["btn_" + i].getChildByName("selectBox1").visible = false;
                (this as any)["btn_" + i].getChildByName("selectBox2").visible = true;
            }
        }
    }

    private setToMainScene(): void {
        SceneManager.setCurrentScene(SceneType.M_SCENE_MAIN);
    }

    public removeEvent(): void {
        for (let i = 0; i < 3; i++) {
            (this as any)["tab" + i].off(Laya.Event.CLICK, this, this.onTabClick, [i]);
        }

        this.btn_back.off(Laya.Event.CLICK, this, this.setToMainScene);

        // 移除协议监听
        Signal.off("msg_" + com.snake.socket.MessageType.MSG_REQUEST_RANK, this, this.onRankListReceived);
    }

    /**
     * Tab点击事件处理
     * @param index 被点击的Tab索引
     */
    private onTabClick(index: number) {
        this.currentTabIndex = index;

        // Tab相关常量定义
        const TAB_COUNT = 3;
        const SKIN_SELECTED = "res/common/comm/img_tab1.png";
        const SKIN_UNSELECTED = "res/common/comm/img_tab2.png";
        const STROKE_COLOR_SELECTED = "#427030";
        const STROKE_COLOR_UNSELECTED = "#1449cb";
        // 遍历所有Tab按钮
        for (let i = 0; i < TAB_COUNT; i++) {
            // 获取当前Tab按钮和其标题文本组件
            const tab = (this as any)[`tab${i}`];
            const title = tab.getChildByName("tf_tit");

            // 判断当前Tab是否被选中，是否是第一个Tab
            const isSelected = index === i;
            // this.selectItemId = index;
            // 根据Tab位置和选中状态设置不同的皮肤
            tab.skin = isSelected ? SKIN_SELECTED : SKIN_UNSELECTED;
            if(isSelected) this.noDataBox.visible = false;

            // 设置文字描边效果：选中时显示描边，未选中时隐藏描边
            title.strokeColor = isSelected ? STROKE_COLOR_SELECTED : STROKE_COLOR_UNSELECTED;

            switch (index) {
                case 0:
                    // 单场击杀排行
                    this.box_daily.visible = true;
                    this.box_dailybest.visible = false;
                    this.box_over.visible = false;
                    break;
                case 1:
                    //单场积分排行2
                    this.box_daily.visible = false;
                    this.box_dailybest.visible = true;
                    this.box_over.visible = false;
                    break;
                case 2:
                    //累计击杀排行
                    this.box_daily.visible = false;
                    this.box_dailybest.visible = false;
                    this.box_over.visible = true;
                    break;
            }
            if(isSelected){
                // 根据tab索引确定数据类型
                const dataType = index + 1; // 协议要求类型从1开始
                
                // 检查是否有缓存的排行榜数据
                if (this.allRankData.has(dataType)) {
                    // 有缓存数据，直接使用
                    const cachedData = this.allRankData.get(dataType);
                    this.displayRankData(index, cachedData);
                } else {
                    // 没有缓存数据，请求新数据
                    this.requestRankData(dataType);
                }
            }
        }
    }

    /**
     * 请求排行榜数据
     * @param type 1.单场积分排行 2.单场击杀排行 3.累计击杀排行
     */
    private requestRankData(type: number): void {
        // 清空当前显示的排行数据
        // 发送请求排行榜协议
        const cmdId = com.snake.socket.MessageType.MSG_REQUEST_RANK;
        const requestData = com.snake.socket.CS_RANK_LIST.fromObject({
            type: type
        });

        HallWebSocket.send(cmdId, requestData);
    }

    /**
     * 接收排行榜数据回调
     */
    private onRankListReceived(msgBase: com.snake.socket.CMsgBase): void {
        // 隐藏加载中效果
        // this.showLoading(false);

        // 解析数据
        const rankListData = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SC_RANK_LIST);
        console.log(rankListData);
        if (!rankListData || !rankListData.rank || rankListData.rank.length === 0) {
            this.showEmptyRankTip();
            this.noDataBox.visible = true;  
            return;
        }else{
            this.RankList.visible = true;
            this.noDataBox.visible = false;
        }

        // 缓存排行榜数据
        this.allRankData.set(this.currentTabIndex+1, rankListData.rank);
        
        // 根据当前选中的Tab显示不同排行榜数据
        this.displayRankData(this.currentTabIndex, rankListData.rank);
    }

    /**
     * 显示排行榜数据
     * @param tabIndex 当前选中的Tab索引
     * @param rankData 排行榜数据
     */
    private displayRankData(tabIndex: number, rankData: any[]): void {        
        this.RankList.array = rankData;
        this.RankList.visible = true;
        this.RankList.refresh();
        
        // 滚动到列表的第一行
        this.RankList.scrollTo(0);
    }

    /**
     * 清空排行榜数据
     */
    private clearRankList(): void {
        const listViews = [
            this.box_daily.getChildByName("list_rank") as Laya.List,
            this.box_dailybest.getChildByName("list_rank") as Laya.List,
            this.box_over.getChildByName("list_rank") as Laya.List
        ];

        // 清空所有列表数据
        listViews.forEach(list => {
            if (list) {
                list.array = [];
                list.refresh();
            }
        });
    }

    /**
     * 显示空数据提示
     */
    private showEmptyRankTip(): void {
        this.RankList.visible = false;
        this.noDataBox.visible = true;
        // 这里可以添加无数据时的提示UI显示逻辑
    }

    onDisable(): void {
        this.removeEvent();
    }
}