export class RoomDto {
    public password: string;
    public arenaId: number;
    /**
     * PVP房 选择index
     */
    public pvpRoomIndex: number;
    /**
     * PVP房 货币选择index
     */
    public pvpTokenIndex: number;
    public coinType: number;
    public roomNo: string;
    public members: any[];

    public isWatch: boolean;

    public requirePass: boolean;

    /**
     * socket链接地址
     */
    public connectAddr: string;
    // public socketPort:number;
    public joinCd: number; //加入cd倒计时,毫秒

    /**
     * 1=可以进战场，0=不能
     */
    public enterGame: number;

    /**
     * 节点ID
     */
    public nodeId: number;

    /**
     * 房间名字
     */
    public roomName: string;
    /**
     * 定制名字
     */
    public customName: string;

    /**
     * 0=等待加入，  2=参加叠加赛阶段（达到最大人数，或者还剩1分钟时）， 3=分组完成阶段（还剩10秒时），10=战斗开始
     */
    public state: number;
    /**
     * 已报名玩家数据
     */
    public groupApplyList: Array<number> = [];
    /**
     * 分组数据
     */
    public groupData: Array<Array<any>> = [];


    /**
     * 房间人数配置下标
     */
    public numIndex: number;

    public minCount: number;
    public maxCount: number;
    //========== 以下仅查看房间列表时使用 =============

    public memberCount: number;
    /**
     * 已成型的队伍数量
     */
    public completeTeamNum: number;

    public leader: any;

    public startTimeDiff: number;

    //=====================  预约房 =========================
    /**
     * 0=否， 1=是预约房
     */
    public preContract: number;

    /**
     * 预约开始时间
     */
    public startTime: number;

    /**
     * 当前时间，后续可能用于距离预约房开始的 cd倒计时,毫秒
     */
    public curTime: number;

    /**
     * 0=否， 1=是匿名
     */
    public anonymous: number;
    /**
     * 0=不关闭直播， 1=关闭直播
     */
    public closeLive: number;

    /**
     * 是否必定预约赛
     */
    public isBookingMust: boolean;

    //=====================  预约房 团战 =========================
    /**
     * 所属组别id
     */
    public groupId: number;

    /**
     * 组信息
     */
    public teamDto: any;

    /**
     * 房间分组
     * key=小队id就是小队长的pid 就是teamId
     */
    public roomGroupMap: Map<string, any>; //房间分组;
}
