const { regClass } = Laya;
import { formatUnits } from "viem";
import { AlertType } from "../../common/AlertType";
import { DepositDto, RechargeParams } from "../../data/dto/DepositDto";
import { TokenData } from "../../data/dto/TokenData";
import Signal from "../../global/event/Signal";
import { com } from "../../network/pb/socket";
import HallWebSocket from "../../network/HallWebSocket";
import { DepositDialogBase } from "./DepositDialog.generated";
import { ComUtil } from "../../utils/ComUtil";
import AlertManager from "../../common/AlertManager";
import LoadingManager from "../../common/LoadingManager";
import GlobalDataManager from "../../global/GlobalDataManager";
import EthereumManager from "../../global/contract/EthereumManager";
import ETHAssetsProxy from "../../global/contract/service/ETHAssetsProxy";
import { SocketDataUtil } from "../../utils/SocketDataUtil";
import GameLanguageMgr from "../../common/GameLanguageMgr";
import NoticeMgr from "../notice/NoticeMgr";

@regClass('O0v8EHpMT0+wWgB8t3D14A==')
export class DepositDialog extends DepositDialogBase {
    private rechargeData: DepositDto;
    private data: TokenData;
    private btnLock: boolean = false; //按钮防止连点锁

    public constructor() {
        super();
    }

    onEnable(): void {
        Signal.on("msg_" + com.snake.socket.MessageType.MSG_CHARGE, this, this.onRequestChargeInfo);
        this.btn_confirm.on(Laya.Event.CLICK, this, this.onbtnConfirm);
        // 添加输入框的输入事件监听，实时验证输入内容
        this.rechargeCode.on(Laya.Event.INPUT, this, this.testRechargeCodeInput);
    }

    /**
     * 显示样式
     * @param data
     */
    public setOpenData(data: TokenData) {
        this.tf_adress.text = ComUtil.shortenString(EthereumManager.walletAddress, 6, 4);
        this.data = data;
        this.tf_web.text = data.chainName;
        this.tf_token.text = data.symbol;
        console.log("data", data);
        this.requestChargeInfo();
    }

    /**
     * 请求资产信息
     */
    private requestChargeInfo(): void {
        const cmdId = com.snake.socket.MessageType.MSG_CHARGE;
        const symbolId = this.data.symbolId;
        const requestData = com.snake.socket.CS_CHARGE.fromObject({
            symbolId: symbolId
        });
        HallWebSocket.send(cmdId, requestData);
    }

    /**
     * 获取充值信息
     */
    public onRequestChargeInfo(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        var msgBody: com.snake.socket.SC_CHARGE = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SC_CHARGE);
        if (msgcode == com.snake.socket.MessageCode.SYS_NORMAL) {
            console.log("SC_CHARGE", msgBody);
            //获取到充值信息
            this.rechargeData = msgBody;
            this.setDepositData(msgBody);
        }
    }

    /**
     * 展示充值页面的信息2
     * @returns
     */
    private async setDepositData(data: any) {
        const currentChainId = await EthereumManager.walletClient.getChainId();
        const needChainId = Number(data.chainId);
        try {
            if (currentChainId !== needChainId) {
                //IOS会卡死，所有加这个提示
                //链地址不一致，需要切换
                let switchSuccess: boolean = await EthereumManager.switchChain(needChainId);
                if (!switchSuccess) {
                    let result = await EthereumManager.addChain(needChainId);
                    if (result) {
                        this.setDepositData(data);
                    }
                    // await EthereumManager.resetPublicAndWallet(chainIDData);
                    return;
                }
            } else {
                // tokenBalance = await EthereumManager.getBalance2(data.currencyId);
            }
            let tokenBalance = await EthereumManager.getBalance2(this.data.tokenAddress);
            const decimals = this.data.decimals;
            //获取到货币的精度
            const balanceAsEther = formatUnits(tokenBalance, decimals);
            this.tf_rest.text = `${ComUtil.truncateToTwoDecimalPlaces(Number(balanceAsEther))}`;
            console.log("tokenBalance", tokenBalance);
        } catch (err) {
            console.log("切换失败，请手动切换", err);
        }
    }

    /**
     * 充值点击事件
     * @returns
     */
    private async onbtnConfirm() {
        if (this.btnLock) {
            return;
        } else {
            this.btnLock = true;
            Laya.timer.once(2000, this, () => {
                this.btnLock = false;
            });
        }
        this.testRechargeCodeInput();
        const restVal = Number(this.tf_rest.text);
        const rechargeCode = Number(this.rechargeCode.text);
        const currentChainId = await EthereumManager.walletClient.getChainId();
        const needChainId = Number(this.data.chainId);
        try {
            if (currentChainId !== needChainId) {
                //IOS会卡死，所有加这个提示
                //链地址不一致，需要切换
                let switchSuccess: boolean = await EthereumManager.switchChain(needChainId);
                if (!switchSuccess) {
                    let result = await EthereumManager.addChain(needChainId);
                    if (result) {
                        this.onbtnConfirm();
                    }
                    // await EthereumManager.resetPublicAndWallet(chainIDData);
                    return;
                }
            } else {
                // tokenBalance = await EthereumManager.getBalance2(data.currencyId);
            }
        } catch (err) {
            console.log("切换失败，请手动切换", err);
        }
        //判断数量是否足够
        if (!rechargeCode) {
            //没输入充值的数量
            AlertManager.AlertByType(AlertType.BASEALERTVIEW, GameLanguageMgr.getLanguage(53), AlertType.YES);
            return;
        }

        if (restVal < rechargeCode) {
            //不够btn_withdraw
            AlertManager.AlertByType(AlertType.BASEALERTVIEW, GameLanguageMgr.getLanguage(54), AlertType.YES);
            return;
        }

        //防操作遮罩
        LoadingManager.showLoadingByInfo();
        // SheetDataManager.intance.getNetAddress(currentChainId)//获取充值网络地址
        // const currencyId = (EnumConsumeType as any)[`TYPE_${this.tf_token.text}`] || EnumConsumeType.TYPE_TOX;
        // let token = SheetDataManager.intance.getCurrency(currencyId,currentChainId)
        let abi = JSON.parse(this.rechargeData.abi);
        console.log(abi);
        const rechargeParams: RechargeParams = {
            amount: rechargeCode,
            token: this.data.tokenAddress,
            rechargeAddress: this.rechargeData.depositAddress,
            decimals: this.data.decimals,
            abi: abi
        };
        let hash = await ETHAssetsProxy.rechargeToken(rechargeParams); //获取合约钱包数据
        if (hash) {
            //关闭防操作遮罩
            this.getRestCoin(this.data.tokenAddress);
            GlobalDataManager.rechargeEnd = true;
            NoticeMgr.notice(GameLanguageMgr.getLanguage(82));
            this.close();
        }
    }

    /**
     * 验证充值码输入
     * 限制只能输入数字和小数点，且只能输入正数
     */
    private testRechargeCodeInput(): void {
        const value = this.rechargeCode.text;
        if (value) {
            // 正则表达式验证：只允许输入正数（整数或小数）
            const reg = /^[0-9]+\.?[0-9]*$/;

            // 检查是否为负数或非法字符
            if (!reg.test(value)) {
                // 过滤掉非法字符，只保留数字和小数点
                let filteredValue = "";
                for (let i = 0; i < value.length; i++) {
                    const char = value.charAt(i);
                    if ((char >= "0" && char <= "9") || (char === "." && filteredValue.indexOf(".") === -1)) {
                        filteredValue += char;
                    }
                }

                // 更新输入框内容
                this.rechargeCode.text = filteredValue;

                // 如果内容被修改，显示提示信息
                // if (filteredValue !== value) {
                //     NoticeMgr.notice(GameLanguageMgr.getLanguage(1802));
                // }
            }

            // 确保不是0开头的多位数（除非是小数）
            if (value.length > 1 && value.startsWith("0") && value.charAt(1) !== ".") {
                this.rechargeCode.text = value.substring(1);
            }
        }
    }

    /**
     * 获取剩余币数
     */
    private async getRestCoin(tokenAddress: string): Promise<void> {
        try {
            const tokenBalance = await EthereumManager.getBalance2(tokenAddress);
            if (tokenBalance) {
                const balanceAsEther = formatUnits(tokenBalance, this.data.decimals);
                this.tf_rest.text = `${ComUtil.truncateToTwoDecimalPlaces(Number(balanceAsEther))}`;
            }
            LoadingManager.hideLoading();
        } catch (error) {
            console.error("获取余额失败", error);
            LoadingManager.hideLoading();
        }
    }

    onDisable(): void {
        Signal.off("msg_" + com.snake.socket.MessageType.MSG_CHARGE, this, this.onRequestChargeInfo);
        // 移除输入框的输入事件监听
        this.rechargeCode.off(Laya.Event.INPUT, this, this.testRechargeCodeInput);
    }
}
