const { regClass } = Laya;
import { BtnColorFilter } from "../../common/filters/BtnColorFilter";

import { ItemItem } from "../../data/sheetItem/item/ItemItem";
import { GameEvent } from "../../global/event/GameEvent";
import Signal from "../../global/event/Signal";
import { MatchSkillListItemBase } from "./MatchSkillListItem.generated";

@regClass('x6t+z1VuR52yXWju0qxGBg==')
export class MatchSkillListItem extends MatchSkillListItemBase {
    public skillItem: any;
    public itemItem: ItemItem;
    private isAddEvent: boolean = false;
    private isCanClick = true;
    public keyNum: number;
    public equipPos: number;
    public count: number;

    public constructor() {
        super();
    }

    onEnable(): void {
        this.addEvent();
    }

    private addEvent() {
        if (!this.isAddEvent) {
            Signal.on(GameEvent.EVENT_CLICK_NUM, this, this.onNumberClick);
            Signal.on(GameEvent.EVENT_UPDATE_ITEM_SKILL_COOL, this, this.updateItemRemainCooldown);
            Signal.on(GameEvent.EVENT_UPDATE_GLOBAL_COOL, this, this.updateGlobalCooldown);
            Signal.on(GameEvent.EVENT_UPDATE_REDECE_COOL, this, this.updateReduceCooldown);
            // this.on(Laya.Event.CLICK, this, this.onSkillButtonClick);
            this.isAddEvent = true;

            this.on(Laya.Event.CLICK, this, this.onSkillButtonClick);
            this.on(Laya.Event.MOUSE_UP, this, this.onSkillButtonUp);
        }
    }

    onNumberClick(num: number) {
        if (num == this.keyNum) {
            // if(!this.isBig)
            this.onSkillButtonClick(null);
        }
    }

    public set dataSource(value: any) {
        super.dataSource = value;
        this.skillItem = value[0];
        this.itemItem = value[1] as ItemItem;
        this.equipPos = value[2];
        this.count = value[3];
        if (!this.skillItem) {
            return;
        }
        this.addEvent();
        this.setCurrentOutPut();
    }

    async setCurrentOutPut() {
        if (!this.skillItem) return;
        this.skillIconItem.isBig = this.skillItem.icon == "1001";
        this.skillIconItem.dataSource = this.skillItem;

        // this.skillIconItem.txt_num.text = '' + this.skillItem.name;//TODO TEST
        // this.skillIconItem.txt_num.visible = true;//TODO TEST

        if (this.itemItem) {
            this.txt_num.visible = true;
            this.updateCount();
            this.skillCooldown = this.itemItem.cd * 1000; // 技能冷却时间（毫秒）
        } else {
            this.txt_num.visible = false;
            this.skillCooldown = this.skillItem.cd; // 技能冷却时间（毫秒）
        }
        this.thisGlobalCooldown = this.skillItem.commCd; // 全局冷却时间（毫秒）

        // 设置帧循环
        Laya.timer.frameLoop(1, this, this.updateCooldown);
    }

    private skillCooldown: number = 5000; // 技能冷却时间（毫秒）
    private thisGlobalCooldown: number = 10000; // 当前技能的全局冷却时间（毫秒）
    private globalCooldown: number = 10000; // 全局冷却时间（毫秒）
    private remainingSkillCooldown: number = 0; // 剩余技能冷却时间
    private remainingGlobalCooldown: number = 0; // 剩余全局冷却时间

    private reduceCooldown: number = 0; //要减去的时间

    // 技能按钮点击事件
    private onSkillButtonUp(e: Laya.Event): void {
        if (e) {
            e.stopPropagation();
        }
        BtnColorFilter.clearClickFilter(this);
    }

    // 技能按钮点击事件
    private onSkillButtonClick(e: Laya.Event): void {
        if (e) {
            e.stopPropagation();
        }
        return;
    }
    public updateSkillCooldown(_skillCooldown: number) {
        this.remainingSkillCooldown = _skillCooldown;
    }
    /**
     * 更新道具冷却
     * @param _skillId
     */
    public updateItemRemainCooldown(updateData: any[]) {
        var _skillId: number = updateData[0];

        console.log("updateItemRemainCooldown _skillId: " + _skillId);
        if (this.itemItem && _skillId == this.skillItem.id) {
            this.count = updateData[1];
            this.updateCount();
            this.updateSkillCooldown(this.skillCooldown);
        }
    }

    updateCount() {
        this.txt_num.text = this.count + "";
        this.disabled = !this.count;
    }
    /**
     * 更新道具冷却
     * @param _skillId
     */
    public updateReduceCooldown(skillType: number, reduceRate: number) {
        console.log("updateReduceCooldown skillType: " + skillType);
        if (this.skillItem && skillType == this.skillItem.type) {
            this.reduceCooldown = this.skillCooldown * reduceRate;
        }
    }
    public updateGlobalCooldown(_globalCooldown: number) {
        if (this.itemItem) {
            //普通道具没有全局冷却
            return;
        }
        this.globalCooldown = _globalCooldown;
        this.remainingGlobalCooldown = _globalCooldown;
    }

    // 更新冷却状态
    private updateCooldown(): void {
        if (this.remainingSkillCooldown + this.reduceCooldown > 0) {
            // 技能冷却还在进行中，更新剩余冷却时间
            this.remainingSkillCooldown -= Laya.timer.delta; // 将帧间隔转换为毫秒

            let num: number = (this.remainingSkillCooldown + this.reduceCooldown) / 1000;
            this.txt_time.text = num.toFixed(1);

            // 更新技能冷却遮罩层
            this.updateCooldownMask(this.skillCooldownMask, (this.remainingSkillCooldown + this.reduceCooldown) / this.skillCooldown, "#000000");
            // this.skillCooldownMask.visible = true;
            this.img_djs.visible = true;
            this.txt_time.visible = true;
        } else {
            // this.skillCooldownMask.visible = false;
            this.img_djs.visible = false;
            this.txt_time.visible = false;
        }

        if (this.remainingGlobalCooldown + this.reduceCooldown > 0) {
            // 全局冷却还在进行中，更新剩余全局冷却时间
            this.remainingGlobalCooldown -= Laya.timer.delta; // 将帧间隔转换为毫秒

            // 更新全局冷却遮罩层
            this.updateCooldownMask(this.globalCooldownMask, (this.remainingGlobalCooldown + this.reduceCooldown) / this.globalCooldown, "#00000036");
            this.globalCooldownMask.visible = true;
        } else {
            this.globalCooldownMask.visible = false;
        }

        // 根据冷却状态更新按钮的可点击状态
        this.skillIconItem.gray = this.remainingSkillCooldown + this.reduceCooldown > 0 || this.remainingGlobalCooldown + this.reduceCooldown > 0;
    }

    // 更新遮罩层，模拟冷却效果
    private updateCooldownMask(mask: Laya.Sprite, progress: number, color: string): void {
        // 计算圆形遮罩的半径
        const maskRadius = this.width / 2;

        // 计算遮罩层的中心点位置
        const centerX = this.width / 2;
        const centerY = this.height / 2;

        // 清空遮罩层
        mask.graphics.clear();

        // 绘制圆形作为遮罩
        mask.graphics.drawPie(centerX, centerY, maskRadius, -90 + 360 * (1 - progress), 270, color);
        // mask.graphics.drawPie(centerX, centerY, maskRadius, -90 + 360 * (1 -progress), 270, "#0000007a");
    }

    onDisable(): void {
        Signal.off(GameEvent.EVENT_UPDATE_ITEM_SKILL_COOL, this, this.updateItemRemainCooldown);
        Signal.off(GameEvent.EVENT_UPDATE_GLOBAL_COOL, this, this.updateGlobalCooldown);
        Signal.off(GameEvent.EVENT_UPDATE_REDECE_COOL, this, this.updateReduceCooldown);
        Signal.offAllCaller(this);
        Laya.timer.clearAll(this);
    }
}
