const { regClass } = Laya;
import { LayerManager } from "../../common/LayerManager";
import { JoinRoomDialogBase } from "./JoinRoomDialog.generated";
import EnterRoomManager from "./EnterRoomManager";
import SheetDataManager from "../../global/SheetDataManager";
import { RoomItem } from "../../data/sheetItem/RoomItem";
import HallWebSocket from "../../network/HallWebSocket";
import { com } from "../../network/pb/socket";
import Signal from "../../global/event/Signal";
import { SocketDataUtil } from "../../utils/SocketDataUtil";
import GameResourceManager from "../../common/GameResourceManager";
import AssetManager from "../../manager/AssetManager";
import GameSetting from "../../global/GameSetting";

// Tab 相关常量定义
const TAB_COUNT = 3;
const TAB_SKINS = {
    selected: ["res/main/join/img_tbl1.png", "res/main/join/img_tbm1.png", "res/main/join/img_tbr1.png"],
    unselected: ["res/main/join/img_tbl2.png", "res/main/join/img_tbm2.png", "res/main/join/img_tbr2.png"]
};
const STROKE_COLORS = {
    selected: "#0c6917",
    unselected: "#405073"
};
const ROOM_TYPES = [2, 3, 4]; // 对应每个 tab 的房间类型

@regClass('NM3GHDnJRD6AnD7XkkQaig==')
export class JoinRoomDialog extends JoinRoomDialogBase {
    public m_iLayerType: number = LayerManager.M_POP;
    public m_iPositionType: number = LayerManager.CENTER;
    private roomType: number;
    private roomData: RoomItem;
    private tabIndex: number = 0;
    private tokenIndex: number = 0;
    private isEntering: boolean = false; // 添加进入对战状态标记

    public constructor() {
        super();
    }
    /**
     * 显示购买页信息
     * @param data 参数
     */
    public setOpenData(data: any): void {
        this.tabIndex = data[0];
        this.tokenIndex = data[1];

        this.initEvents();
        this.backLayer.alpha = 0;
        this.backLayer.visible = true;
        Laya.Tween.to(this.backLayer, { alpha: 0.7 }, 200, Laya.Ease.linearIn);
        if (!AssetManager.getTokenData()) {
            this.requestCoinInfo();
        } else {
            this.onTabClick(this.tabIndex);
        }
    }

    onDisable(): void {
        this.removeEvents();

        // 清除可能存在的定时器
        Laya.timer.clear(this, () => {
            this.isEntering = false;
        });
    }

    /**
     * 初始化事件监听
     */
    private initEvents(): void {
        // 注册顶部按钮点击事件
        for (let i = 0; i < TAB_COUNT; i++) {
            (this as any)[`tab${i}`].on(Laya.Event.CLICK, this, this.onTabClick, [i]);
        }

        // 注册其他事件
        Signal.on(`msg_${com.snake.socket.MessageType.MSG_QUERY_TOKEN}`, this, this.onRequestInfo);
        this.img_di1.on(Laya.Event.CLICK, this, this.onCheakTab);
        this.btn_hideBox.on(Laya.Event.CLICK, this, this.onCloseTab);
        this.btn_font.on(Laya.Event.CLICK, this, this.onEnterMatch);
        if (GameSetting.Debug == 2) {
            this.btn_watch.visible = true;
            this.btn_watch.on(Laya.Event.CLICK, this, this.onWatchMatch);
        }

        // this.backLayer.on(Laya.Event.CLICK, this, this.closeDialog);

        // 列表渲染和选择处理
        this.list_token.renderHandler = Laya.Handler.create(this, this.onTokenItemRender, null, false);
        this.list_token.selectHandler = new Laya.Handler(this, this.handleSelectToken);
    }

    /**
     * 移除事件监听
     */
    private removeEvents(): void {
        // 移除消息监听
        Signal.off(`msg_${com.snake.socket.MessageType.MSG_QUERY_TOKEN}`, this, this.onRequestInfo);

        // 移除UI事件
        this.img_di1.off(Laya.Event.CLICK, this, this.onCheakTab);
        this.btn_hideBox.off(Laya.Event.CLICK, this, this.onCloseTab);
        this.btn_font.off(Laya.Event.CLICK, this, this.onEnterMatch);
        // this.backLayer.off(Laya.Event.CLICK, this, this.closeDialog);

        // 移除Tab点击事件
        for (let i = 0; i < TAB_COUNT; i++) {
            (this as any)[`tab${i}`].off(Laya.Event.CLICK, this, this.onTabClick);
        }

        // 移除列表事件
        this.list_token.renderHandler = null;
        this.list_token.selectHandler = null;
    }

    /**
     * 对战按钮点击事件
     */
    private onEnterMatch(): void {
        if (this.isEntering) {
            return;
        }

        if (this.roomData) {
            // 设置状态为true，防止连点
            this.isEntering = true;

            EnterRoomManager.goPvpArenaScene(
                this.roomData.id,
                this.roomData.ticketType[this.tokenIndex],
                this.roomData.ticketAmount[this.tokenIndex],
                this.tabIndex,
                this.tokenIndex
            );

            // 3秒后恢复状态
            Laya.timer.once(3000, this, () => {
                this.isEntering = false;
            });
        }
    }
    /**
     * 观战按钮点击事件
     */
    private onWatchMatch(): void {
        if (this.isEntering) {
            return;
        }

        if (this.roomData) {
            // 设置状态为true，防止连点
            this.isEntering = true;
            let roomNo = "1_00_2_1001";
            if (GameSetting.roomNoTest) {
                roomNo = GameSetting.roomNoTest;
            }

            EnterRoomManager.watchPvpArenaScene(this.roomData.id, roomNo);

            // 3秒后恢复状态
            Laya.timer.once(3000, this, () => {
                this.isEntering = false;
            });
        }
    }

    /**
     * 显示代币选择面板
     */
    private onCheakTab(): void {
        if (AssetManager.getTokenData()) {
            this.img_token_pad.visible = true;
            this.btn_hideBox.visible = true;
        }
    }

    /**
     * 关闭代币选择面板
     */
    private onCloseTab(): void {
        if (this.img_token_pad.visible) {
            this.btn_hideBox.visible = false;
            this.img_token_pad.visible = false;
        }
    }

    /**
     * Tab点击事件处理
     * @param index 被点击的Tab索引
     */
    private onTabClick(index: number): void {
        this.tabIndex = index;
        if (!AssetManager.getTokenData()) return;

        // 更新所有Tab的状态
        this.updateTabsAppearance(index);

        // 设置当前房间类型
        this.roomType = ROOM_TYPES[index];

        // 更新房间数据
        this.updateRoomData();
    }

    /**
     * 更新所有Tab的外观
     * @param selectedIndex 当前选中的Tab索引
     */
    private updateTabsAppearance(selectedIndex: number): void {
        for (let i = 0; i < TAB_COUNT; i++) {
            const tab = (this as any)[`tab${i}`];
            const title = tab.getChildByName("tf_tit");
            const isSelected = selectedIndex === i;

            // 设置Tab外观
            tab.skin = isSelected ? TAB_SKINS.selected[i] : TAB_SKINS.unselected[i];
            title.strokeColor = isSelected ? STROKE_COLORS.selected : STROKE_COLORS.unselected;
        }
    }

    /**
     * 更新房间数据列表
     */
    private updateRoomData(): void {
        // 获取当前房间类型的所有房间
        const dic = SheetDataManager.m_dicRoom?.values;
        const roomItems = dic.filter((item) => item.roomType == this.roomType);

        if (roomItems.length === 0) return;

        // 根据ticketType去重
        this.roomData = roomItems[0];

        // 更新UI
        this.list_token.array = this.roomData.ticketType;
        this.list_token.selectedIndex = 0;

        // 更新显示的代币信息
        this.updateTokenInfo(this.tokenIndex);
    }

    /**
     * 更新代币信息显示
     * @param roomItem 房间项
     */
    private updateTokenInfo(index: number): void {
        this.tokenIndex = index;
        const tokenData = AssetManager.getTokenData().find((item) => item.symbolId == this.roomData.ticketType[index]);
        if (tokenData) {
            this.tf_coin.text = tokenData.symbol;
            this.img_coin.skin = GameResourceManager.getCurrencyIcon(this.roomData.ticketType[index]);
            this.tf_number.text = String(this.roomData.ticketAmount[index]);
        }
    }

    /**
     * 列表项渲染处理
     */
    private onTokenItemRender(cell: any, index: number): void {
        if (cell && cell.onChange) {
            cell.onChange(this.list_token.selectedIndex == index);
            this.img_token_pad.visible = false;
            this.btn_hideBox.visible = false;
        }
    }

    /**
     * 代币选择处理
     */
    private handleSelectToken(index: number): void {
        if (index != -1) {
            this.updateTokenInfo(index);
        }
    }

    /**
     * 请求资产信息
     */
    public requestCoinInfo(): void {
        const cmdId = com.snake.socket.MessageType.MSG_QUERY_TOKEN;
        HallWebSocket.send(cmdId);
    }

    /**
     * 获取资产信息回调
     */
    private onRequestInfo(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        const msgBody: com.snake.socket.SC_QUERY_TOKEN = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SC_QUERY_TOKEN);

        if (msgcode == com.snake.socket.MessageCode.SYS_NORMAL) {
            // 解析成可用的object格式
            // const parsedTokens = ComUtil.parseTokenData(msgBody.token);
            // 保存数据
            // AssetManager.getTokenData() = parsedTokens;
            this.onTabClick(this.tabIndex);
        }
    }

    /**
     * 关闭对话框
     */
    // private closeDialog(): void {
    //     this.close();
    // }
}
