import GameLanguageMgr from "../common/GameLanguageMgr";
import GlobalDataManager from "../global/GlobalDataManager";
/**
 * 数字工具类，提供各种数字格式化和转换方法
 */
export class NumberUtil {
    /**
     * 将数字保留指定小数位数
     * @param number 需要处理的数字
     * @param decimalPointCount 保留的小数位数
     * @returns 处理后的数字
     */
    public static toFixed(number: number, decimalPointCount: number): number {
        if (number.toString().indexOf(".") == -1) {
            return number;
        } else {
            let str: string = number.toFixed(decimalPointCount);
            return parseFloat(str);
        }
    }

    /**
     * 将数字转换为百分比格式
     * @param number 需要转换的数字
     * @param decimalPointCount 保留的小数位数
     * @param addStr 前缀字符串，默认为"+"
     * @returns 百分比格式的字符串，如"+50%"
     */
    public static toFixedWithPercent(number: number, decimalPointCount: number, addStr: string = "+"): string {
        let str: string;
        if (number.toString().indexOf(".") == -1) {
            str = addStr + number * 100 + "%";
        } else {
            decimalPointCount = decimalPointCount - 2;
            if (decimalPointCount < 0) {
                decimalPointCount = 0;
            }
            str = addStr + (number * 100).toFixed(decimalPointCount) + "%";
        }
        return str;
    }

    /**
     * 将金币数值格式化为带单位的字符串
     * @param num 金币数值
     * @returns 格式化后的字符串，超过999999显示为m单位
     */
    public static getGoldStr(num: any): string {
        let str: string;
        if (num > 999999) {
            str = parseInt(String(num / 100000)) + "m";
        } else {
            str = num;
        }
        return str;
    }

    /**
     * 将数字转换为千分位格式
     * @param num 需要格式化的数字字符串
     * @returns 添加千分位分隔符的字符串
     */
    public static numStringFormat(num: string): string {
        let str: string = num;
        if (GlobalDataManager.m_strLanguage == 2) {
            if (num.length > 4) {
                str = String(num).replace(/(\d)(?=(\d{3})+$)/g, "$1 ");
            }
        } else {
            str = String(num).replace(/(\d)(?=(\d{3})+$)/g, "$1,");
        }
        return str;
    }

    /**
     * 将数字简化为k单位的形式
     * @param num 需要简化的数字字符串
     * @returns 简化后的字符串，如1000转换为1k
     */
    public static numSimple(num: string): string {
        let str: string = num;
        let knum: number = parseInt(parseInt(str) / 1000 + "");
        if (knum > 0) {
            return knum + "k";
        }
        return NumberUtil.numStringFormat(str);
    }

    /**
     * 将数字格式化为带单位(K/M)的字符串
     * @param num 需要格式化的数字
     * @returns 格式化后的字符串
     */
    public static numStringFormat2(num: number): string {
        let str: string;
        if (num > 999999) {
            str = NumberUtil.getNumStr(num, 1000000, "M");
        } else if (num > 999) {
            str = NumberUtil.getNumStr(num, 1000, "K");
        } else {
            return num + "";
        }
        return str;
    }

    /**
     * 将数字转换为带单位的字符串
     * @param numI 需要转换的数字
     * @param numM 单位基数
     * @param lauguage 单位字符串
     * @returns 格式化后的字符串
     */
    public static getNumStr(numI: number, numM: number, lauguage: string): string {
        let str: string = parseInt(Math.floor(numI / numM) + "") + lauguage;
        return str;
    }

    /**
     * 将时间数值转换为格式化的时间字符串
     * @param times 时间数值（单位：秒）
     * @returns 格式化后的时间字符串，根据时间长短显示为分钟、小时或天数
     */
    public static getTimeStr(times: number): string {
        let str: string;
        if (times < 3600) {
            str = GameLanguageMgr.getLanguage(9024, Math.ceil(times / 60));
        } else if (times < 3600 * 24) {
            str = GameLanguageMgr.getLanguage(9025, Math.ceil(times / 3600));
        } else {
            str = GameLanguageMgr.getLanguage(9025, Math.ceil(times / (3600 * 24)));
        }
        return str;
    }

    /**
     * 判断一个数字是否为整数
     * @param obj 需要判断的数字
     * @returns 如果是整数返回true，否则返回false
     */
    public static isInteger(obj: number): boolean {
        return obj % 1 === 0;
    }

    /**
     * 判断一个值是否为数字类型
     * @param value 需要判断的值
     * @returns 如果是数字类型返回true，否则返回false
     */
    public static isNumber(value: unknown): value is number {
        return typeof value === "number";
    }

    /**
     * 格式化数字，对于非整数保留指定位数的小数
     * @param num 需要格式化的数字
     * @param digits 保留的小数位数，默认为8位
     * @returns 格式化后的数字
     */
    static formatNumber(num: number, digits = 8): number {
        if (Number.isInteger(num)) {
            // 如果是整数，直接转换为字符串
            return num;
        } else {
            // 如果不是整数，保留两位小数
            return parseFloat(num.toFixed(digits));
        }
    }

    /**
     * 格式化数字为字符串，对于非整数保留指定位数的小数
     * @param num 需要格式化的数字
     * @param digits 保留的小数位数，默认为2位
     * @returns 格式化后的数字字符串
     */
    static formatNumberStr(num: number, digits = 2): any {
        if (Number.isInteger(num)) {
            // 如果是整数，直接转换为字符串
            return num;
        } else {
            // 如果不是整数，保留两位小数
            return parseFloat(num.toFixed(digits)).toString();
        }
    }

    /**
     * @param num
     * @param digits
     * @param needK
     * @param isFloor 是否向下取的小数
     * @returns
     */
    public static filterNumFormat(num: any, digits = 2, needK: boolean = false, isFloor = false): string {
        if (!num) {
            return num;
        }
        if (num < 1e3 && num > 0) {
            if (isFloor) {
                var tempNum = Math.floor(Number(parseFloat(num * 10 ** digits + "").toPrecision(16))) / 10 ** digits;
                return parseFloat(tempNum.toFixed(digits)).toString();
            } else {
                return parseFloat(num.toFixed(digits)).toString();
            }
        }

        if (num === "0.00") return num;
        var si = [
            { value: 1, symbol: "" },
            { value: 1e6, symbol: "M" },
            { value: 1e9, symbol: "G" },
            { value: 1e12, symbol: "T" },
            { value: 1e15, symbol: "P" }
        ];
        if (needK) {
            si = [
                { value: 1, symbol: "" },
                { value: 1e3, symbol: "k" },
                { value: 1e6, symbol: "M" },
                { value: 1e9, symbol: "G" },
                { value: 1e12, symbol: "T" },
                { value: 1e15, symbol: "P" }
            ];
        }
        var rx = /\.0+$|(\.[0-9]*[1-9])0+$/;
        var i;
        for (i = si.length - 1; i > 0; i--) {
            if (num >= si[i].value) {
                break;
            }
        }
        let temp = (num / si[i].value).toString();
        if (temp.indexOf(".") > -1) {
            if (digits > 0) temp = temp.substr(0, temp.indexOf(".") + digits + 1);
            else temp = temp.substr(0, temp.indexOf(".") + digits);
        }
        return temp.replace(rx, "$1") + si[i].symbol;
    }

    /**
     * 将区块链中的Wei单位数值转换为普通数值
     * @param value 原始Wei单位的数值字符串
     * @param decimals 代币的小数位数
     * @param point 需要保留的小数位数，默认为0
     * @returns 转换后的数值字符串，如果输入无效则返回0
     */
    public static fromWei(value: any, decimals: number, point = 0) {
        if (!value) {
            return 0;
        }
        let len = value.length - decimals + point;
        if (len <= 0) {
            return 0;
        }
        let temp = value.toString().slice(0, len);
        if (point) {
            let tt = temp.length - point;
            if (tt <= 0) {
                let ttt = "0.";
                for (let index = 0; index < Math.abs(tt); index++) {
                    ttt += "0";
                }
                temp = ttt + temp;
            } else {
                temp = temp.slice(0, temp.length - point) + "." + temp.slice(temp.length - point);
            }
        }
        return temp;
    }

    /**
     * 获取数字的后9位数字，用于处理大数值的显示
     * @param numStr 需要处理的数字字符串
     * @returns 返回数字的后9位，如果输入无效则返回原字符串
     */
    public static getNumberSuffix(numStr: string): string {
        const num = parseInt(numStr, 10);
        if (isNaN(num)) {
            return numStr;
        }
        return (num % 1000000000).toString();
    }
}
