    private getDirectionToTarget(target: Vec2): Vec2 {
        const headPos = this.snake.getCollisionHeadPosition(false);
        const dx = target.x - headPos.x;
        const dy = target.y - headPos.y;
        const direction = new Vec2(dx, dy);

        // 添加角度差判断，避免微小调整
        const angleDiff = Math.abs(direction.getRotation() - this.snake.getCurDir());
        if (angleDiff < 5) {
            // 5度内不调整方向
            var curDir = this.snake.getCurDir();
            var dir = Tool.getAngleToVec(curDir);
            return dir; // 保持原方向
        }

        // 添加零向量检查
        if (direction.length() < 0.1) {
            var curDir = this.snake.getCurDir();
            var dir = Tool.getAngleToVec(curDir);
            return dir; // 保持原方向
        }
        direction.normalize();
        return direction;
    }

    private isInDangerRange(threat: Snake): boolean {
        return MathUtil.getVecDistance(this.snake.getCollisionHeadPosition(false), threat.getCollisionHeadPosition(false)) < this.dangerDistance;
    }

    destroy(): void {
        Laya.timer.clearAll(this);
        this.setTarget(null, EnumMatch.TARGET_TYPE_NULL);
        this.snake = null;
        this.collision = null;
    }
