import SnakeManager from "../snake/SnakeManager";
import FoodManager from "../food/FoodManager";
import Constants from "../../global/config/Constants";
import MatchModel from "../../modules/match/MatchModel";
import HallWebSocket from "../../network/HallWebSocket";
import { com } from "../../network/pb/socket";
import GameAiControl from "./GameAiControl";
import AiSnakeManager from "../snake/AiSnakeManager";

class FrameAiManager {
    private static _instance: FrameAiManager;
    public static getInstance(): FrameAiManager {
        if (!FrameAiManager._instance) {
            FrameAiManager._instance = new FrameAiManager();
        }
        return FrameAiManager._instance;
    }

    private _frameInterval: number = 33;

    /**
     * 客户端帧(可自增)
     */
    private _currentFrame: number = 0;

    isStart: boolean = false;

    public init(): void {
        this.stop();

        this._currentFrame = 0;
    }

    public start(): void {
        Laya.timer.loop(this._frameInterval, this, this.update);
    }

    private stop(): void {
        Laya.timer.clear(this, this.update);
    }
    public end(): void {
        this.stop();
        this.isStart = false;
    }

    private update(): void {
        this._currentFrame++;
        this.executeFrame(this._currentFrame);
    }

    // 执行指定帧的逻辑
    private executeFrame(frame: number, hasConfirmed: boolean = true): void {
        //TODO:: 暂时增加这个isStop()，防止日志太多；
        if (SnakeManager.getInstance().selfSnake && SnakeManager.getInstance().selfSnake.tag == null) {
            return;
        }

        // 3. 更新所有蛇的逻辑
        GameAiControl.update(frame, false, hasConfirmed);

        FoodManager.update(Laya.timer.delta);
        (SnakeManager.getInstance() as AiSnakeManager).update(Laya.timer.delta);
    }

    public get currentFrame(): number {
        return this._currentFrame;
    }

    //============================
    sendAiEnter(): void {
        var cmdId = com.snake.socket.MessageType.MSG_AI_ENTER; //进入AI场
        HallWebSocket.send(cmdId, null);
        // RoomWebSocket.sendData(cmdId, null, false);
    }

    sendAiEnd(kills: number, score: number): void {
        var cmdId = com.snake.socket.MessageType.MSG_AI_END; //AI场结算
        var o = com.snake.socket.CS_AI_END.fromObject({
            kills: kills,
            score: score
        });
        HallWebSocket.send(cmdId, o);
        // RoomWebSocket.sendData(cmdId, o, false);
    }

    onPveEnd() {
        var msgEndBody = new com.snake.socket.SC_BATTLE_END();
        var selfSnake = SnakeManager.getInstance().selfSnake;
        msgEndBody.res = false;
        msgEndBody.roleId = selfSnake.tag.roleId;
        msgEndBody.score = selfSnake.viewSnake.score;
        msgEndBody.kills = selfSnake.tag.kills; //总击杀
        msgEndBody.length = selfSnake.viewSnake.getSkinLength(); //总长度
        msgEndBody.alive = MatchModel.matchCoolDownTime;
        // msgEndBody.alive = Constants.snake.battleCd / 1000 - MatchModel.matchCoolDownTime;
        msgEndBody.rank = selfSnake.rankNum;
        msgEndBody.items = [];
        console.log("onPveEnd", msgEndBody);
        MatchModel.onAiSetMatchEnd(msgEndBody);
    }
}
export default FrameAiManager.getInstance();
