const { regClass } = Laya;
import GameResourceManager from "../../common/GameResourceManager";
import AssetManager from "../../manager/AssetManager";
import { ProfitListItemBase } from "./ProfitListItem.generated";

@regClass('gevXZPT3TWCi4DUrM//uOg==')
export class ProfitListItem extends ProfitListItemBase {
    public constructor() {
        super();
    }

    public createChildren(): void {
        super.createChildren();
    }

    onEnable(): void {}

    onDisable(): void {}

    public set dataSource(value: any) {
        if (!value) return;
        let data = value.split(",");
        // 收益（时间，国家，头像，昵称，货币id,数量,USDT价值,索引）
        super.dataSource = value;
        this.img_flag.skin = GameResourceManager.getCountryIconById(data[1]);
        this.tf_name.text = `${data[3]}`;
        this.PlayerIcon.setHeadSkinAndRoldId(data[2], data[8]);
        const symbolId = parseInt(data[4]);
        if (AssetManager.getTokenData()) {
            const tokenData = AssetManager.getTokenData().find((item) => item.symbolId == symbolId);
            this.tf_income.text = `${data[5]} ${tokenData.symbol}`;
        }

        this.tf_rate.text = `${data[6]}`;

        // 从数据中提取索引信息（添加到最后一个字段）
        const index = data.length > 7 ? parseInt(data[9]) : 0;
        // 根据索引设置背景条纹效果
        this.img_bg.visible = index % 2 === 1;

        const timestamp = data[0];
        // 检查时间戳长度，如果是13位（毫秒）则直接使用，如果是10位（秒）则乘以1000
        const timestampNum = parseInt(timestamp);
        const date = new Date(String(timestampNum).length > 10 ? timestampNum : timestampNum * 1000);
        const month = String(date.getMonth() + 1).padStart(2, "0");
        const day = String(date.getDate()).padStart(2, "0");
        const hours = String(date.getHours()).padStart(2, "0");
        const minutes = String(date.getMinutes()).padStart(2, "0");
        const seconds = String(date.getSeconds()).padStart(2, "0");

        // 添加格式化后的时间字符串，显示为 MM/DD HH:MM:SS 格式
        this.tf_time.text = `${month}/${day} ${hours}:${minutes}:${seconds}`;
    }
}
