import { ItemVo } from "../../../data/vo/pack/ItemVo";
import GetItemService from "../service/GetItemService";
class GetItemDataModel {
    private _list: any[] = [];
    private static _instance: GetItemDataModel;
    public needPop: boolean = true;
    public autoPop: boolean = true;
    public constructor(cls: singClass) {}
    public static getInstance(): GetItemDataModel {
        if (!GetItemDataModel._instance) {
            GetItemDataModel._instance = new GetItemDataModel(new singClass());
        }
        return GetItemDataModel._instance;
    }

    private get service(): any {
        return GetItemService;
    }

    public addItem(itemVo: ItemVo, isAutoShow: boolean = false): void {
        let copyItem: ItemVo = new ItemVo();
        copyItem.id = itemVo.id;
        copyItem.newAddCnt = itemVo.newAddCnt;
        copyItem.m_iLevel = itemVo.m_iLevel;
        copyItem.isLvUp = itemVo.isLvUp;
        copyItem.m_bNew = itemVo.m_bNew;
        this._list.push(copyItem);
        if (isAutoShow) {
            this.service.startShow();
        }
    }

    public addSnakeItem(itemVo: any, isAutoShow: boolean = false): void {
        let copyItem: any = {};
        copyItem.id = itemVo.id;
        copyItem.newAddCnt = itemVo.newAddCnt;
        copyItem.lv = itemVo.lv;
        copyItem.isLvUp = itemVo.isLvUp;
        copyItem.m_bNew = itemVo.m_bNew;
        this._list.push(copyItem);
        if (isAutoShow) {
            this.service.startShow();
        }
    }

    public addItems(value: any[], isAutoShow: boolean = false): void {
        this._list = this._list.concat(value);
        if (isAutoShow) {
            this.service.startShow();
        }
    }

    public hasRemain(): any {
        if (this._list.length > 0) {
            return this._list[0];
        } else {
            return null;
        }
    }

    public get needListener(): boolean {
        return this._list.length >= 2;
    }

    public addConsumeByServer(info: any[]): void {
        this._list.push(info);
    }

    public addConsume(id: any, count: number): void {
        this._list.push([id, count]);
    }

    public getNextItem(): any {
        if (this._list.length > 0) {
            return this._list[0];
        } else {
            return null;
        }
    }

    public getOneItem(): any {
        if (this._list.length > 0) {
            return this._list.shift();
        } else {
            return null;
        }
    }
}
class singClass {}
export default GetItemDataModel.getInstance();
