export class SnakePackageData {
    public m_dicSnakeList: Dictionary;

    public constructor() {
        this.m_dicSnakeList = new Dictionary();
    }

    public initData(data: SnakeDto[]): void {
        this.m_dicSnakeList = new Dictionary();

        let snakeVo: SnakeVo;
        for (let i: number = 0; i < data.length; i++) {
            snakeVo = new SnakeVo();
            var snakeDto: SnakeDto = data[i];

            // snake.initDataByArr(data[i]);
            snakeVo.id = snakeDto.id;

            snakeVo.unkey = snakeDto.unkey;
            snakeVo.attr = snakeDto.attr;
            snakeVo.skin = snakeDto.skin;
            snakeVo.upgrade = snakeDto.upgrade;

            if (snakeVo) this.pushSnake(snakeVo);
        }

        console.log("@@@@@@@@@@@@@@@@@@-----------------------------------------SnakePackageData: ");
    }

    public getCountById(unkey: number, needLv: boolean = true): number {
        return this.getSnakeCountById(unkey, needLv);
    }

    private pushSnake(snake: SnakeVo): void {
        this.m_dicSnakeList.set(snake.unkey, snake);
    }

    private removeSnake(snake: SnakeVo): void {
        this.m_dicSnakeList.remove(snake.unkey);
    }

    /**isAll : 服务器发的是否是背包所有的数量 */
    public updateData(dataArr: SnakeDto[], isAll: boolean = false, needPop: boolean = true): void {
        console.log("updateData: ", dataArr, isAll, needPop);
        let updateIds: any[] = [];
        let dispatchGetSnake: boolean = false;
        let snakeDto: SnakeDto;
        for (let i: number = 0; i < dataArr.length; i++) {
            snakeDto = dataArr[i];

            let snakeVo: SnakeVo = this.m_dicSnakeList.get(snakeDto.unkey);
            if (snakeVo == null) {
                snakeVo = new SnakeVo(snakeDto.id);
                snakeVo.unkey = snakeDto.unkey;
                this.pushSnake(snakeVo);
                // snakeVo.m_bNew = true;
            }
            snakeVo.attr = snakeDto.attr;
            snakeVo.skin = snakeDto.skin;
            snakeVo.upgrade = snakeDto.upgrade;

            updateIds.push(snakeVo.unkey);

            if (GetItemDataModel.needPop && needPop) {
                GetItemDataModel.addSnakeItem(snakeVo);
                dispatchGetSnake = true;
            }
        }
        if (dispatchGetSnake && GetItemDataModel.needPop && GetItemDataModel.autoPop) {
            GetItemService.startShow();
        }
        if (updateIds.length > 0) {
            Signal.event(GameEvent.PACKAGE_UPDATE_ITEM, [updateIds]);
        }
    }

    public getSnakeById(unkey: number): SnakeVo {
        let snake: SnakeVo = this.m_dicSnakeList.get(unkey);
        return snake;
    }

    public getSnakeCountById(unkey: number, needLv: boolean = true): number {
        let snakeVo: SnakeVo = this.getSnakeById(unkey);
        if (snakeVo) {
            return 1;
        } else {
            return 0;
        }
    }
}
