const { regClass } = Laya;
import { ClubListScript } from "../../components/script/ClubListScript";
import { ClubRoomListBase } from "./ClubRoomList.generated";
import { ClubRoomListItem } from "./ClubRoomListItem";

@regClass('yX9EXyl1SSqNAQpsNWVG6w==')
export class ClubRoomList extends ClubRoomListBase {
    /** 子项集合 */
    items: ClubRoomListItem[] = [];
    /** 项目池（用于复用） */
    private itemPool: ClubRoomListItem[] = [];
    /** 是否互斥展开 */
    private exclusive: boolean = true;
    private itemPrefab: Laya.Prefab;

    /** 当前展开的项目ID */
    private expandedItemId: string | null = null;

    onEnable(): void {
        this.removeChildren();
        var clubListScript: ClubListScript = this.getComponent(ClubListScript);
        this.itemPrefab = clubListScript.itemPrefab;
    }

    onDisable(): void {
        // 回收所有项目到对象池
        this.recycleAllItems();
        this.itemPool = [];
    }

    /** 回收所有项目到对象池 */
    private recycleAllItems(): void {
        this.items.forEach((item) => {
            item.removeSelf();
            item.offAll(); // 移除所有事件监听
            item.collapse(); // 确保折叠状态
            item.visible = false; // 隐藏而不是销毁
            this.itemPool.push(item);
        });
        this.items = [];
    }

    public set array(value: any) {
        console.log("ClubRoomList === array", value);
        if (!value) {
            this.recycleAllItems();
            this.updateLayout();
            return;
        }

        // 1. 回收当前不需要的项目
        const currentCount = this.items.length;
        const newCount = value.length;

        if (newCount < currentCount) {
            // 回收多余的项目
            const removeItems = this.items.splice(newCount);
            removeItems.forEach((item) => {
                item.removeSelf();
                item.offAll();
                item.collapse();
                item.visible = false;
                this.itemPool.push(item);
            });
        }

        // 2. 更新现有项目
        for (let i = 0; i < Math.min(currentCount, newCount); i++) {
            const item = this.items[i];
            // 设置数据前检查是否需要展开
            const shouldExpand = this.expandedItemId === value[i][0];
            item.dataSource = value[i];

            // 如果需要展开且当前未展开，则展开
            if (shouldExpand && !item.isExpanded) {
                item.expand();
            }

            // item.dataSource = value[i];
            item.visible = true;
        }

        // 3. 添加新项目
        for (let i = currentCount; i < newCount; i++) {
            this.addItem(value[i]);
        }

        this.updateLayout();
    }

    /** 添加手风琴项 */
    public addItem(data: any): void {
        console.log("ClubRoomList === addItem", data);

        let item: ClubRoomListItem;

        // 尝试从对象池获取
        if (this.itemPool.length > 0) {
            item = this.itemPool.pop()!;
            item.visible = true;
        } else {
            // 创建新项目
            item = this.itemPrefab.create() as ClubRoomListItem;
            this.addChild(item);

            // 设置点击事件（只设置一次）
            // 在点击事件中更新展开状态
            item.on(Laya.Event.CLICK, this, () => {
                if (this.exclusive) {
                    this.items.forEach((i) => {
                        if (i !== item && i.isExpanded) {
                            i.collapse();
                            // 更新展开状态
                            if (i.referralData.id === this.expandedItemId) {
                                this.expandedItemId = null;
                            }
                        }
                    });
                }

                // 更新当前展开的项目ID
                if (item.isExpanded) {
                    this.expandedItemId = item.referralData.id;
                } else {
                    this.expandedItemId = null;
                }

                this.updateLayout();
            });
        }

        // 更新数据
        // 设置数据前检查是否需要展开
        const shouldExpand = this.expandedItemId === data[0];
        item.dataSource = data;

        // 如果需要展开且当前未展开，则展开
        if (shouldExpand && !item.isExpanded) {
            item.expand();
        }

        // item.width = this.width;

        // 添加到当前列表
        this.items.push(item);
    }

    /** 更新布局 */
    public updateLayout(): void {
        let totalHeight = 0;
        this.items.forEach((item) => {
            item.y = totalHeight;
            totalHeight += item.height;
        });
        this.height = totalHeight;

        // 通知父级Panel更新滚动区域
        if (this.parent instanceof Laya.Panel) {
            (this.parent as Laya.Panel).refresh();
        }
    }

    /** 展开指定索引项 */
    public expandAt(index: number): void {
        if (index >= 0 && index < this.items.length) {
            this.items[index].expand();
            this.updateLayout();
        }
    }

    /** 折叠所有项 */
    public collapseAll(): void {
        this.items.forEach((item) => item.collapse());
        this.expandedItemId = null;
        this.updateLayout();
    }
}
