    /**
     * 蛇的运动更新方法
     * @param dt 时间增量（单位：秒），每帧经过的时间
     */
    public move(dt: number): void {
        this.time++;
        this.frameIndex++;

        // speedRate 表示加速状态下的倍率（例如长按按钮时加速），默认为 1
        // 根据 speedRate 执行多次移动（多次循环表示在一个间隔内移动多步）
        for (let rate = 0; rate < this.speedRate; rate++) {
            let dif = this.aimDir - this.dir;

            const maxRotate = this.rotateSpeed * Constants.snake.defaultMoveInterval; //18.15
            if (Math.abs(dif) < maxRotate) {
                // 直接对齐目标角度
                this.dir = this.aimDir;
                // console.log("move:============  当前直接设目标方向", " aimDir" + this.aimDir, " dir：" + this.dir);
            } else {
                dif = (dif + 360) % 360;
                //如果差值大于180，则取负值，表示逆时针旋转
                if (dif > 180) dif -= 360;
                // 限制本次旋转量不超过最大旋转速度
                var rotateAngle = Math.abs(dif) < maxRotate ? dif : maxRotate * (dif > 0 ? 1 : -1);
                this.dir += rotateAngle;
                if (this.dir >= 360) {
                    this.dir -= 360;
                }
                if (this.dir < 0) {
                    this.dir += 360;
                }

                // console.log("第" + this.time + "次", " ============  rotateAngle：" + rotateAngle, " aimDir" + this.aimDir, " dir：" + this.dir);
            }

            // 计算方向向量
            const radian = (this.dir * Math.PI) / 180;
            const dirVector = Vec2.create(Math.cos(radian), Math.sin(radian));

            var targetPos = this.bones[0].add(dirVector.mul(this.speed));

            // 蛇头移动
            this.bones[0].assign(targetPos);

            console.log("TEST==== 移动蛇头坐标：", "第" + this.time + "次", this.bones[0].x, this.bones[0].y, "frameIndex: " + this.frameIndex);
            // console.log(Quick.GetLogTime + "=======loc===== " +" clientLoc1: " + 0, targetPos.x, targetPos.y);
            // 蛇身跟随逻辑

            // for (let i = 1; i < this.bones.length; i++) {
            //     const target = this.bones[i - 1];
            //     const current = this.bones[i];
            //     // const stiffness = 1; // 弹性系数 (0~1)
            //     const stiffness = 0.6; // 弹性系数 (0~1)
            //     const newPos = current.add(target.sub(current).mul(stiffness));
            //     // if(i == 1){
            //     //     console.log(Quick.GetLogTime + "=======loc===== " +"clientLoc1: " + newPos.x, newPos.y);

            //     // }
            //     // const newPos = target;
            //     this.bones[i].x = newPos.x;
            //     this.bones[i].y = newPos.y;
            //     // this.boneVec2s[i].assign(newPos);
            // }
        }
    }
